function normalizeStaticRemoteQueryInput(
  input: StaticRemoteQueryInput | StaticRemoteQueryConfigInput
): StaticRemoteQueryInput {
  if (isStaticRemoteQueryInput(input)) {
    return input
  }

  const entryKey = input.entryPoint ?? input.service
  if (!entryKey) {
    return {}
  }

  return {
    __value: {
      [entryKey]: {
        __args: input.variables ?? {},
        fields: input.fields ?? [],
        isServiceAccess: !!input.service,
      },
    },
  }
}

function isStaticRemoteQueryInput(
  input: StaticRemoteQueryInput | StaticRemoteQueryConfigInput
): input is StaticRemoteQueryInput {
  return Object.prototype.hasOwnProperty.call(input, "__value")
}

function createStaticRemoteQueryResponse({
  query,
  rows,
  sliceRows = false,
}: {
  query: StaticRemoteQueryNode | undefined
  rows: Array<Record<string, unknown>>
  sliceRows?: boolean
}): StaticRemoteQueryResult | Array<Record<string, unknown>> {
  const args = query?.__args

  const skip = args?.skip ?? args?.offset
  const take = args?.take ?? args?.limit

  if (typeof skip !== "number" && typeof take !== "number") {
    return rows
  }

  const normalizedSkip = skip ?? 0
  const normalizedTake = take ?? rows.length

  return {
    rows: sliceRows
      ? rows.slice(normalizedSkip, normalizedSkip + normalizedTake)
      : rows,
    metadata: {
      count: rows.length,
      skip: normalizedSkip,
      take: normalizedTake,
    },
  }
}

function isStaticFieldRequested(
  query: StaticRemoteQueryNode | undefined,
  field: string
): boolean {
  if (!query) {
    return false
  }

  if (isRecord(query[field])) {
    return true
  }

  return parseStaticRemoteFields(query.fields).some(
    (requestedField) =>
      requestedField === field ||
      requestedField === `*${field}` ||
      requestedField.startsWith(`${field}.`) ||
      requestedField.startsWith(`*${field}.`) ||
      requestedField === `${field}.*` ||
      requestedField === `*${field}.*`
  )
}

function isStaticRemoteProductRelationRequested(
  query: StaticRemoteQueryNode | undefined,
  field: string
): boolean {
  if (parseStaticRemoteFields(query?.fields).length === 0) {
    return true
  }

  return isStaticFieldRequested(query, field)
}

function isStaticGraphFieldRequested(
  fields: string[] | undefined,
  field: string
): boolean {
  if (!fields || fields.length === 0) {
    return true
  }

  return fields.some(
    (requestedField) =>
      requestedField === field ||
      requestedField === `*${field}` ||
      requestedField.startsWith(`${field}.`) ||
      requestedField.startsWith(`*${field}.`) ||
      requestedField === `${field}.*` ||
      requestedField === `*${field}.*`
  )
}

function getStaticCurrencyRows(
  currencyQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = currencyQuery?.__args
  const codeFilters = normalizeStringFilter(args?.filters?.code)
  const search = typeof args?.filters?.q === "string" ? args.filters.q : ""
  const normalizedSearch = search.toLowerCase()
  const fields = parseStaticRemoteFields(currencyQuery?.fields)

  const rows = Object.values(defaultCurrencies)
    .map((currency) => ({
      ...currency,
      code: currency.code.toLowerCase(),
      fields,
      filter: args?.filters?.code ?? null,
    }))
    .filter((currency) => {
      if (codeFilters.length > 0 && !codeFilters.includes(currency.code)) {
        return false
      }

      if (!normalizedSearch) {
        return true
      }

      return (
        currency.code.includes(normalizedSearch) ||
        currency.name.toLowerCase().includes(normalizedSearch) ||
        currency.name_plural.toLowerCase().includes(normalizedSearch)
      )
    })

  return applyStaticOrder(rows, args?.order)
}

function applyStaticOrder(
  rows: Array<Record<string, unknown>>,
  order: StaticOrder | undefined
): Array<Record<string, unknown>> {
  const [field, direction] = Object.entries(order ?? {})[0] ?? []
  if (!field || !isStaticOrderDirection(direction)) {
    return rows
  }

  return [...rows].sort((first, second) => {
    const firstValue = first[field]
    const secondValue = second[field]
    if (typeof firstValue !== "string" || typeof secondValue !== "string") {
      return 0
    }

    return direction === "DESC"
      ? secondValue.localeCompare(firstValue)
      : firstValue.localeCompare(secondValue)
  })
}

function isStaticOrderDirection(value: unknown): value is StaticOrderDirection {
  return value === "ASC" || value === "DESC"
}

function getStaticCartRows(
  cartQuery: StaticRemoteQueryNode
): Array<Record<string, unknown>> {
  const args = cartQuery.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  if (
    idFilters.length > 0 &&
    !idFilters.includes(staticCartId)
  ) {
    return []
  }

  const cartOriginalItemTotal = getStaticCartOriginalItemTotal()
  const cartOriginalItemTaxTotal = getStaticCartOriginalItemTaxTotal()
  const cartOriginalItemSubtotal =
    cartOriginalItemTotal - cartOriginalItemTaxTotal
  const cartItemTotal = getStaticCartDiscountedItemTotal()
  const cartItemTaxTotal = getStaticCartDiscountedItemTaxTotal()
  const cartTaxTotal = cartItemTaxTotal + staticCartTaxTotal
  const cartItemSubtotal = cartOriginalItemSubtotal
  const cartShippingTotal = getStaticCartShippingTotal()
  const cartOriginalTotal = cartOriginalItemTotal + cartShippingTotal
  const cartDiscountSubtotal = getStaticCartDiscountSubtotal()
  const cartDiscountTotal = getStaticCartDiscountTotal()
  const cartCreditLineTotal = getStaticCartCreditLineTotal()

  return [
    {
      id: staticCartId,
      email: staticCartEmail,
      customer_id: staticCartCustomerId,
      customer: getStaticCartCustomerRow(),
      completed_at: staticCartCompletedAt,
      created_at: staticCartTimestamp,
      updated_at: staticCartTimestamp,
      billing_address: null,
      billing_address_id: null,
      currency_code: staticCartCurrencyCode,
      credit_line_subtotal: cartCreditLineTotal,
      credit_line_tax_total: 0,
      credit_line_total: cartCreditLineTotal,
      credit_lines: staticCartCreditLines.map((creditLine) => ({
        ...creditLine,
      })),
      discount_subtotal: cartDiscountSubtotal,
      discount_tax_total: roundStaticAmount(
        cartDiscountTotal - cartDiscountSubtotal
      ),
      discount_total: cartDiscountTotal,
      locale: staticCartLocale,
      metadata: staticCartMetadata,
      region: getStaticCartRegionRow(),
      region_id: staticCartRegionId,
      sales_channel_id: staticCartSalesChannelId,
      shipping_address: toStaticCartAddressRow(staticCartShippingAddress),
      shipping_address_id: staticCartShippingAddress?.id ?? null,
      total: getStaticCartTotal(),
      subtotal: cartItemSubtotal,
      tax_total: cartTaxTotal,
      original_total: cartOriginalTotal,
      original_tax_total: cartTaxTotal,
      item_total: cartItemTotal,
      item_subtotal: cartItemSubtotal,
      item_tax_total: cartItemTaxTotal,
      original_item_total: cartOriginalItemTotal,
      original_item_subtotal: cartOriginalItemSubtotal,
      original_item_tax_total: cartOriginalItemTaxTotal,
      shipping_tax_total: 0,
      original_shipping_tax_total: 0,
      original_shipping_total: cartShippingTotal,
      original_shipping_subtotal: cartShippingTotal,
      items: staticCartLineItems.map(toStaticCartLineItemRow),
      promotions: staticCartPromotions.map(toStaticCartPromotionRow),
      shipping_methods: staticCartShippingMethods.map(
        toStaticCartShippingMethodRow
      ),
      ...(staticCartHasPaymentCollection
        ? {
            payment_collection: createStaticPaymentCollection(),
          }
        : {}),
      shipping_total: cartShippingTotal,
      shipping_subtotal: cartShippingTotal,
      fields: parseStaticRemoteFields(cartQuery.fields),
      filter: args?.filters ?? null,
    },
  ]
}

function getStaticCartRegionRow(): Record<string, unknown> | null {
  const region = staticRegions.find(
    (candidate) => candidate.id === staticCartRegionId
  )

  if (region) {
    return {
      automatic_taxes: region.automatic_taxes,
      countries: region.countries,
      currency_code: region.currency_code,
      id: region.id,
      name: region.name,
    }
  }

  if (staticCartRegionId !== "reg_worker_http_proof") {
    return null
  }

  return {
    id: "reg_worker_http_proof",
    name: "Worker Region",
    currency_code: "usd",
    automatic_taxes: true,
    countries: [
      {
        iso_2: "us",
        iso_3: "usa",
        display_name: "United States",
      },
    ],
  }
}

function getStaticCartCustomerRow(): Record<string, unknown> | null {
  const linkedCustomer = staticCartCustomerId
    ? staticCustomers.find((candidate) => candidate.id === staticCartCustomerId)
    : undefined

  if (linkedCustomer) {
    return { ...linkedCustomer }
  }

  if (!staticCartEmail) {
    return null
  }

  const existingCustomer = staticCustomers.find(
    (candidate) => candidate.email === staticCartEmail
  )

  if (existingCustomer) {
    return { ...existingCustomer }
  }

  return {
    id: null,
    email: staticCartEmail,
    first_name: null,
    last_name: null,
    metadata: null,
    has_account: false,
    created_at: staticCartTimestamp,
    updated_at: staticCartTimestamp,
    deleted_at: null,
  }
}

function toStaticCartAddressRow(
  address: StaticCartShippingAddress | null
): Record<string, unknown> | null {
  if (!address) {
    return null
  }

  const { customer_id: customerId, ...row } = address

  return customerId ? { ...row, customer_id: customerId } : row
}

function isStaticCartAutomaticTaxesEnabled(): boolean {
  const region = staticRegions.find(
    (candidate) => candidate.id === staticCartRegionId
  )

  return region?.automatic_taxes ?? true
}

function getStaticTranslationRows(
  translationQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = translationQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const referenceIdFilters = normalizeStringFilter(args?.filters?.reference_id)
  const referenceFilters = normalizeStringFilter(args?.filters?.reference)
  const localeCodeFilters = normalizeStringFilter(args?.filters?.locale_code)

  return staticTranslations.filter((translation) => {
    if (idFilters.length > 0 && !idFilters.includes(translation.id)) {
      return false
    }

    if (
      referenceIdFilters.length > 0 &&
      !referenceIdFilters.includes(translation.reference_id)
    ) {
      return false
    }

    if (
      referenceFilters.length > 0 &&
      !referenceFilters.includes(translation.reference)
    ) {
      return false
    }

    if (
      localeCodeFilters.length > 0 &&
      !localeCodeFilters.includes(translation.locale_code)
    ) {
      return false
    }

    return true
  })
}

function getStaticTranslatableFields(): Record<string, string[]> {
  return {
    product: ["title", "description", "subtitle", "material"],
    product_variant: ["title", "material"],
    product_category: ["name", "description"],
    product_collection: ["title"],
  }
}

function getStaticActiveTranslatableFields(
  entityType: string
): string[] {
  const setting = staticTranslationSettings.find(
    (candidate) => candidate.entity_type === entityType
  )

  return setting?.is_active ? setting.fields : []
}

function getStaticInactiveTranslatableFields(
  entityType: string
): string[] {
  const allFields = getStaticTranslatableFields()[entityType] ?? []
  const activeFields = new Set(getStaticActiveTranslatableFields(entityType))

  return allFields.filter((field) => !activeFields.has(field))
}

function computeStaticTranslatedFieldCount(
  reference: string,
  translations: Record<string, string>
): number {
  return getStaticActiveTranslatableFields(reference).filter((field) => {
    const value = translations[field]
    return value != null && value !== "" && value !== "null"
  }).length
}

function recomputeStaticTranslationFieldCounts(entityTypes: string[]): void {
  const entityTypeSet = new Set(entityTypes)

  staticTranslations = staticTranslations.map((translation) => {
    if (!entityTypeSet.has(translation.reference)) {
      return translation
    }

    return {
      ...translation,
      translated_field_count: computeStaticTranslatedFieldCount(
        translation.reference,
        translation.translations
      ),
    }
  })
}

function getStaticTranslationSettingsRows(
  entityType?: string | null
): StaticTranslationSetting[] {
  return staticTranslationSettings.filter((setting) => {
    return !entityType || setting.entity_type === entityType
  })
}

function createStaticTranslationSettingsResponse(
  url: URL
): Response {
  const entityType = url.searchParams.get("entity_type")
  const fieldsByEntity = getStaticTranslatableFields()
  const rows = getStaticTranslationSettingsRows(entityType)
  const rowByEntity = new Map(rows.map((row) => [row.entity_type, row]))
  const translationSettings: Record<
    string,
    {
      id: string
      fields: string[]
      inactive_fields: string[]
      is_active: boolean
    }
  > = {}

  for (const [currentEntityType, allFields] of Object.entries(fieldsByEntity)) {
    if (entityType && currentEntityType !== entityType) {
      continue
    }

    const setting = rowByEntity.get(currentEntityType)
    if (!setting) {
      continue
    }

    const activeFields = setting.is_active ? setting.fields : []
    translationSettings[currentEntityType] = {
      id: setting.id,
      fields: activeFields,
      inactive_fields: allFields.filter((field) => !activeFields.includes(field)),
      is_active: setting.is_active,
    }
  }

  return createStaticJsonResponse({
    translation_settings: translationSettings,
  })
}

function createStaticTranslationsListResponse(url: URL): Response {
  const rows = getStaticAdminTranslationRows(url)
  const offset = parseStaticIntegerSearchParam(url, "offset", 0)
  const limit = parseStaticIntegerSearchParam(url, "limit", 20)

  return createStaticJsonResponse({
    translations: rows.slice(offset, offset + limit),
    count: rows.length,
    offset,
    limit,
  })
}

function createStaticTranslationsStatisticsResponse(url: URL): Response {
  const locales = url.searchParams.getAll("locales")
  const entityTypes = url.searchParams.getAll("entity_types")

  if (locales.length === 0 || entityTypes.length === 0) {
    return createStaticErrorResponse(
      400,
      "invalid_data",
      "locales and entity_types are required"
    )
  }

  const statistics = Object.fromEntries(
    entityTypes.map((entityType) => {
      const fields = getStaticTranslatableFields()[entityType] ?? []
      const entityCount = getStaticTranslationEntityCount(entityType)
      const expectedPerLocale = entityCount * fields.length
      const byLocale = Object.fromEntries(
        locales.map((locale) => {
          const translated = getStaticTranslatedFieldCountForLocale(
            entityType,
            locale,
            fields
          )

          return [
            locale,
            {
              expected: expectedPerLocale,
              translated,
              missing: expectedPerLocale - translated,
            },
          ]
        })
      )
      const translated = Object.values(byLocale).reduce(
        (sum, localeStats) => sum + localeStats.translated,
        0
      )
      const expected = expectedPerLocale * locales.length

      return [
        entityType,
        {
          expected,
          translated,
          missing: expected - translated,
          by_locale: byLocale,
        },
      ]
    })
  )

  return createStaticJsonResponse({ statistics })
}

function createStaticTranslationEntitiesResponse(url: URL): Response {
  const entityType = url.searchParams.get("type")
  if (!entityType) {
    return createStaticErrorResponse(400, "invalid_data", "type is required")
  }

  const rows = getStaticTranslationEntityRows(entityType)
  const offset = parseStaticIntegerSearchParam(url, "offset", 0)
  const limit = parseStaticIntegerSearchParam(url, "limit", 20)

  return createStaticJsonResponse({
    data: rows.slice(offset, offset + limit),
    count: rows.length,
    offset,
    limit,
  })
}

function createStaticUploadPresignedUrlResponse(
  body: Record<string, unknown>
): Response {
  const mimeType = getStringValue(body, "mime_type") ?? ""
  const parsedMimeType = parseStaticMimeType(mimeType)

  if (!parsedMimeType) {
    return createStaticCodedErrorResponse(
      400,
      "invalid_data",
      `Invalid file type "${mimeType}"`
    )
  }

  staticUploadPresignedSequence += 1

  return createStaticJsonResponse({
    url: "/admin/uploads",
    filename: `upload_worker_http_proof_${staticUploadPresignedSequence}.${parsedMimeType.extension}`,
    originalname: getStringValue(body, "originalname") ?? "",
    mime_type: parsedMimeType.normalized,
    extension: parsedMimeType.extension,
    size: getNumberValue(body, "size") ?? 0,
  })
}

function parseStaticMimeType(
  mimeType: string
): { normalized: string; extension: string } | undefined {
  const normalized = mimeType.trim().toLowerCase()
  const match = normalized.match(/^[^/\s;]+\/([^/\s;]+)(?:;.*)?$/)
  const extension = match?.[1]

  if (!extension) {
    return undefined
  }

  return {
    normalized,
    extension,
  }
}

function getStaticAdminTranslationRows(url: URL): StaticTranslation[] {
  const referenceIdFilters = url.searchParams.getAll("reference_id")
  const referenceFilters = url.searchParams.getAll("reference")
  const localeCodeFilters = url.searchParams.getAll("locale_code")
  const query = url.searchParams.get("q")?.toLowerCase() ?? ""

  return staticTranslations.filter((translation) => {
    if (
      referenceIdFilters.length > 0 &&
      !referenceIdFilters.includes(translation.reference_id)
    ) {
      return false
    }

    if (
      referenceFilters.length > 0 &&
      !referenceFilters.includes(translation.reference)
    ) {
      return false
    }

    if (
      localeCodeFilters.length > 0 &&
      !localeCodeFilters.includes(translation.locale_code)
    ) {
      return false
    }

    if (!query) {
      return true
    }

    return JSON.stringify(translation.translations)
      .toLowerCase()
      .includes(query)
  })
}

function getStaticTranslationEntityCount(entityType: string): number {
  if (entityType === "product") {
    return staticProducts.filter((product) => !product.deleted_at).length
  }

  if (entityType === "product_variant") {
    return staticProducts
      .filter((product) => !product.deleted_at)
      .flatMap((product) => product.variants).length
  }

  if (entityType === "product_category") {
    return staticProductCategories.length
  }

  if (entityType === "product_collection") {
    return staticProductCollections.length
  }

  return 0
}

function getStaticTranslatedFieldCountForLocale(
  entityType: string,
  locale: string,
  fields: string[]
): number {
  if (fields.length === 0) {
    return 0
  }

  return staticTranslations
    .filter(
      (translation) =>
        translation.reference === entityType && translation.locale_code === locale
    )
    .reduce((sum, translation) => {
      return (
        sum +
        fields.filter((field) => {
          const value = translation.translations[field]
          return value != null && value !== "" && value !== "null"
        }).length
      )
    }, 0)
}

function getStaticTranslationEntityRows(
  entityType: string
): Array<Record<string, unknown>> {
  if (entityType === "product") {
    return staticProducts
      .filter((product) => !product.deleted_at)
      .map((product) => ({
        id: product.id,
        title: product.title,
        description: product.description,
        subtitle: product.subtitle,
        material: product.material,
      }))
  }

  if (entityType === "product_variant") {
    return staticProducts
      .filter((product) => !product.deleted_at)
      .flatMap((product) =>
        product.variants.map((variant) => ({
          id: variant.id,
          title: variant.title,
        }))
      )
  }

  return []
}

function parseStaticIntegerSearchParam(
  url: URL,
  name: string,
  fallback: number
): number {
  const value = url.searchParams.get(name)
  if (value === null) {
    return fallback
  }

  const parsed = Number(value)
  return Number.isInteger(parsed) && parsed >= 0 ? parsed : fallback
}

function batchStaticTranslationSettingsFromBody(body: unknown): {
  created: StaticTranslationSetting[]
  updated: StaticTranslationSetting[]
  deleted: string[]
} | Response {
  if (!isRecord(body)) {
    return {
      created: [],
      updated: [],
      deleted: [],
    }
  }

  const createInput = Array.isArray(body.create) ? body.create : []
  const updateInput = Array.isArray(body.update) ? body.update : []
  const deleteIds = normalizeStringFilter(body.delete)
  const validationMessage = getStaticTranslationSettingsValidationMessage([
    ...createInput,
    ...updateInput,
  ])

  if (validationMessage) {
    return createStaticErrorResponse(400, "invalid_data", validationMessage)
  }

  const timestamp = new Date(Date.UTC(2026, 5, 21, 0, 47, 0)).toISOString()
  const created = createStaticTranslationSettings(createInput, timestamp)
  const updated = updateStaticTranslationSettings(updateInput, timestamp)

  if (deleteIds.length > 0) {
    staticTranslationSettings = staticTranslationSettings.filter(
      (setting) => !deleteIds.includes(setting.id)
    )
  }

  return {
    created,
    updated,
    deleted: deleteIds,
  }
}

function getStaticTranslationSettingsValidationMessage(
  input: unknown[]
): string | undefined {
  const fieldsByEntity = getStaticTranslatableFields()
  const invalidSettings = input.flatMap((candidate): string[] => {
    if (!isRecord(candidate)) {
      return []
    }

    const entityType =
      getStringValue(candidate, "entity_type") ??
      getStaticTranslationSettingEntityType(getStringValue(candidate, "id"))

    if (!entityType) {
      return []
    }

    const allowedFields = fieldsByEntity[entityType]
    if (!allowedFields) {
      return [`- ${entityType} is not a translatable entity`]
    }

    const fields = normalizeStringFilter(candidate.fields)
    const invalidFields = fields.filter((field) => !allowedFields.includes(field))

    if (invalidFields.length === 0) {
      return []
    }

    return [
      `- ${entityType} doesn't have the following fields set as translatable: ${invalidFields.join(
        ", "
      )}`,
    ]
  })

  if (invalidSettings.length === 0) {
    return undefined
  }

  return `Invalid translation settings:\n${invalidSettings.join("\n")}`
}

function createStaticTranslationSettings(
  input: unknown[],
  timestamp: string
): StaticTranslationSetting[] {
  const created = input.flatMap((candidate): StaticTranslationSetting[] => {
    if (!isRecord(candidate)) {
      return []
    }

    const entityType = getStringValue(candidate, "entity_type")
    const fields = normalizeStringFilter(candidate.fields)

    if (!entityType) {
      return []
    }

    const setting: StaticTranslationSetting = {
      id: `trset_worker_http_proof_${++staticTranslationSettingSequence}`,
      entity_type: entityType,
      fields,
      is_active: getBooleanValue(candidate, "is_active") ?? true,
      created_at: timestamp,
      updated_at: timestamp,
      deleted_at: null,
    }

    return [setting]
  })

  const createdEntityTypes = created.map((setting) => setting.entity_type)
  staticTranslationSettings = [
    ...staticTranslationSettings.filter(
      (setting) => !createdEntityTypes.includes(setting.entity_type)
    ),
    ...created,
  ]
  recomputeStaticTranslationFieldCounts(createdEntityTypes)

  return created
}

function updateStaticTranslationSettings(
  input: unknown[],
  timestamp: string
): StaticTranslationSetting[] {
  const updated: StaticTranslationSetting[] = []
  const updatedEntityTypes: string[] = []

  for (const candidate of input) {
    if (!isRecord(candidate)) {
      continue
    }

    const id = getStringValue(candidate, "id")
    if (!id) {
      continue
    }

    staticTranslationSettings = staticTranslationSettings.map((setting) => {
      if (setting.id !== id) {
        return setting
      }

      const next: StaticTranslationSetting = {
        ...setting,
        entity_type: getStringValue(candidate, "entity_type") ?? setting.entity_type,
        fields: Object.prototype.hasOwnProperty.call(candidate, "fields")
          ? normalizeStringFilter(candidate.fields)
          : setting.fields,
        is_active:
          getBooleanValue(candidate, "is_active") ?? setting.is_active,
        updated_at: timestamp,
      }

      updated.push(next)
      updatedEntityTypes.push(next.entity_type)
      return next
    })
  }

  recomputeStaticTranslationFieldCounts(updatedEntityTypes)

  return updated
}

function getStaticTranslationSettingEntityType(
  id: string | undefined
): string | undefined {
  if (!id) {
    return undefined
  }

  return staticTranslationSettings.find((setting) => setting.id === id)
    ?.entity_type
}

function getStaticLocaleRows(
  input: StaticQueryGraphInput
): Array<Record<string, unknown>> {
  const codeFilters = normalizeStringFilter(input.filters?.code)
  const search =
    typeof input.filters?.q === "string" ? input.filters.q.toLowerCase() : ""

  return staticDefaultLocales.filter((locale) => {
    if (codeFilters.length > 0 && !codeFilters.includes(locale.code)) {
      return false
    }

    if (!search) {
      return true
    }

    return (
      locale.code.toLowerCase().includes(search) ||
      locale.name.toLowerCase().includes(search)
    )
  })
}

function getStaticProductCollectionRows(
  collectionQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = collectionQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const titleFilters = normalizeStringFilter(args?.filters?.title)
  const handleFilters = normalizeStringFilter(args?.filters?.handle)
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""

  return staticProductCollections
    .filter((collection) => {
      if (idFilters.length > 0 && !idFilters.includes(collection.id)) {
        return false
      }

      if (titleFilters.length > 0 && !titleFilters.includes(collection.title)) {
        return false
      }

      if (
        handleFilters.length > 0 &&
        !handleFilters.includes(collection.handle)
      ) {
        return false
      }

      if (!search) {
        return true
      }

      return (
        collection.title.toLowerCase().includes(search) ||
        collection.handle.toLowerCase().includes(search)
      )
    })
    .map((collection) => {
      if (!isStaticFieldRequested(collectionQuery, "products")) {
        return collection
      }

      return {
        ...collection,
        products: getStaticProductsForCollection(collection.id),
      }
    })
}

function getStaticProductCategoryGraphResult(
  input: StaticQueryGraphInput
): StaticQueryGraphResult {
  const filters = input.filters
  const idFilters = normalizeStringFilter(filters?.id)
  const handleFilters = normalizeStringFilter(filters?.handle)
  const descriptionFilters = normalizeStringFilter(filters?.description)
  const parentCategoryFilter = normalizeProductCategoryParentFilter(
    filters?.parent_category_id
  )
  const isInternalFilter = normalizeBooleanValue(filters?.is_internal)
  const isActiveFilter = normalizeBooleanValue(filters?.is_active)
  const search =
    typeof filters?.q === "string" ? filters.q.toLowerCase() : ""

  const rows = staticProductCategories
    .filter((category) => {
      if (idFilters.length > 0 && !idFilters.includes(category.id)) {
        return false
      }

      if (
        handleFilters.length > 0 &&
        !handleFilters.includes(category.handle)
      ) {
        return false
      }

      if (
        descriptionFilters.length > 0 &&
        !descriptionFilters.includes(category.description)
      ) {
        return false
      }

      if (parentCategoryFilter.active) {
        if (parentCategoryFilter.includeRoot && category.parent_category_id) {
          return false
        }

        if (
          parentCategoryFilter.ids.length > 0 &&
          !parentCategoryFilter.ids.includes(category.parent_category_id ?? "")
        ) {
          return false
        }
      }

      if (
        typeof isInternalFilter === "boolean" &&
        category.is_internal !== isInternalFilter
      ) {
        return false
      }

      if (
        typeof isActiveFilter === "boolean" &&
        category.is_active !== isActiveFilter
      ) {
        return false
      }

      if (!search) {
        return true
      }

      return (
        category.name.toLowerCase().includes(search) ||
        category.handle.toLowerCase().includes(search)
      )
    })
    .sort((left, right) => compareStaticProductCategories(left, right, input))
    .map((category) => toStaticProductCategoryRow(category))

  const skip = input.pagination?.skip ?? 0
  const take = input.pagination?.take ?? rows.length

  return {
    data: rows.slice(skip, skip + take),
    metadata: {
      count: rows.length,
      skip,
      take,
    },
  }
}

function compareStaticProductCategories(
  left: StaticProductCategory,
  right: StaticProductCategory,
  input: StaticQueryGraphInput
): number {
  const nameOrder = input.order?.name ?? input.pagination?.order?.name
  if (nameOrder === "ASC") {
    return left.name.localeCompare(right.name)
  }

  if (nameOrder === "DESC") {
    return right.name.localeCompare(left.name)
  }

  if (left.parent_category_id === right.parent_category_id) {
    return left.rank - right.rank
  }

  return left.created_at.localeCompare(right.created_at)
}

function toStaticProductCategoryRow(
  category: StaticProductCategory,
  options: {
    includeChildren?: boolean
    includeParent?: boolean
  } = {}
): Record<string, unknown> {
  const includeChildren = options.includeChildren ?? true
  const includeParent = options.includeParent ?? true
  const row: Record<string, unknown> = {
    ...category,
    parent_category: null,
    category_children: [],
  }

  if (includeParent && category.parent_category_id) {
    const parent = getStaticProductCategoryById(category.parent_category_id)
    row.parent_category = parent
      ? toStaticProductCategoryRow(parent, {
          includeChildren: false,
          includeParent: true,
        })
      : null
  }

  if (includeChildren) {
    row.category_children = getStaticProductCategoryChildren(category.id).map(
      (child) =>
        toStaticProductCategoryRow(child, {
          includeChildren: true,
          includeParent: false,
        })
    )
  }

  row.products = getStaticProductsForCategory(category.id)

  return row
}

function getStaticProductCategoryById(
  categoryId: string
): StaticProductCategory | undefined {
  return staticProductCategories.find((category) => category.id === categoryId)
}

function getStaticProductCategoryChildren(
  categoryId: string
): StaticProductCategory[] {
  return staticProductCategories
    .filter((category) => category.parent_category_id === categoryId)
    .sort((left, right) => left.rank - right.rank)
}

function getStaticProductsForCategory(
  categoryId: string
): Array<Record<string, unknown>> {
  const productIds = new Set(
    staticProductCategoryProductLinks
      .filter((link) => link.category_id === categoryId)
      .map((link) => link.product_id)
  )

  return staticProducts.filter((product) => productIds.has(product.id))
}

function normalizeProductCategoryParentFilter(value: unknown): {
  active: boolean
  includeRoot: boolean
  ids: string[]
} {
  if (typeof value === "undefined") {
    return {
      active: false,
      includeRoot: false,
      ids: [],
    }
  }

  const values = Array.isArray(value) ? value : [value]
  const ids = values.filter(
    (candidate): candidate is string =>
      typeof candidate === "string" && candidate !== "null"
  )

  return {
    active: true,
    includeRoot: values.some(
      (candidate) => candidate === null || candidate === "null"
    ),
    ids,
  }
}

function normalizeBooleanValue(value: unknown): boolean | undefined {
  if (typeof value === "boolean") {
    return value
  }

  if (value === "true") {
    return true
  }

  if (value === "false") {
    return false
  }

  return undefined
}

function getStaticProductsForCollection(
  collectionId: string
): Array<Record<string, unknown>> {
  const productIds = new Set(
    staticProductCollectionProductLinks
      .filter((link) => link.collection_id === collectionId)
      .map((link) => link.product_id)
  )

  return staticProducts
    .filter((product) => productIds.has(product.id))
    .map((product) => ({
      ...product,
      collection_id: collectionId,
    }))
}

function getStaticProductTagRows(
  productTagQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = productTagQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const valueFilters = normalizeStringFilter(args?.filters?.value)
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""

  return staticProductTags.filter((tag) => {
    if (idFilters.length > 0 && !idFilters.includes(tag.id)) {
      return false
    }

    if (valueFilters.length > 0 && !valueFilters.includes(tag.value)) {
      return false
    }

    if (!search) {
      return true
    }

    return tag.value.toLowerCase().includes(search)
  })
}

function getStaticRefundReasonRows(
  refundReasonQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = refundReasonQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const labelFilters = normalizeStringFilter(args?.filters?.label)
  const codeFilters = normalizeStringFilter(args?.filters?.code)
  const descriptionFilters = normalizeStringFilter(args?.filters?.description)
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""

  return staticRefundReasons.filter((reason) => {
    if (idFilters.length > 0 && !idFilters.includes(reason.id)) {
      return false
    }

    if (labelFilters.length > 0 && !labelFilters.includes(reason.label)) {
      return false
    }

    if (codeFilters.length > 0 && !codeFilters.includes(reason.code)) {
      return false
    }

    if (
      descriptionFilters.length > 0 &&
      !descriptionFilters.includes(reason.description ?? "")
    ) {
      return false
    }

    if (!search) {
      return true
    }

    return (
      reason.label.toLowerCase().includes(search) ||
      reason.code.toLowerCase().includes(search) ||
      (reason.description?.toLowerCase().includes(search) ?? false)
    )
  })
}

function getStaticProductTypeRows(
  productTypeQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = productTypeQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const valueFilters = normalizeStringFilter(args?.filters?.value)
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""

  return staticProductTypes.filter((type) => {
    if (idFilters.length > 0 && !idFilters.includes(type.id)) {
      return false
    }

    if (valueFilters.length > 0 && !valueFilters.includes(type.value)) {
      return false
    }

    if (!search) {
      return true
    }

    return type.value.toLowerCase().includes(search)
  })
}

function getStaticProductRows(
  productQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = productQuery?.__args
  const idFilter = getStaticStringFilter(args?.filters?.id)
  const statusFilter = getStaticStringFilter(args?.filters?.status)
  const collectionIdFilter = getStaticStringFilter(args?.filters?.collection_id)
  const typeIdFilter = getStaticStringFilter(args?.filters?.type_id)
  const externalIdFilter = getStaticStringFilter(args?.filters?.external_id)
  const handleFilter = getStaticStringFilter(args?.filters?.handle)
  const titleFilter = getStaticStringFilter(args?.filters?.title)
  const giftcardFilter = getStaticBooleanFilter(args?.filters?.is_giftcard)
  const withDeleted = args?.filters?.deleted_at !== undefined
  const search = getStaticSearchFilter(args?.filters?.q)
  const categoryIdFilters = getStaticProductCategoryFilterIds(args?.filters)
  const tagIdFilters = getStaticProductTagFilterIds(args?.filters)
  const variantOptionFilter = getStaticVariantOptionFilter(args?.filters)
  const variantFieldFilter = getStaticVariantFieldFilter(args?.filters)
  const variantIdFilter = getStaticProductVariantIdFilter(args?.filters)
  const salesChannelIdFilters = getStaticSalesChannelFilterIds(args?.filters)
  const priceListIdFilters = getStaticProductPriceListFilterIds(args?.filters)

  const rows = staticProducts
    .filter((product) => {
      if (!withDeleted && product.deleted_at) {
        return false
      }

      if (withDeleted && !product.deleted_at) {
        return false
      }

      if (idFilter.present && !idFilter.ids.includes(product.id)) {
        return false
      }

      if (
        statusFilter.ids.length > 0 &&
        !statusFilter.ids.includes(product.status)
      ) {
        return false
      }

      if (search && !matchesStaticProductSearch(product, search)) {
        return false
      }

      if (
        collectionIdFilter.ids.length > 0 &&
        !collectionIdFilter.ids.includes(product.collection_id ?? "") &&
        !staticProductCollectionProductLinks.some(
          (link) =>
            link.product_id === product.id &&
            collectionIdFilter.ids.includes(link.collection_id)
        )
      ) {
        return false
      }

      if (
        typeIdFilter.ids.length > 0 &&
        !typeIdFilter.ids.includes(product.type_id ?? "")
      ) {
        return false
      }

      if (
        externalIdFilter.ids.length > 0 &&
        !externalIdFilter.ids.includes(product.external_id ?? "")
      ) {
        return false
      }

      if (
        handleFilter.ids.length > 0 &&
        !handleFilter.ids.includes(product.handle)
      ) {
        return false
      }

      if (
        titleFilter.ids.length > 0 &&
        !titleFilter.ids.includes(product.title)
      ) {
        return false
      }

      if (
        giftcardFilter !== undefined &&
        product.is_giftcard !== giftcardFilter
      ) {
        return false
      }

      if (
        tagIdFilters.length > 0 &&
        !product.tags.some((tag) => tagIdFilters.includes(tag.id))
      ) {
        return false
      }

      if (
        variantOptionFilter.present &&
        !matchesStaticVariantOptionFilter(product, variantOptionFilter)
      ) {
        return false
      }

      if (
        variantFieldFilter.present &&
        !matchesStaticVariantFieldFilter(product, variantFieldFilter)
      ) {
        return false
      }

      if (
        variantIdFilter.present &&
        !matchesStaticVariantIdFilter(product, variantIdFilter)
      ) {
        return false
      }

      if (
        categoryIdFilters.length > 0 &&
        !staticProductCategoryProductLinks.some(
          (link) =>
            link.product_id === product.id &&
            categoryIdFilters.includes(link.category_id)
        )
      ) {
        return false
      }

      if (
        salesChannelIdFilters.length > 0 &&
        !isStaticProductInSalesChannel(product.id, salesChannelIdFilters)
      ) {
        return false
      }

      if (
        priceListIdFilters.length > 0 &&
        !isStaticProductInPriceLists(product, priceListIdFilters)
      ) {
        return false
      }

      return true
    })

  return applyStaticProductOrder(rows, args?.order).map((product) => {
    const row: Record<string, unknown> = {
      ...product,
      weight: toStaticProductDimensionResponseValue(product.weight),
      length: toStaticProductDimensionResponseValue(product.length),
      height: toStaticProductDimensionResponseValue(product.height),
      width: toStaticProductDimensionResponseValue(product.width),
      categories: getStaticCategoriesForProduct(product.id),
      sales_channels: getStaticSalesChannelsForProduct(product.id),
      variants: product.variants.map(toStaticProductVariantRow),
      fields: parseStaticRemoteFields(productQuery?.fields),
      filter: args?.filters ?? null,
    }

    if (isStaticRemoteProductRelationRequested(productQuery, "collection")) {
      row.collection = getStaticCollectionForProduct(product)
    }

    if (isStaticRemoteProductRelationRequested(productQuery, "type")) {
      row.type = getStaticTypeForProduct(product) ?? {}
    }

    if (
      isStaticRemoteProductRelationRequested(productQuery, "shipping_profile")
    ) {
      row.shipping_profile = getStaticShippingProfileForProduct(product)
    }

    return row
  })
}

function getStaticCategoriesForProduct(
  productId: string
): Array<Record<string, unknown>> {
  const categoryIds = new Set(
    staticProductCategoryProductLinks
      .filter((link) => link.product_id === productId)
      .map((link) => link.category_id)
  )

  return staticProductCategories
    .filter((category) => categoryIds.has(category.id))
    .map((category) =>
      toStaticProductCategoryRow(category, {
        includeChildren: false,
        includeParent: false,
      })
    )
}

function getStaticProductCategoryFilterIds(value: unknown): string[] {
  if (Array.isArray(value)) {
    return [
      ...new Set(value.flatMap((candidate) =>
        getStaticProductCategoryFilterIds(candidate)
      )),
    ]
  }

  if (!isRecord(value)) {
    return []
  }

  const ids: string[] = []

  for (const [key, candidate] of Object.entries(value)) {
    if (key === "category_id") {
      ids.push(
        ...normalizeStringFilter(candidate),
        ...normalizeStringOperatorFilter(candidate)
      )
      continue
    }

    if (key === "categories" && isRecord(candidate)) {
      ids.push(
        ...normalizeStringFilter(candidate.id),
        ...normalizeStringOperatorFilter(candidate.id)
      )
      continue
    }

    ids.push(...getStaticProductCategoryFilterIds(candidate))
  }

  return [...new Set(ids)]
}

function getStaticProductTagFilterIds(value: unknown): string[] {
  if (Array.isArray(value)) {
    return [
      ...new Set(value.flatMap((candidate) =>
        getStaticProductTagFilterIds(candidate)
      )),
    ]
  }

  if (!isRecord(value)) {
    return []
  }

  const ids: string[] = []

  for (const [key, candidate] of Object.entries(value)) {
    if (key === "tag_id") {
      ids.push(
        ...normalizeStringFilter(candidate),
        ...normalizeStringOperatorFilter(candidate)
      )
      continue
    }

    if ((key === "tag" || key === "tags") && isRecord(candidate)) {
      ids.push(
        ...normalizeStringFilter(candidate.id),
        ...normalizeStringOperatorFilter(candidate.id)
      )
      continue
    }

    ids.push(...getStaticProductTagFilterIds(candidate))
  }

  return [...new Set(ids)]
}

type StaticVariantOptionFilter = {
  optionIds: string[]
  values: string[]
  present: boolean
}

type StaticVariantFieldKey = "ean" | "upc" | "barcode"

type StaticVariantFieldFilter = {
  values: Record<StaticVariantFieldKey, string[]>
  present: boolean
}

function getStaticVariantOptionFilter(
  value: unknown
): StaticVariantOptionFilter {
  if (Array.isArray(value)) {
    return mergeStaticVariantOptionFilters(
      value.map(getStaticVariantOptionFilter)
    )
  }

  if (!isRecord(value)) {
    return {
      optionIds: [],
      values: [],
      present: false,
    }
  }

  const nestedFilters: StaticVariantOptionFilter[] = []
  let optionIds: string[] = []
  let values: string[] = []
  let present = false

  for (const [key, candidate] of Object.entries(value)) {
    if (key === "options" && isRecord(candidate)) {
      optionIds = [
        ...optionIds,
        ...normalizeStringFilter(candidate.option_id),
        ...normalizeStringOperatorFilter(candidate.option_id),
      ]
      values = [
        ...values,
        ...normalizeStringFilter(candidate.value),
        ...normalizeStringOperatorFilter(candidate.value),
      ]
      present = true
      continue
    }

    nestedFilters.push(getStaticVariantOptionFilter(candidate))
  }

  return mergeStaticVariantOptionFilters([
    {
      optionIds,
      values,
      present,
    },
    ...nestedFilters,
  ])
}

function mergeStaticVariantOptionFilters(
  filters: StaticVariantOptionFilter[]
): StaticVariantOptionFilter {
  return {
    optionIds: [...new Set(filters.flatMap((filter) => filter.optionIds))],
    values: [...new Set(filters.flatMap((filter) => filter.values))],
    present: filters.some((filter) => filter.present),
  }
}

function matchesStaticVariantOptionFilter(
  product: StaticProduct,
  filter: StaticVariantOptionFilter
): boolean {
  return product.variants.some((variant) =>
    variant.options.some((option) => {
      if (
        filter.optionIds.length > 0 &&
        !filter.optionIds.includes(option.option_id)
      ) {
        return false
      }

      if (filter.values.length > 0 && !filter.values.includes(option.value)) {
        return false
      }

      return true
    })
  )
}

function getStaticSalesChannelFilterIds(value: unknown): string[] {
  if (Array.isArray(value)) {
    return [
      ...new Set(value.flatMap((candidate) =>
        getStaticSalesChannelFilterIds(candidate)
      )),
    ]
  }

  if (!isRecord(value)) {
    return []
  }

  const ids: string[] = []

  for (const [key, candidate] of Object.entries(value)) {
    if (key === "sales_channel_id") {
      ids.push(
        ...normalizeStringFilter(candidate),
        ...normalizeStringOperatorFilter(candidate)
      )
      continue
    }

    if (
      (key === "sales_channel" || key === "sales_channels") &&
      isRecord(candidate)
    ) {
      ids.push(
        ...normalizeStringFilter(candidate.id),
        ...normalizeStringOperatorFilter(candidate.id)
      )
      continue
    }

    ids.push(...getStaticSalesChannelFilterIds(candidate))
  }

  return [...new Set(ids)]
}

function getStaticProductPriceListFilterIds(value: unknown): string[] {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value.flatMap((candidate) =>
          getStaticProductPriceListFilterIds(candidate)
        )
      ),
    ]
  }

  if (!isRecord(value)) {
    return []
  }

  const ids: string[] = []

  for (const [key, candidate] of Object.entries(value)) {
    if (key === "price_list_id") {
      ids.push(
        ...normalizeStringFilter(candidate),
        ...normalizeStringOperatorFilter(candidate)
      )
      continue
    }

    if (
      (key === "price_list" || key === "price_lists") &&
      isRecord(candidate)
    ) {
      ids.push(
        ...normalizeStringFilter(candidate.id),
        ...normalizeStringOperatorFilter(candidate.id)
      )
      continue
    }

    ids.push(...getStaticProductPriceListFilterIds(candidate))
  }

  return [...new Set(ids)]
}

function isStaticProductInPriceLists(
  product: StaticProduct,
  priceListIds: string[]
): boolean {
  const variantIds = new Set(product.variants.map((variant) => variant.id))

  return staticPriceLists.some(
    (priceList) =>
      priceListIds.includes(priceList.id) &&
      !priceList.deleted_at &&
      priceList.prices.some(
        (price) => !price.deleted_at && variantIds.has(price.variant_id)
      )
  )
}

type StaticStringFilter = {
  ids: string[]
  present: boolean
}

function getStaticStringFilter(value: unknown): StaticStringFilter {
  return {
    ids: [
      ...new Set([
        ...normalizeStringFilter(value),
        ...normalizeStringOperatorFilter(value),
      ]),
    ],
    present: value !== undefined,
  }
}

function getStaticBooleanFilter(value: unknown): boolean | undefined {
  if (typeof value === "boolean") {
    return value
  }

  if (typeof value === "string") {
    if (value === "true") {
      return true
    }

    if (value === "false") {
      return false
    }
  }

  return undefined
}

function getStaticSearchFilter(value: unknown): string | undefined {
  return typeof value === "string" && value.trim().length > 0
    ? value.toLowerCase()
    : undefined
}

function matchesStaticProductSearch(
  product: StaticProduct,
  search: string
): boolean {
  return (
    product.title.toLowerCase().includes(search) ||
    product.handle.toLowerCase().includes(search) ||
    (product.description?.toLowerCase().includes(search) ?? false)
  )
}

function matchesStaticProductVariantSearch(
  variant: StaticProductVariant,
  search: string
): boolean {
  return (
    variant.title.toLowerCase().includes(search) ||
    (variant.sku?.toLowerCase().includes(search) ?? false) ||
    (variant.ean?.toLowerCase().includes(search) ?? false) ||
    (variant.upc?.toLowerCase().includes(search) ?? false) ||
    (variant.barcode?.toLowerCase().includes(search) ?? false)
  )
}

function getStaticVariantFieldFilter(value: unknown): StaticVariantFieldFilter {
  const emptyFilter: StaticVariantFieldFilter = {
    values: {
      ean: [],
      upc: [],
      barcode: [],
    },
    present: false,
  }

  if (Array.isArray(value)) {
    return mergeStaticVariantFieldFilters(
      value.map(getStaticVariantFieldFilter)
    )
  }

  if (!isRecord(value)) {
    return emptyFilter
  }

  const nestedFilters: StaticVariantFieldFilter[] = []
  const directValues: StaticVariantFieldFilter = emptyFilter

  for (const [key, candidate] of Object.entries(value)) {
    if ((key === "variant" || key === "variants") && isRecord(candidate)) {
      nestedFilters.push(getStaticVariantFieldFilter(candidate))
      continue
    }

    if (isStaticVariantFieldKey(key)) {
      directValues.values[key] = [
        ...directValues.values[key],
        ...normalizeStringFilter(candidate),
        ...normalizeStringOperatorFilter(candidate),
      ]
      directValues.present = true
      continue
    }

    nestedFilters.push(getStaticVariantFieldFilter(candidate))
  }

  return mergeStaticVariantFieldFilters([directValues, ...nestedFilters])
}

function mergeStaticVariantFieldFilters(
  filters: StaticVariantFieldFilter[]
): StaticVariantFieldFilter {
  return {
    values: {
      ean: [...new Set(filters.flatMap((filter) => filter.values.ean))],
      upc: [...new Set(filters.flatMap((filter) => filter.values.upc))],
      barcode: [
        ...new Set(filters.flatMap((filter) => filter.values.barcode)),
      ],
    },
    present: filters.some((filter) => filter.present),
  }
}

function isStaticVariantFieldKey(key: string): key is StaticVariantFieldKey {
  return key === "ean" || key === "upc" || key === "barcode"
}

function matchesStaticVariantFieldFilter(
  product: StaticProduct,
  filter: StaticVariantFieldFilter
): boolean {
  return product.variants.some((variant) => {
    const keys: StaticVariantFieldKey[] = ["ean", "upc", "barcode"]

    for (const key of keys) {
      const values = filter.values[key]
      if (values.length === 0) {
        continue
      }

      if (!values.includes(variant[key] ?? "")) {
        return false
      }
    }

    return true
  })
}

function getStaticProductVariantIdFilter(value: unknown): StaticStringFilter {
  if (Array.isArray(value)) {
    return mergeStaticStringFilters(value.map(getStaticProductVariantIdFilter))
  }

  if (!isRecord(value)) {
    return {
      ids: [],
      present: false,
    }
  }

  const filters: StaticStringFilter[] = []

  for (const [key, candidate] of Object.entries(value)) {
    if ((key === "variant" || key === "variants") && isRecord(candidate)) {
      filters.push(getStaticStringFilter(candidate.id))
      continue
    }

    filters.push(getStaticProductVariantIdFilter(candidate))
  }

  return mergeStaticStringFilters(filters)
}

function mergeStaticStringFilters(
  filters: StaticStringFilter[]
): StaticStringFilter {
  return {
    ids: [...new Set(filters.flatMap((filter) => filter.ids))],
    present: filters.some((filter) => filter.present),
  }
}

function matchesStaticVariantIdFilter(
  product: StaticProduct,
  filter: StaticStringFilter
): boolean {
  return product.variants.some((variant) => filter.ids.includes(variant.id))
}

function applyStaticProductOrder(
  products: StaticProduct[],
  order: StaticOrder | undefined
): StaticProduct[] {
  const idOrder = getStaticOrderDirection(order, ["id"])
  if (idOrder) {
    return [...products].sort((first, second) =>
      compareStaticStrings(first.id, second.id, idOrder)
    )
  }

  const variantTitleOrder = getStaticOrderDirection(order, [
    "variants",
    "title",
  ])
  if (variantTitleOrder) {
    return [...products].sort((first, second) =>
      compareStaticStrings(
        first.variants[0]?.title ?? "",
        second.variants[0]?.title ?? "",
        variantTitleOrder
      )
    )
  }

  return products
}

function isStaticHandleOnlyProductProjection(
  fields: string[] | undefined
): boolean {
  if (!fields) {
    return false
  }

  return (
    fields.length === 2 &&
    fields[0] === "handle" &&
    fields[1] === "id"
  )
}

function isStaticExternalIdRequested(fields: string[] | undefined): boolean {
  return (
    fields?.some(
      (field) => field === "external_id" || field === "+external_id"
    ) ?? false
  )
}

function compareStaticStrings(
  first: string,
  second: string,
  direction: StaticOrderDirection
): number {
  return direction === "DESC"
    ? second.localeCompare(first)
    : first.localeCompare(second)
}

function getStaticOrderDirection(
  order: StaticOrder | undefined,
  path: string[]
): StaticOrderDirection | undefined {
  if (!order || path.length === 0) {
    return undefined
  }

  const dotKeyDirection = order[path.join(".")]
  if (isStaticOrderDirection(dotKeyDirection)) {
    return dotKeyDirection
  }

  let current: StaticOrder | StaticOrderDirection | undefined = order
  for (const segment of path) {
    if (!isRecord(current)) {
      return undefined
    }

    current = current[segment] as StaticOrder | StaticOrderDirection | undefined
  }

  return isStaticOrderDirection(current) ? current : undefined
}

function getStaticProductIdFilter(value: unknown): StaticStringFilter {
  if (!isRecord(value)) {
    return {
      ids: [],
      present: false,
    }
  }

  const ids: string[] = []
  let present = false

  for (const [key, candidate] of Object.entries(value)) {
    if (key === "product_id" || key === "product.id") {
      present = true
      ids.push(
        ...normalizeStringFilter(candidate),
        ...normalizeStringOperatorFilter(candidate)
      )
      continue
    }

    if (key === "product" && isRecord(candidate)) {
      if (Object.prototype.hasOwnProperty.call(candidate, "id")) {
        present = true
        ids.push(
          ...normalizeStringFilter(candidate.id),
          ...normalizeStringOperatorFilter(candidate.id)
        )
      }

      continue
    }

    const nested = getStaticProductIdFilter(candidate)
    present = present || nested.present
    ids.push(...nested.ids)
  }

  return {
    ids: [...new Set(ids)],
    present,
  }
}

function isStaticProductInSalesChannel(
  productId: string,
  salesChannelIds: string[]
): boolean {
  return staticProductSalesChannelLinks.some(
    (link) =>
      link.product_id === productId &&
      salesChannelIds.includes(link.sales_channel_id)
  )
}

function getStaticProductVariantRows(
  productVariantQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = productVariantQuery?.__args
  const idFilter = getStaticStringFilter(args?.filters?.id)
  const productIdFilter = getStaticProductIdFilter(args?.filters)
  const manageInventoryFilter = getStaticBooleanFilter(
    args?.filters?.manage_inventory
  )
  const search = getStaticSearchFilter(args?.filters?.q)
  const salesChannelIdFilters = getStaticSalesChannelFilterIds(args?.filters)

  return staticProducts
    .filter((product) => !product.deleted_at)
    .flatMap((product) => product.variants)
    .filter((variant) => {
      if (idFilter.present && !idFilter.ids.includes(variant.id)) {
        return false
      }

      if (
        productIdFilter.present &&
        !productIdFilter.ids.includes(variant.product_id)
      ) {
        return false
      }

      if (
        manageInventoryFilter !== undefined &&
        variant.manage_inventory !== manageInventoryFilter
      ) {
        return false
      }

      if (search && !matchesStaticProductVariantSearch(variant, search)) {
        return false
      }

      if (
        salesChannelIdFilters.length > 0 &&
        !isStaticProductInSalesChannel(
          variant.product_id,
          salesChannelIdFilters
        )
      ) {
        return false
      }

      return true
    })
    .map(toStaticProductVariantRow)
}

function toStaticProductVariantRow(
  variant: StaticProductVariant
): Record<string, unknown> {
  return {
    ...variant,
    inventory_items: variant.inventory_items.map(
      toStaticProductVariantInventoryItemRow
    ),
    images: getStaticImagesForVariant(variant),
    product: {
      id: variant.product_id,
      status:
        staticProducts.find((product) => product.id === variant.product_id)
          ?.status ?? "published",
      type_id:
        staticProducts.find((product) => product.id === variant.product_id)
          ?.type_id ?? null,
    },
  }
}

function getStaticImagesForVariant(
  variant: StaticProductVariant
): StaticProductImage[] {
  const product = staticProducts.find(
    (candidate) => candidate.id === variant.product_id
  )

  if (!product) {
    return []
  }

  return product.images.filter((image) => {
    const links = staticProductVariantImageLinks.filter(
      (link) => link.image_id === image.id
    )

    return (
      links.length === 0 ||
      links.some((link) => link.variant_id === variant.id)
    )
  })
}

function getStaticCollectionForProduct(
  product: StaticProduct
): StaticProductCollection | null {
  if (!product.collection_id) {
    return null
  }

  return (
    staticProductCollections.find(
      (collection) => collection.id === product.collection_id
    ) ?? null
  )
}

function getStaticTypeForProduct(
  product: StaticProduct
): StaticProductType | null {
  if (!product.type_id) {
    return null
  }

  return staticProductTypes.find((type) => type.id === product.type_id) ?? null
}

function getStaticShippingProfileForProduct(
  product: StaticProduct
): StaticShippingProfile | null {
  if (!product.shipping_profile_id) {
    return null
  }

  return (
    staticShippingProfiles.find(
      (profile) => profile.id === product.shipping_profile_id
    ) ?? null
  )
}

function getStaticInventoryItemRows(
  inventoryItemQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = inventoryItemQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const q = typeof args?.filters?.q === "string" ? args.filters.q : undefined
  const locationLevelLocationIds = normalizeStringFilter(
    getRecordValue(args?.filters ?? {}, "location_levels")?.location_id
  )
  const normalizedQ = q?.trim().toLowerCase()

  return staticInventoryItems
    .filter((item) => {
      if (idFilters.length > 0 && !idFilters.includes(item.id)) {
        return false
      }

      if (
        locationLevelLocationIds.length > 0 &&
        !item.location_levels.some((level) =>
          locationLevelLocationIds.includes(level.location_id)
        )
      ) {
        return false
      }

      if (normalizedQ) {
        const searchable = [item.title, item.description, item.sku]
          .filter((value): value is string => typeof value === "string")
          .map((value) => value.toLowerCase())

        if (!searchable.some((value) => value.includes(normalizedQ))) {
          return false
        }
      }

      return true
    })
    .map(toStaticInventoryItemRow)
}

function getStaticInventoryLevelRows(
  inventoryLevelQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = inventoryLevelQuery?.__args
  const inventoryItemIds = normalizeStringFilter(args?.filters?.inventory_item_id)
  const locationIds = normalizeStringFilter(args?.filters?.location_id)

  return staticInventoryItems
    .flatMap((item) => item.location_levels)
    .filter((level) => {
      if (
        inventoryItemIds.length > 0 &&
        !inventoryItemIds.includes(level.inventory_item_id)
      ) {
        return false
      }

      if (locationIds.length > 0 && !locationIds.includes(level.location_id)) {
        return false
      }

      return true
    })
    .map((level) => ({ ...level }))
}

function getStaticShippingOptionTypeRows(
  shippingOptionTypeQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = shippingOptionTypeQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const labelFilters = normalizeStringFilter(args?.filters?.label)
  const codeFilters = normalizeStringFilter(args?.filters?.code)
  const descriptionFilters = normalizeStringFilter(args?.filters?.description)
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""

  return staticShippingOptionTypes.filter((shippingOptionType) => {
    if (
      idFilters.length > 0 &&
      !idFilters.includes(shippingOptionType.id)
    ) {
      return false
    }

    if (
      labelFilters.length > 0 &&
      !labelFilters.includes(shippingOptionType.label)
    ) {
      return false
    }

    if (
      codeFilters.length > 0 &&
      !codeFilters.includes(shippingOptionType.code)
    ) {
      return false
    }

    if (
      descriptionFilters.length > 0 &&
      !descriptionFilters.includes(shippingOptionType.description ?? "")
    ) {
      return false
    }

    if (!search) {
      return true
    }

    return (
      shippingOptionType.label.toLowerCase().includes(search) ||
      shippingOptionType.code.toLowerCase().includes(search) ||
      (shippingOptionType.description?.toLowerCase().includes(search) ?? false)
    )
  })
}

function getStaticShippingProfileRows(
  shippingProfileQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = shippingProfileQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const typeFilters = normalizeStringFilter(args?.filters?.type)
  const nameFilters = normalizeStringFilter(args?.filters?.name)
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""

  return staticShippingProfiles.filter((shippingProfile) => {
    if (idFilters.length > 0 && !idFilters.includes(shippingProfile.id)) {
      return false
    }

    if (typeFilters.length > 0 && !typeFilters.includes(shippingProfile.type)) {
      return false
    }

    if (nameFilters.length > 0 && !nameFilters.includes(shippingProfile.name)) {
      return false
    }

    if (!search) {
      return true
    }

    return (
      shippingProfile.name.toLowerCase().includes(search) ||
      shippingProfile.type.toLowerCase().includes(search)
    )
  })
}

function getStaticShippingOptionRows(
  shippingOptionQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = shippingOptionQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const serviceZoneFilters = normalizeStringFilter(
    args?.filters?.service_zone_id
  )
  const shippingProfileFilters = normalizeStringFilter(
    args?.filters?.shipping_profile_id
  )
  const providerFilters = normalizeStringFilter(args?.filters?.provider_id)
  const stockLocationFilters = normalizeStringFilter(
    args?.filters?.stock_location_id
  )
  const fulfillmentSetFilters = normalizeStringFilter(
    args?.filters?.["service_zone.fulfillment_set_id"]
  )
  const nestedServiceZone = getRecordValue(args?.filters, "service_zone")
  const nestedFulfillmentSetFilters = normalizeStringFilter(
    nestedServiceZone?.fulfillment_set_id
  )
  const hasEmptyFulfillmentSetFilter =
    Array.isArray(args?.filters?.["service_zone.fulfillment_set_id"]) &&
    args.filters["service_zone.fulfillment_set_id"].length === 0
  const hasEmptyNestedFulfillmentSetFilter =
    Array.isArray(nestedServiceZone?.fulfillment_set_id) &&
    nestedServiceZone.fulfillment_set_id.length === 0
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""

  return staticShippingOptions
    .filter((shippingOption) => {
      if (idFilters.length > 0 && !idFilters.includes(shippingOption.id)) {
        return false
      }

      if (
        serviceZoneFilters.length > 0 &&
        !serviceZoneFilters.includes(shippingOption.service_zone_id)
      ) {
        return false
      }

      if (
        shippingProfileFilters.length > 0 &&
        !shippingProfileFilters.includes(shippingOption.shipping_profile_id)
      ) {
        return false
      }

      if (
        providerFilters.length > 0 &&
        !providerFilters.includes(shippingOption.provider_id)
      ) {
        return false
      }

      const allFulfillmentSetFilters = [
        ...fulfillmentSetFilters,
        ...nestedFulfillmentSetFilters,
      ]

      if (
        hasEmptyFulfillmentSetFilter ||
        hasEmptyNestedFulfillmentSetFilter
      ) {
        return false
      }

      if (allFulfillmentSetFilters.length > 0) {
        const serviceZone = getStaticServiceZoneById(
          shippingOption.service_zone_id
        )
        if (
          !serviceZone ||
          !allFulfillmentSetFilters.includes(serviceZone.fulfillment_set_id)
        ) {
          return false
        }
      }

      if (stockLocationFilters.length > 0) {
        const stockLocationId = getStaticStockLocationIdForServiceZone(
          shippingOption.service_zone_id
        )
        if (
          !stockLocationId ||
          !stockLocationFilters.includes(stockLocationId)
        ) {
          return false
        }
      }

      if (!search) {
        return true
      }

      return shippingOption.name.toLowerCase().includes(search)
    })
    .map(toStaticShippingOptionRecord)
}

function toStaticShippingOptionRecord(
  shippingOption: StaticShippingOption
): Record<string, unknown> {
  const serviceZone = getStaticServiceZoneById(shippingOption.service_zone_id)
  const shippingProfile = staticShippingProfiles.find(
    (profile) => profile.id === shippingOption.shipping_profile_id
  )

  return {
    id: shippingOption.id,
    name: shippingOption.name,
    price_type: shippingOption.price_type,
    prices: shippingOption.prices,
    provider_id: shippingOption.provider_id,
    provider: {
      id: shippingOption.provider_id,
      is_enabled: true,
    },
    rules: shippingOption.rules,
    service_zone_id: shippingOption.service_zone_id,
    service_zone: serviceZone
      ? {
          id: serviceZone.id,
          name: serviceZone.name,
          fulfillment_set: {
            id: serviceZone.fulfillment_set_id,
          },
          fulfillment_set_id: serviceZone.fulfillment_set_id,
          metadata: null,
          created_at: serviceZone.created_at,
          updated_at: serviceZone.updated_at,
          deleted_at: null,
        }
      : null,
    shipping_profile_id: shippingOption.shipping_profile_id,
    shipping_profile: shippingProfile
      ? {
          id: shippingProfile.id,
          metadata: shippingProfile.metadata,
          name: shippingProfile.name,
          type: shippingProfile.type,
          created_at: shippingProfile.created_at,
          updated_at: shippingProfile.updated_at,
          deleted_at: null,
        }
      : null,
    type: {
      id: shippingOption.type.id,
      label: shippingOption.type.label,
      code: shippingOption.type.code,
      description: shippingOption.type.description,
      created_at: shippingOption.type.created_at,
      updated_at: shippingOption.type.updated_at,
      deleted_at: null,
    },
    created_at: shippingOption.created_at,
    updated_at: shippingOption.updated_at,
    data: shippingOption.data,
    metadata: shippingOption.metadata,
  }
}

