function getStaticStockLocationRows(
  stockLocationQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = stockLocationQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const nameFilters = normalizeStringFilter(args?.filters?.name)
  const salesChannelFilters = normalizeStringFilter(
    args?.filters?.sales_channel_id
  )
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""
  const shouldExcludeSeedLocations =
    idFilters.length === 0 &&
    nameFilters.length === 0 &&
    salesChannelFilters.length === 0 &&
    !search

  return staticStockLocations
    .filter((stockLocation) => {
      if (
        shouldExcludeSeedLocations &&
        stockLocation.id.startsWith("sloc_") &&
        stockLocation.id.endsWith("_worker_http_proof")
      ) {
        return false
      }

      if (idFilters.length > 0 && !idFilters.includes(stockLocation.id)) {
        return false
      }

      if (nameFilters.length > 0 && !nameFilters.includes(stockLocation.name)) {
        return false
      }

      if (
        salesChannelFilters.length > 0 &&
        !staticLocationSalesChannelLinks.some(
          (link) =>
            link.stock_location_id === stockLocation.id &&
            salesChannelFilters.includes(link.sales_channel_id)
        )
      ) {
        return false
      }

      if (!search) {
        return true
      }

      return stockLocation.name.toLowerCase().includes(search)
    })
    .map((stockLocation) => {
      const row: Record<string, unknown> = {
        ...stockLocation,
        address: stockLocation.address,
      }

      if (isStaticFieldRequested(stockLocationQuery, "fulfillment_providers")) {
        row.fulfillment_providers = getStaticFulfillmentProvidersForLocation(
          stockLocation.id
        )
      }

      if (isStaticFieldRequested(stockLocationQuery, "sales_channels")) {
        row.sales_channels = getStaticSalesChannelsForLocation(stockLocation.id)
      }

      if (isStaticFieldRequested(stockLocationQuery, "fulfillment_sets")) {
        row.fulfillment_sets = getStaticFulfillmentSetsForLocation(
          stockLocation.id
        )
      }

      return row
    })
}

function getStaticFulfillmentProviderRows(
  fulfillmentProviderQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = fulfillmentProviderQuery?.__args
  const hasEmptyIdFilter =
    Array.isArray(args?.filters?.id) && args.filters.id.length === 0
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const stockLocationIds = normalizeStringFilter(args?.filters?.stock_location_id)
  const isEnabledFilter =
    typeof args?.filters?.is_enabled === "boolean"
      ? args.filters.is_enabled
      : undefined
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""
  const providerIdsForLocation =
    stockLocationIds.length > 0
      ? new Set(
          staticLocationFulfillmentProviderLinks
            .filter((link) => stockLocationIds.includes(link.stock_location_id))
            .map((link) => link.fulfillment_provider_id)
        )
      : undefined

  if (hasEmptyIdFilter) {
    return []
  }

  return getStaticFulfillmentProviderSourceRows().filter((provider) => {
    if (idFilters.length > 0 && !idFilters.includes(provider.id)) {
      return false
    }

    if (providerIdsForLocation && !providerIdsForLocation.has(provider.id)) {
      return false
    }

    if (
      typeof isEnabledFilter === "boolean" &&
      provider.is_enabled !== isEnabledFilter
    ) {
      return false
    }

    if (!search) {
      return true
    }

    return provider.id.toLowerCase().includes(search)
  })
}

function getStaticFulfillmentProviderSourceRows(): Array<{
  id: string
  is_enabled: boolean
}> {
  return [
    {
      id: "manual_test-provider",
      is_enabled: true,
    },
    {
      id: "manual-calculated_test-provider-calculated",
      is_enabled: true,
    },
  ]
}

