function getStaticSalesChannelRows(
  salesChannelQuery: StaticRemoteQueryNode | undefined
): Array<Record<string, unknown>> {
  const args = salesChannelQuery?.__args
  const idFilters = normalizeStringFilter(args?.filters?.id)
  const nameFilters = normalizeStringFilter(args?.filters?.name)
  const descriptionFilter =
    typeof args?.filters?.description === "string"
      ? args.filters.description
      : ""
  const isDisabledFilter =
    typeof args?.filters?.is_disabled === "boolean"
      ? args.filters.is_disabled
      : undefined
  const publishableKeyIds = normalizeStringFilter(
    args?.filters?.publishable_key_id
  )
  const search =
    typeof args?.filters?.q === "string"
      ? args.filters.q.toLowerCase()
      : ""

  const rows = getStaticSalesChannelQueryRows(idFilters)

  return rows
    .filter((salesChannel) => {
      if (idFilters.length > 0 && !idFilters.includes(salesChannel.id)) {
        return false
      }

      if (
        nameFilters.length > 0 &&
        !nameFilters.includes(salesChannel.name)
      ) {
        return false
      }

      if (
        descriptionFilter &&
        salesChannel.description !== descriptionFilter
      ) {
        return false
      }

      if (
        typeof isDisabledFilter === "boolean" &&
        salesChannel.is_disabled !== isDisabledFilter
      ) {
        return false
      }

      if (
        publishableKeyIds.length > 0 &&
        !staticApiKeySalesChannelLinks.some(
          (link) =>
            link.sales_channel_id === salesChannel.id &&
            publishableKeyIds.includes(link.api_key_id)
        )
      ) {
        return false
      }

      if (!search) {
        return true
      }

      return (
        salesChannel.name.toLowerCase().includes(search) ||
        (salesChannel.description?.toLowerCase().includes(search) ?? false)
      )
    })
    .map((salesChannel) => {
      const row: Record<string, unknown> = {
        ...salesChannel,
        stock_locations: getStaticStockLocationsForSalesChannel(salesChannel.id),
        fields: parseStaticRemoteFields(salesChannelQuery?.fields),
        filter: args?.filters ?? null,
      }

      if (isStaticFieldRequested(salesChannelQuery, "publishable_api_keys")) {
        row.publishable_api_keys = getStaticApiKeysForSalesChannel(
          salesChannel.id
        )
      }

      return row
    })
}

function getStaticSalesChannelQueryRows(
  idFilters: string[]
): StaticSalesChannel[] {
  const hasMirroredDefaultSalesChannel = staticSalesChannels.some(
    (salesChannel) =>
      salesChannel.id !== "sc_worker_http_proof" &&
      salesChannel.name === "Default Sales Channel"
  )

  if (!hasMirroredDefaultSalesChannel) {
    return staticSalesChannels
  }

  return staticSalesChannels.filter(
    (salesChannel) =>
      salesChannel.id !== "sc_worker_http_proof" ||
      idFilters.includes(salesChannel.id)
  )
}

