async function createStaticAdminViewConfigurationUpdateResponse(
  entity: string,
  viewConfigurationId: string,
  body: Record<string, unknown>,
  authorization: string | undefined,
  testNowHeader: string | undefined
): Promise<Response> {
  const actorId = await getStaticAuthenticatedActorId(
    authorization,
    testNowHeader
  )
  if (!actorId) {
    return createStaticErrorResponse(401, "unauthorized", "Unauthorized")
  }

  const viewConfiguration = staticViewConfigurations.find(
    (candidate) =>
      candidate.id === viewConfigurationId &&
      candidate.entity === entity &&
      candidate.deleted_at === null
  )

  if (!viewConfiguration) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `View configuration with id: ${viewConfigurationId} was not found`
    )
  }

  if (
    viewConfiguration.user_id &&
    viewConfiguration.user_id !== actorId
  ) {
    return createStaticErrorResponse(
      400,
      "not_allowed",
      "You can only update your own view configurations"
    )
  }

  const configuration = getRecordValue(body, "configuration")
  const updatedViewConfiguration: StaticViewConfiguration = {
    ...viewConfiguration,
    name:
      typeof body.name === "string"
        ? body.name
        : viewConfiguration.name,
    configuration: configuration ?? viewConfiguration.configuration,
    updated_at: new Date(Date.UTC(2026, 5, 21, 6, 0, 0)).toISOString(),
  }

  staticViewConfigurations = [
    ...staticViewConfigurations.filter(
      (candidate) => candidate.id !== viewConfigurationId
    ),
    updatedViewConfiguration,
  ]
  staticUpdatedViewConfigurations.set(
    viewConfigurationId,
    updatedViewConfiguration
  )
  if (body.set_active === true && updatedViewConfiguration.user_id) {
    staticActiveViewConfigurationPreferences.set(
      createStaticActiveViewConfigurationPreferenceKey(entity, actorId),
      updatedViewConfiguration.id
    )
  }

  return createStaticJsonResponse({
    view_configuration: updatedViewConfiguration,
  })
}

async function createStaticAdminViewConfigurationDeleteResponse(
  entity: string,
  viewConfigurationId: string,
  authorization: string | undefined,
  testNowHeader: string | undefined
): Promise<Response> {
  const actorId = await getStaticAuthenticatedActorId(
    authorization,
    testNowHeader
  )
  if (!actorId) {
    return createStaticErrorResponse(401, "unauthorized", "Unauthorized")
  }

  const viewConfiguration = staticViewConfigurations.find(
    (candidate) =>
      candidate.id === viewConfigurationId &&
      candidate.entity === entity &&
      candidate.deleted_at === null
  )

  if (!viewConfiguration) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `View configuration with id: ${viewConfigurationId} was not found`
    )
  }

  if (
    viewConfiguration.user_id &&
    viewConfiguration.user_id !== actorId
  ) {
    return createStaticErrorResponse(
      400,
      "not_allowed",
      "You can only delete your own view configurations"
    )
  }

  staticDeletedViewConfigurationIds.add(viewConfigurationId)
  staticViewConfigurations = staticViewConfigurations.filter(
    (candidate) => candidate.id !== viewConfigurationId
  )

  return createStaticJsonResponse({
    id: viewConfigurationId,
    object: "view_configuration",
    deleted: true,
  })
}

async function getStaticAuthenticatedActorId(
  authorization: string | undefined,
  testNowHeader: string | undefined
): Promise<string | undefined> {
  const token = getStaticBearerToken(authorization)
  const payload = token
    ? await verifyStaticResetToken(token, getStaticRequestNowMs(testNowHeader))
    : undefined

  return payload ? getStringValue(payload, "actor_id") : undefined
}

async function createStaticAuthSessionResponse(
  authorization: string | undefined,
  testNowHeader: string | undefined
): Promise<Response> {
  const nowMs = getStaticRequestNowMs(testNowHeader)
  const token = getStaticBearerToken(authorization)
  const payload = token ? await verifyStaticResetToken(token, nowMs) : undefined

  if (!payload) {
    return createStaticErrorResponse(401, "unauthorized", "Unauthorized")
  }

  staticSessionSequence += 1
  const sessionId = `session_worker_http_proof_${staticSessionSequence}`
  staticSessionIds.add(sessionId)

  return new Response(JSON.stringify({}), {
    status: 200,
    headers: {
      "content-type": "application/json",
      "set-cookie": `connect.sid=${sessionId}; Path=/; HttpOnly`,
      "x-medusa-http-proof": "static-fetch",
    },
  })
}

function deleteStaticAuthSessionResponse(cookieHeader: string | undefined): Response {
  const sessionId = getStaticSessionId(cookieHeader)
  if (sessionId) {
    staticSessionIds.delete(sessionId)
  }

  return createStaticJsonResponse({})
}

async function createStaticAuthLoginResponse(
  actorType: string,
  provider: string,
  body: Record<string, unknown>,
  testNowHeader: string | undefined
): Promise<Response> {
  const result = await staticAuthService.authenticate(provider, { body })
  const authIdentity =
    result.success && result.authIdentity
      ? result.authIdentity
      : getStaticAcceptedInviteAuthIdentity(provider, body)

  if (!authIdentity) {
    return createStaticErrorResponse(
      401,
      "unauthorized",
      result.error ?? "Authentication failed"
    )
  }

  return createStaticAuthTokenResponse(
    actorType,
    provider,
    authIdentity,
    testNowHeader
  )
}

async function createStaticAuthRegisterResponse(
  actorType: string,
  provider: string,
  body: Record<string, unknown>,
  testNowHeader: string | undefined
): Promise<Response> {
  const result = await staticAuthService.register(provider, { body })

  if (!result.success || !result.authIdentity) {
    return createStaticErrorResponse(
      401,
      "unauthorized",
      result.error ?? "Authentication failed"
    )
  }

  return createStaticAuthTokenResponse(
    actorType,
    provider,
    result.authIdentity,
    testNowHeader
  )
}

async function createStaticAuthTokenResponse(
  actorType: string,
  provider: string,
  authIdentity: AuthIdentityDTO,
  testNowHeader: string | undefined
): Promise<Response> {
  const actorIdKey = `${actorType}_id`
  const actorId = getStaticAuthIdentityActorId(authIdentity, actorType)
  const providerIdentity = authIdentity.provider_identities?.find(
    (identity) => identity.provider === provider
  )
  const token = await createStaticJwtToken(
    {
      actor_id: actorId ?? "",
      actor_type: actorType,
      auth_identity_id: authIdentity.id,
      app_metadata: {
        [actorIdKey]: actorId,
        roles: actorType === "user" ? getStaticUserRoleIds(actorId) : undefined,
      },
      user_metadata: providerIdentity?.user_metadata ?? {},
    },
    getStaticRequestNowMs(testNowHeader),
    60 * 60 * 24
  )

  return createStaticJsonResponse({ token })
}

function getStaticAuthIdentityActorId(
  authIdentity: AuthIdentityDTO,
  actorType: string
): string | undefined {
  const appMetadata = authIdentity.app_metadata ?? {}
  const actorIdKey = `${actorType}_id`
  const metadataActorId =
    getStringValue(appMetadata, actorIdKey) ??
    getStringValue(appMetadata, actorType)
  if (metadataActorId) {
    return metadataActorId
  }

  const providerEmail = authIdentity.provider_identities
    ?.map((identity) => identity.entity_id)
    .find((entityId): entityId is string => typeof entityId === "string")

  if (actorType === "customer") {
    return staticCustomers.find(
      (customer) => customer.email === providerEmail && customer.has_account
    )?.id
  }

  if (actorType !== "user") {
    return undefined
  }

  return providerEmail
    ? staticUsers.find((user) => user.email === providerEmail)?.id
    : undefined
}

function getStaticAcceptedInviteAuthIdentity(
  provider: string,
  body: Record<string, unknown>
): AuthIdentityDTO | undefined {
  const email = getStringValue(body, "email")
  const password = getStringValue(body, "password")
  if (!email || !password) {
    return undefined
  }

  const user = staticUsers.find((candidate) => candidate.email === email)
  if (!user) {
    return undefined
  }

  const identity = staticAuthIdentities.find(
    (candidate) =>
      candidate.provider === provider &&
      candidate.email === email &&
      candidate.app_metadata.user_id === user.id
  )
  if (!identity) {
    return undefined
  }

  identity.password = password
  return toStaticAuthIdentityDTO(identity)
}

function createStaticAdminProductsSessionProbeResponse(
  cookieHeader: string | undefined
): Response | undefined {
  const sessionId = getStaticSessionId(cookieHeader)
  if (!sessionId) {
    return undefined
  }

  if (!staticSessionIds.has(sessionId)) {
    return createStaticErrorResponse(401, "unauthorized", "Unauthorized")
  }

  return createStaticJsonResponse({
    products: [],
    count: 0,
    offset: 0,
    limit: 1,
  })
}

function createStaticAdminProductRetrieveResponse(
  productId: string,
  searchParams: URLSearchParams,
  authorization: string | undefined,
  accessToken: string | null
): Response {
  const product = staticProducts.find(
    (candidate) => candidate.id === productId && !candidate.deleted_at
  )
  if (!product) {
    return createStaticErrorResponse(404, "not_found", "Product not found")
  }

  const access =
    accessToken === "test_token" && staticUserRbacRoleLinks.length === 0
      ? createStaticProductFullAccess()
      : getStaticProductRbacAccess(authorization)
  if (access.enforced && !access.canReadProduct) {
    return createStaticErrorResponse(403, "forbidden", "Forbidden")
  }

  return createStaticJsonResponse({
    product: toStaticAdminProductResponse(product, searchParams, access),
  })
}

function createStaticAdminProductUpdateResponse(
  productId: string,
  body: Record<string, unknown>,
  searchParams: URLSearchParams
): Response {
  const statusValidationResponse = validateStaticAdminProductStatusInput(body)
  if (statusValidationResponse) {
    return statusValidationResponse
  }

  const product = staticProducts.find(
    (candidate) => candidate.id === productId && !candidate.deleted_at
  )
  if (!product) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Product with id "${productId}" not found`
    )
  }

  const updatedProducts = updateStaticProductsFromWorkflowInput({
    selector: { id: productId },
    update: body,
  })
  const updated = updatedProducts[0] ?? product

  return createStaticJsonResponse({
    product: toStaticAdminProductResponse(
      updated,
      searchParams,
      createStaticProductFullAccess()
    ),
  })
}

const staticAdminProductStatuses = [
  "draft",
  "proposed",
  "published",
  "rejected",
] as const

function validateStaticAdminProductStatusInput(
  body: Record<string, unknown>
): Response | undefined {
  if (!Object.prototype.hasOwnProperty.call(body, "status")) {
    return undefined
  }

  if (
    typeof body.status !== "string" ||
    !staticAdminProductStatuses.some((status) => status === body.status)
  ) {
    return createStaticErrorResponse(
      400,
      "invalid_data",
      "Invalid product status"
    )
  }

  return undefined
}

function createStaticAdminProductDeleteResponse(productId: string): Response {
  try {
    deleteStaticProductsFromWorkflowInput({ ids: [productId] })
  } catch (error) {
    const validationResponse = createStaticInvalidDataErrorResponse(error)
    if (validationResponse) {
      return validationResponse
    }

    throw error
  }

  return createStaticJsonResponse({
    id: productId,
    object: "product",
    deleted: true,
  })
}

function createStaticAdminProductBatchResponse(
  body: Record<string, unknown>,
  searchParams: URLSearchParams
): Response {
  try {
    const batchResult = batchStaticProductsFromWorkflowInput(body)

    return createStaticJsonResponse({
      created: batchResult.created.map((product) =>
        toStaticAdminProductResponse(
          product,
          searchParams,
          createStaticProductFullAccess()
        )
      ),
      updated: batchResult.updated.map((product) =>
        toStaticAdminProductResponse(
          product,
          searchParams,
          createStaticProductFullAccess()
        )
      ),
      deleted: {
        ids: batchResult.deleted,
      },
    })
  } catch (error) {
    const validationResponse = createStaticInvalidDataErrorResponse(error)
    if (validationResponse) {
      return validationResponse
    }

    throw error
  }
}

function createStaticInvalidDataErrorResponse(
  error: unknown
): Response | undefined {
  if (
    error instanceof MedusaError &&
    error.type === MedusaError.Types.INVALID_DATA
  ) {
    return createStaticErrorResponse(400, "invalid_data", error.message)
  }

  return undefined
}

type StaticProductRbacAccess = {
  enforced: boolean
  canReadProduct: boolean
  canReadProductTags: boolean
  canReadPrices: boolean
}

function createStaticProductFullAccess(): StaticProductRbacAccess {
  return {
    enforced: false,
    canReadProduct: true,
    canReadProductTags: true,
    canReadPrices: true,
  }
}

function getStaticProductRbacAccess(
  authorization: string | undefined
): StaticProductRbacAccess {
  const authContext = decodeStaticBearerAuthContext(authorization)
  if (authContext?.actor_type !== "user") {
    return createStaticProductFullAccess()
  }

  const roleIds = getStaticAuthRoleIds(authContext)
  if (roleIds.length === 0) {
    return {
      enforced: true,
      canReadProduct: false,
      canReadProductTags: false,
      canReadPrices: false,
    }
  }

  if (roleIds.includes("role_super_admin")) {
    return createStaticProductFullAccess()
  }

  return {
    enforced: true,
    canReadProduct: hasStaticRolePolicy(roleIds, "product", "read"),
    canReadProductTags: hasStaticRolePolicy(roleIds, "product_tag", "read"),
    canReadPrices:
      hasStaticRolePolicy(roleIds, "price", "read") &&
      hasStaticRolePolicy(roleIds, "price_set", "read"),
  }
}

function getStaticAuthRoleIds(authContext: AuthContext): string[] {
  const rolesFromToken = normalizeStringFilter(authContext.app_metadata.roles)
  if (rolesFromToken.length > 0) {
    return rolesFromToken
  }

  return getStaticUserRoleIds(getStaticAuthUserId(authContext))
}

function getStaticAuthUserId(authContext: AuthContext): string | undefined {
  if (authContext.actor_id) {
    return authContext.actor_id
  }

  const metadataUserId =
    getStringValue(authContext.app_metadata, "user_id") ??
    getStringValue(authContext.app_metadata, "user")
  if (metadataUserId) {
    return metadataUserId
  }

  const authIdentity = staticAuthIdentities.find(
    (identity) => identity.id === authContext.auth_identity_id
  )
  if (!authIdentity) {
    return undefined
  }

  return (
    getStringValue(authIdentity.app_metadata, "user_id") ??
    getStringValue(authIdentity.app_metadata, "user")
  )
}

function getStaticUserRoleIds(userId: string | undefined): string[] {
  if (!userId) {
    return []
  }

  return staticUserRbacRoleLinks
    .filter((link) => link.user_id === userId)
    .map((link) => link.rbac_role_id)
}

function getStaticUserRbacRoles(userId: string): Array<Record<string, unknown>> {
  const roleIds = getStaticUserRoleIds(userId)
  return staticRbacRoles
    .filter((role) => roleIds.includes(role.id))
    .map(toStaticRbacRoleGraphRow)
}

function toStaticRbacRoleGraphRow(
  role: StaticRbacRole
): Record<string, unknown> {
  const policyIds = staticRbacRolePolicies
    .filter((rolePolicy) => rolePolicy.role_id === role.id)
    .map((rolePolicy) => rolePolicy.policy_id)

  return {
    ...role,
    policies: staticRbacPolicies.filter((policy) =>
      policyIds.includes(policy.id)
    ),
  }
}

function hasStaticRolePolicy(
  roleIds: string[],
  resource: string,
  operation: string
): boolean {
  const policyIds = staticRbacRolePolicies
    .filter((rolePolicy) => roleIds.includes(rolePolicy.role_id))
    .map((rolePolicy) => rolePolicy.policy_id)

  return staticRbacPolicies.some(
    (policy) =>
      policyIds.includes(policy.id) &&
      (policy.resource === "*" || policy.resource === resource) &&
      (policy.operation === "*" || policy.operation === operation)
  )
}

function toStaticAdminProductResponse(
  product: StaticProduct,
  searchParams: URLSearchParams,
  access: StaticProductRbacAccess
): Record<string, unknown> {
  const fieldFilters = searchParams
    .getAll("fields")
    .flatMap((field) => field.split(",").map((part) => part.trim()))
    .filter((field) => field.length > 0)
  const explicitFields = fieldFilters.filter(
    (field) =>
      !field.startsWith("*") && !field.startsWith("+") && !field.includes(".")
  )
  const includeOnlyExplicit = explicitFields.length > 0
  const includeVariantPrices =
    fieldFilters.length === 0 ||
    isStaticAdminProductFieldRequested(fieldFilters, "variants.prices")

  const response: Record<string, unknown> = {
    ...product,
    weight: toStaticProductDimensionResponseValue(product.weight),
    length: toStaticProductDimensionResponseValue(product.length),
    height: toStaticProductDimensionResponseValue(product.height),
    width: toStaticProductDimensionResponseValue(product.width),
    collection: getStaticCollectionForProduct(product),
    type: getStaticTypeForProduct(product) ?? {},
    variants: product.variants.map((variant) =>
      toStaticAdminProductVariantResponse(variant, access, includeVariantPrices)
    ),
  }

  if (isStaticAdminProductFieldRequested(fieldFilters, "categories")) {
    response.categories = getStaticCategoriesForProduct(product.id)
  }

  if (isStaticAdminProductFieldRequested(fieldFilters, "sales_channels")) {
    response.sales_channels = getStaticSalesChannelsForProduct(product.id)
  }

  if (isStaticAdminProductFieldRequested(fieldFilters, "shipping_profile")) {
    response.shipping_profile = getStaticShippingProfileForProduct(product)
  }

  if (!access.canReadProductTags) {
    delete response.tags
  }

  if (includeOnlyExplicit) {
    const projected: Record<string, unknown> = { id: response.id }
    for (const field of explicitFields) {
      if (Object.prototype.hasOwnProperty.call(response, field)) {
        projected[field] = response[field]
      }
    }
    for (const field of fieldFilters) {
      const responseField = getStaticAdminProductResponseField(field)
      if (
        responseField &&
        Object.prototype.hasOwnProperty.call(response, responseField)
      ) {
        projected[responseField] = response[responseField]
      }
    }
    return projected
  }

  return response
}

function isStaticAdminProductFieldRequested(
  fields: string[],
  field: string
): boolean {
  return fields.some((requestedField) => {
    const normalized = getStaticAdminProductNormalizedField(requestedField)
    return (
      normalized === field ||
      normalized.startsWith(`${field}.`) ||
      normalized === `${field}.*`
    )
  })
}

function toStaticAdminProductVariantResponse(
  variant: StaticProductVariant,
  access: StaticProductRbacAccess,
  includePrices: boolean
): Record<string, unknown> {
  const response: Record<string, unknown> = {
    ...toStaticProductVariantRow(variant),
    prices: variant.price_set.prices,
  }

  if (!access.canReadPrices || !includePrices) {
    delete response.prices
    delete response.price_set
  }

  return response
}

function getStaticAdminProductResponseField(
  requestedField: string
): string | undefined {
  const normalized = getStaticAdminProductNormalizedField(requestedField)
  if (!normalized) {
    return undefined
  }

  return normalized.split(".")[0]
}

function getStaticAdminProductNormalizedField(requestedField: string): string {
  return requestedField.replace(/^[*+]+/, "")
}

function getStaticSessionId(cookieHeader: string | undefined): string | undefined {
  return getFetchCookieValue(cookieHeader, "connect.sid")
}

function createStaticSessionId(): string {
  staticSessionSequence += 1
  return `session_worker_http_proof_${staticSessionSequence}`
}

async function createStaticInviteResponse(
  body: Record<string, unknown>,
  testNowHeader: string | undefined
): Promise<Response> {
  const email = getStringValue(body, "email")
  if (!email) {
    return createStaticErrorResponse(400, "invalid_data", "Email is required")
  }

  const roles = normalizeStringFilter(body.roles)
  const missingRole = roles.find(
    (roleId) => !staticRbacRoles.some((role) => role.id === roleId)
  )
  if (missingRole) {
    return createStaticErrorResponse(
      400,
      "invalid_data",
      `The role ${missingRole} does not exist`
    )
  }

  const invite = await createStaticInvite(
    email,
    roles,
    getStaticRequestNowMs(testNowHeader)
  )
  return createStaticJsonResponse({ invite })
}

function createStaticInviteListResponse(): Response {
  const invites = staticInvites.filter((invite) => !invite.accepted)
  return createStaticJsonResponse({
    invites,
    count: invites.length,
    offset: 0,
    limit: 50,
  })
}

function createStaticInviteRetrieveResponse(inviteId: string): Response {
  const invite = staticInvites.find(
    (candidate) => candidate.id === inviteId && !candidate.accepted
  )

  if (!invite) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Invite with id: ${inviteId} was not found`
    )
  }

  return createStaticJsonResponse({ invite })
}

async function resendStaticInviteResponse(
  inviteId: string,
  testNowHeader: string | undefined
): Promise<Response> {
  const invite = staticInvites.find(
    (candidate) => candidate.id === inviteId && !candidate.accepted
  )

  if (!invite) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Invite with id: ${inviteId} was not found`
    )
  }

  invite.token = await createStaticJwtToken(
    {
      invite_id: invite.id,
      email: invite.email,
      token_sequence: incrementStaticInviteTokenSequence(),
    },
    getStaticRequestNowMs(testNowHeader),
    60 * 60 * 24
  )
  invite.updated_at = new Date(
    Date.UTC(2026, 5, 21, 5, 30, staticInviteSequence)
  ).toISOString()

  return createStaticJsonResponse({ invite })
}

function deleteStaticInviteResponse(inviteId: string): Response {
  const invite = staticInvites.find(
    (candidate) => candidate.id === inviteId && !candidate.accepted
  )

  if (!invite) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Invite with id: ${inviteId} was not found`
    )
  }

  invite.accepted = true
  return createStaticJsonResponse({
    id: inviteId,
    object: "invite",
    deleted: true,
  })
}

async function acceptStaticInviteResponse(
  body: Record<string, unknown>,
  searchParams: URLSearchParams,
  authorization: string | undefined,
  testNowHeader: string | undefined
): Promise<Response> {
  const nowMs = getStaticRequestNowMs(testNowHeader)
  const token = searchParams.get("token")
  const bearerToken = getStaticBearerToken(authorization)
  const payload = bearerToken
    ? await verifyStaticResetToken(bearerToken, nowMs)
    : undefined

  const authIdentityId = payload
    ? getStringValue(payload, "auth_identity_id")
    : undefined
  const invite = staticInvites.find(
    (candidate) => candidate.token === token && !candidate.accepted
  )
  const invitePayload = token
    ? await verifyStaticResetToken(token, nowMs)
    : undefined
  const inviteId = invitePayload
    ? getStringValue(invitePayload, "invite_id") ??
      getStringValue(invitePayload, "id")
    : undefined
  const authIdentity = authIdentityId
    ? staticAuthIdentities.find((identity) => identity.id === authIdentityId)
    : undefined

  if (!invite || invite.id !== inviteId || !authIdentity) {
    return createStaticErrorResponse(401, "unauthorized", "Unauthorized")
  }

  const user = createStaticUserFromInvite(invite, body)
  invite.accepted = true
  invite.updated_at = user.updated_at
  authIdentity.app_metadata = {
    ...authIdentity.app_metadata,
    user_id: user.id,
  }

  return createStaticJsonResponse({ user })
}

async function createStaticInvite(
  email: string,
  roles: string[],
  nowMs: number
): Promise<StaticInvite> {
  staticInviteSequence += 1
  const timestamp = new Date(
    Date.UTC(2026, 5, 21, 5, 10, staticInviteSequence)
  ).toISOString()
  const id = `invite_worker_http_proof_${staticInviteSequence}`
  const token = await createStaticJwtToken(
    {
      invite_id: id,
      email,
      token_sequence: incrementStaticInviteTokenSequence(),
    },
    nowMs,
    60 * 60 * 24
  )
  const invite: StaticInvite = {
    id,
    email,
    token,
    roles,
    accepted: false,
    created_at: timestamp,
    updated_at: timestamp,
    deleted_at: null,
  }

  staticInvites.push(invite)
  return invite
}

function incrementStaticInviteTokenSequence(): number {
  staticInviteTokenSequence += 1
  return staticInviteTokenSequence
}

