function ensureStaticAdminActorUser(
  actorId: string,
  userMetadata: Record<string, unknown>
): StaticUser {
  const existing = staticUsers.find((candidate) => candidate.id === actorId)
  if (existing) {
    return existing
  }

  const timestamp = new Date(Date.UTC(2026, 5, 21, 5, 35, 0)).toISOString()
  const email =
    getStringValue(userMetadata, "email") ??
    `${actorId.replace(/[^a-zA-Z0-9._-]/g, "_")}@worker-http-proof.local`
  const user: StaticUser = {
    id: actorId,
    email,
    first_name:
      getStringValue(userMetadata, "first_name") ??
      getStringValue(userMetadata, "given_name") ??
      null,
    last_name:
      getStringValue(userMetadata, "last_name") ??
      getStringValue(userMetadata, "family_name") ??
      null,
    metadata: null,
    created_at: timestamp,
    updated_at: timestamp,
    deleted_at: null,
  }

  staticUsers.push(user)
  return user
}

function createStaticUserFromLinkedAuthIdentity(
  email: string
): StaticUser | undefined {
  const linkedIdentity = staticAuthIdentities.find(
    (identity) =>
      identity.email === email &&
      typeof identity.app_metadata.user_id === "string"
  )
  if (!linkedIdentity) {
    return undefined
  }

  const linkedUserId = getStringValue(linkedIdentity.app_metadata, "user_id")

  if (!linkedUserId) {
    return undefined
  }

  const existingUser = staticUsers.find((user) => user.id === linkedUserId)
  if (existingUser) {
    return existingUser
  }

  const timestamp = new Date(Date.UTC(2026, 5, 21, 5, 25, 0)).toISOString()
  const user: StaticUser = {
    id: linkedUserId,
    email,
    first_name: getStringValue(linkedIdentity.user_metadata, "first_name") ?? null,
    last_name: getStringValue(linkedIdentity.user_metadata, "last_name") ?? null,
    metadata: null,
    created_at: timestamp,
    updated_at: timestamp,
    deleted_at: null,
  }

  staticUsers.push(user)
  return user
}

