function createStaticRbacRoleResponse(
  body: Record<string, unknown>
): Response {
  const role = createStaticRbacRoleFromBody(body)
  return createStaticJsonResponse({ role })
}

function createStaticRbacRolesResponse(searchParams: URLSearchParams): Response {
  const idFilters = normalizeStringFilter(searchParams.getAll("id"))
  const nameFilters = normalizeStringFilter(searchParams.getAll("name"))
  const roles = staticRbacRoles.filter((role) => {
    if (idFilters.length > 0 && !idFilters.includes(role.id)) {
      return false
    }

    if (nameFilters.length > 0 && !nameFilters.includes(role.name)) {
      return false
    }

    return true
  })

  return createStaticJsonResponse({
    roles,
    count: roles.length,
    offset: 0,
    limit: roles.length,
  })
}

function createStaticRbacRoleRetrieveResponse(
  roleId: string,
  searchParams: URLSearchParams
): Response {
  const role = staticRbacRoles.find((candidate) => candidate.id === roleId)
  if (!role) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Role with id: ${roleId} not found`
    )
  }

  return createStaticJsonResponse({
    role: decorateStaticRbacRole(role, searchParams),
  })
}

function createStaticRbacRoleUpdateResponse(
  roleId: string,
  body: Record<string, unknown>
): Response {
  const role = staticRbacRoles.find((candidate) => candidate.id === roleId)
  if (!role) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Role with id: ${roleId} not found`
    )
  }

  const updated: StaticRbacRole = {
    ...role,
    name: getStringValue(body, "name") ?? role.name,
    description:
      getNullableStringValue(body, "description") ?? role.description,
    metadata: getRecordValue(body, "metadata") ?? role.metadata,
    updated_at: new Date(Date.UTC(2026, 5, 21, 5, 58, 0)).toISOString(),
  }

  staticRbacRoles = staticRbacRoles.map((candidate) =>
    candidate.id === roleId ? updated : candidate
  )

  return createStaticJsonResponse({ role: updated })
}

function createStaticRbacRoleDeleteResponse(roleId: string): Response {
  staticRbacRoles = staticRbacRoles.filter((role) => role.id !== roleId)
  staticRbacRolePolicies = staticRbacRolePolicies.filter(
    (rolePolicy) => rolePolicy.role_id !== roleId
  )
  staticUserRbacRoleLinks = staticUserRbacRoleLinks.filter(
    (link) => link.rbac_role_id !== roleId
  )

  return createStaticJsonResponse({
    id: roleId,
    object: "rbac_role",
    deleted: true,
  })
}

function decorateStaticRbacRole(
  role: StaticRbacRole,
  searchParams: URLSearchParams
): StaticRbacRole & { policies?: StaticRbacPolicy[] } {
  const fields = searchParams.get("fields") ?? ""
  if (!fields.split(",").map((field) => field.trim()).includes("policies")) {
    return role
  }

  const policyIds = staticRbacRolePolicies
    .filter((rolePolicy) => rolePolicy.role_id === role.id)
    .map((rolePolicy) => rolePolicy.policy_id)

  return {
    ...role,
    policies: staticRbacPolicies.filter((policy) => policyIds.includes(policy.id)),
  }
}

