function createStaticRbacPolicyFromBody(
  body: Record<string, unknown>
): StaticRbacPolicy {
  staticRbacPolicySequence += 1
  const timestamp = new Date(
    Date.UTC(2026, 5, 21, 5, 45, staticRbacPolicySequence)
  ).toISOString()
  const key = getStringValue(body, "key") ?? "worker:policy"
  const policy: StaticRbacPolicy = {
    id: `policy_worker_http_proof_${staticRbacPolicySequence}`,
    key,
    resource: getStringValue(body, "resource") ?? key.split(":")[1] ?? "",
    operation: getStringValue(body, "operation") ?? key.split(":")[0] ?? "",
    name: getStringValue(body, "name") ?? key,
    description: getNullableStringValue(body, "description"),
    metadata: getRecordValue(body, "metadata") ?? null,
    created_at: timestamp,
    updated_at: timestamp,
    deleted_at: null,
  }

  staticRbacPolicies.push(policy)
  return policy
}

function createStaticRbacRolePoliciesResponse(
  roleId: string,
  body: Record<string, unknown>
): Response {
  if (!staticRbacRoles.some((role) => role.id === roleId)) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Role with id: ${roleId} not found`
    )
  }

  const policyIds = getStringArrayValue(body, "policies")
  const policies = policyIds.map((policyId) =>
    createStaticRbacRolePolicy(roleId, policyId)
  )

  return createStaticJsonResponse({ policies })
}

function createStaticRbacRolePolicyDeleteResponse(
  roleId: string,
  policyId: string
): Response {
  const link = staticRbacRolePolicies.find(
    (rolePolicy) =>
      rolePolicy.role_id === roleId && rolePolicy.policy_id === policyId
  )

  staticRbacRolePolicies = staticRbacRolePolicies.filter(
    (rolePolicy) =>
      !(rolePolicy.role_id === roleId && rolePolicy.policy_id === policyId)
  )

  return createStaticJsonResponse({
    id: link?.id ?? `rlpl_worker_http_proof_${roleId}_${policyId}`,
    object: "rbac_role_policy",
    deleted: true,
  })
}

function createStaticRbacRolePolicy(
  roleId: string,
  policyId: string
): StaticRbacRolePolicy {
  const existing = staticRbacRolePolicies.find(
    (rolePolicy) =>
      rolePolicy.role_id === roleId && rolePolicy.policy_id === policyId
  )
  if (existing) {
    return existing
  }

  staticRbacRolePolicySequence += 1
  const timestamp = new Date(
    Date.UTC(2026, 5, 21, 6, 5, staticRbacRolePolicySequence)
  ).toISOString()
  const rolePolicy: StaticRbacRolePolicy = {
    id: `rlpl_worker_http_proof_${staticRbacRolePolicySequence}`,
    role_id: roleId,
    policy_id: policyId,
    created_at: timestamp,
    updated_at: timestamp,
    deleted_at: null,
  }

  staticRbacRolePolicies.push(rolePolicy)
  return rolePolicy
}

function createStaticRbacRoleUsersResponse(
  roleId: string,
  searchParams: URLSearchParams
): Response {
  if (!staticRbacRoles.some((role) => role.id === roleId)) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Role with id: ${roleId} not found`
    )
  }

  const userIdFilters = normalizeStringFilter([
    ...searchParams.getAll("user_id"),
    ...searchParams.getAll("user_id[]"),
  ])
  const offset = parseStaticIntegerSearchParam(
    new URL(`http://worker.local/?${searchParams.toString()}`),
    "offset",
    0
  )
  const limit = parseStaticIntegerSearchParam(
    new URL(`http://worker.local/?${searchParams.toString()}`),
    "limit",
    20
  )
  const linkedUserIds = staticUserRbacRoleLinks
    .filter((link) => link.rbac_role_id === roleId)
    .map((link) => link.user_id)
  const users = staticUsers.filter((user) => {
    if (!linkedUserIds.includes(user.id)) {
      return false
    }

    return userIdFilters.length === 0 || userIdFilters.includes(user.id)
  })

  return createStaticJsonResponse({
    users: users.slice(offset, offset + limit),
    count: users.length,
    offset,
    limit,
  })
}

function createStaticRbacRoleUsersAssignResponse(
  roleId: string,
  body: Record<string, unknown>
): Response {
  if (!staticRbacRoles.some((role) => role.id === roleId)) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Role with id: ${roleId} not found`
    )
  }

  const userIds = getStringArrayValue(body, "users")
  for (const userId of userIds) {
    pushUniqueStaticUserRbacRoleLink(userId, roleId)
  }

  return createStaticJsonResponse({
    users: staticUsers.filter((user) => userIds.includes(user.id)),
  })
}

function createStaticRbacRoleUsersDeleteResponse(
  roleId: string,
  body: Record<string, unknown>
): Response {
  if (!staticRbacRoles.some((role) => role.id === roleId)) {
    return createStaticErrorResponse(
      404,
      "not_found",
      `Role with id: ${roleId} not found`
    )
  }

  const userIds = getStringArrayValue(body, "users")
  staticUserRbacRoleLinks = staticUserRbacRoleLinks.filter(
    (link) =>
      !(link.rbac_role_id === roleId && userIds.includes(link.user_id))
  )

  return createStaticJsonResponse({
    ids: userIds,
    object: "role_user",
    deleted: true,
  })
}

function pushUniqueStaticUserRbacRoleLink(
  userId: string,
  roleId: string
): void {
  if (
    staticUserRbacRoleLinks.some(
      (link) => link.user_id === userId && link.rbac_role_id === roleId
    )
  ) {
    return
  }

  staticUserRbacRoleLinks.push({
    user_id: userId,
    rbac_role_id: roleId,
  })
}

