const observeStoreLocale: MiddlewareFunction = (
  req: MedusaRequest,
  res: MedusaResponse,
  next: MedusaNextFunction
): void => {
  if (req.locale) {
    res.setHeader("x-medusa-locale-proof", req.locale)
  }
  next()
}

const observePublishableKeyContext: MiddlewareFunction = (
  req: MedusaRequest,
  res: MedusaResponse,
  next: MedusaNextFunction
): void => {
  const context = getMedusaRequestPublishableKeyContext(req)
  if (context) {
    res.setHeader("x-medusa-publishable-key-proof", context.key)
    res.setHeader(
      "x-medusa-publishable-sales-channel-count",
      context.sales_channel_ids.length
    )
  }
  next()
}

const observeStoreAuthContext: MiddlewareFunction = (
  req: MedusaRequest,
  res: MedusaResponse,
  next: MedusaNextFunction
): void => {
  const context = getMedusaRequestAuthContext(req)
  res.setHeader(
    "x-medusa-auth-proof",
    context?.actor_type ?? "unauthenticated"
  )
  next()
}

const ensureStaticPublishableSalesChannelMatch: MiddlewareFunction = (
  req: MedusaRequest,
  res: MedusaResponse,
  next: MedusaNextFunction
): void => {
  if (
    req.method?.toUpperCase() !== "POST" ||
    getStaticRequestPath(req) !== "/store/carts" ||
    typeof req.get("x-publishable-api-key") !== "string"
  ) {
    next()
    return
  }

  const salesChannelIds = getStaticPublishableSalesChannelScopeIds(req)
  if (salesChannelIds.length === 0) {
    next()
    return
  }

  const body = isRecord(req) ? getRecordValue(req, "validatedBody") : undefined
  const salesChannelId = body
    ? getStringValue(body, "sales_channel_id")
    : undefined
  const errors: string[] = []

  if (salesChannelId && !salesChannelIds.includes(salesChannelId)) {
    errors.push(
      `Sales channel ID in payload ${salesChannelId} is not associated with the Publishable API Key in the header.`
    )
  }

  if (!salesChannelId) {
    if (salesChannelIds.length > 1) {
      errors.push(
        "Cannot assign sales channel to cart. The Publishable API Key in the header has multiple associated sales channels. Please provide a sales channel ID in the request body."
      )
    } else if (body) {
      body.sales_channel_id = salesChannelIds[0]
    }
  }

  if (errors.length > 0) {
    res.status(400).json({
      errors,
      message:
        "Provided request body contains errors. Please check the data and retry the request",
    })
    return
  }

  next()
}

function getStaticRequestPath(req: MedusaRequest): string {
  if (!isRecord(req)) {
    return ""
  }

  const pathValue = getStringValue(req, "path")
  if (pathValue) {
    return pathValue
  }

  const urlValue =
    getStringValue(req, "url") ?? getStringValue(req, "originalUrl")
  if (!urlValue) {
    return ""
  }

  return urlValue.split("?")[0] ?? ""
}

function getStaticPublishableSalesChannelScopeIds(
  req: MedusaRequest
): string[] {
  const scopeRequest = req as MedusaRequest & {
    publishableApiKeyScopes?: { sales_channel_ids?: unknown }
  }
  const scopedIds = normalizeStringFilter(
    scopeRequest.publishableApiKeyScopes?.sales_channel_ids
  )
  if (scopedIds.length > 0) {
    return scopedIds
  }

  return getMedusaRequestPublishableKeyContext(req)?.sales_channel_ids ?? []
}

const markStaticHttpProof: MiddlewareFunction = (
  req: MedusaRequest,
  res: MedusaResponse,
  next: MedusaNextFunction
): void => {
  req.context = {
    ...req.context,
    staticHttpProof: true,
  }
  res.setHeader("x-medusa-http-proof", "static-fetch")
  next()
}

function getStaticAuthorizationHeader(req: MedusaRequest): string | undefined {
  const value = req.headers.authorization

  if (Array.isArray(value)) {
    return value[0]
  }

  return value
}

function decodeStaticBasicAuthToken(
  authHeader: string | undefined
): string | undefined {
  if (!authHeader) {
    return undefined
  }

  const [tokenType, token] = authHeader.split(" ")
  if (tokenType?.toLowerCase() !== "basic" || !token) {
    return undefined
  }

  let normalizedToken = token
  if (!token.startsWith("sk_")) {
    try {
      normalizedToken = atob(token)
    } catch {
      return undefined
    }
  }

  if (normalizedToken.endsWith(":")) {
    normalizedToken = normalizedToken.slice(0, -1)
  }

  return normalizedToken.startsWith("sk_") ? normalizedToken : undefined
}

const applyStaticSecretApiKeyAuth: MiddlewareFunction = (
  req: MedusaRequest,
  res: MedusaResponse,
  next: MedusaNextFunction
): void => {
  const authorization = getStaticAuthorizationHeader(req)
  if (!authorization?.toLowerCase().startsWith("basic ")) {
    next()
    return
  }

  const token = decodeStaticBasicAuthToken(authorization)
  const apiKey = token
    ? staticApiKeys.find(
        (candidate) =>
          candidate.token === token && candidate.type === "secret"
      )
    : undefined

  if (!apiKey || apiKey.revoked_at) {
    res.status(401).json({ message: "Unauthorized" })
    return
  }

  setMedusaRequestAuthContext(req, {
    actor_id: apiKey.id,
    actor_type: "api-key",
    auth_identity_id: "",
    app_metadata: {},
    user_metadata: {},
  })

  next()
}

const applyStaticBearerAuth: MiddlewareFunction = (
  req: MedusaRequest,
  _res: MedusaResponse,
  next: MedusaNextFunction
): void => {
  const authContext = decodeStaticBearerAuthContext(
    getStaticAuthorizationHeader(req)
  )

  if (authContext) {
    setMedusaRequestAuthContext(req, authContext, { persistSession: true })
  }

  next()
}

function decodeStaticBearerAuthContext(
  authHeader: string | undefined
): AuthContext | null {
  if (!authHeader) {
    return null
  }

  const [tokenType, token] = authHeader.split(" ")
  if (tokenType?.toLowerCase() !== "bearer" || !token) {
    return null
  }

  try {
    const parsed = decodeStaticBearerPayload(token)
    if (!isRecord(parsed)) {
      return null
    }

    const actorType = getStringValue(parsed, "actor_type")
    const authIdentityId = getStringValue(parsed, "auth_identity_id")
    if (!actorType || !authIdentityId) {
      return decodeStaticAuthIdentityPayloadContext(parsed)
    }

    return {
      actor_id: getStringValue(parsed, "actor_id") ?? "",
      actor_type: actorType,
      auth_identity_id: authIdentityId,
      app_metadata: getRecordValue(parsed, "app_metadata") ?? {},
      user_metadata: getRecordValue(parsed, "user_metadata") ?? {},
    }
  } catch {
    return null
  }
}

function decodeStaticAuthIdentityPayloadContext(
  payload: Record<string, unknown>
): AuthContext | null {
  const authIdentityId = getStringValue(payload, "id")
  if (!authIdentityId) {
    return null
  }

  const providerIdentitiesValue = payload.provider_identities
  const providerIdentities = Array.isArray(providerIdentitiesValue)
    ? providerIdentitiesValue.filter(isRecord)
    : []
  const providerIdentity = providerIdentities[0]
  const appMetadata = getRecordValue(payload, "app_metadata") ?? {}
  const userMetadata =
    getRecordValue(providerIdentity, "user_metadata") ??
    getRecordValue(payload, "user_metadata") ??
    {}

  return {
    actor_id: getStringValue(appMetadata, "customer_id") ?? "",
    actor_type: "customer",
    auth_identity_id: authIdentityId,
    app_metadata: appMetadata,
    user_metadata: userMetadata,
  }
}

function decodeStaticBearerPayload(token: string): unknown {
  if (token.startsWith("static.")) {
    try {
      return JSON.parse(atob(token.slice("static.".length)))
    } catch {
      return undefined
    }
  }

  const payloadSegment = token.split(".")[1]
  if (!payloadSegment) {
    return undefined
  }

  return decodeStaticJwtSegment(payloadSegment)
}

function decodeStaticJwtSegment(segment: string): unknown {
  const base64 = segment
    .replace(/-/g, "+")
    .replace(/_/g, "/")
    .padEnd(Math.ceil(segment.length / 4) * 4, "=")

  try {
    return JSON.parse(atob(base64))
  } catch {
    return undefined
  }
}

