export const staticHttpProofResourcesAfterManifest: StaticHttpResourceSetInput =
  {
    middlewares: [
      {
        matcher: "/store/carts",
        methods: ["POST"],
        handler: ensureStaticPublishableSalesChannelMatch,
      },
      {
        matcher: "/http-proof",
        pathMatching: "prefix",
        methods: ["GET", "POST"],
        handler: markStaticHttpProof,
      },
    ],
    errorHandler: errorHandler() as MedusaErrorHandlerFunction,
  }

export function createStaticHttpProofRequestScope(): MedusaRequest["scope"] {
  // The package declaration preserves Awilix's broad createScope return, but
  // createMedusaContainer installs Medusa's registerAdd extension at runtime.
  return staticHttpProofContainer.createScope() as MedusaRequest["scope"]
}

export const createStaticHttpProofSession =
  staticHttpProofSessionHooks.createSession

export const commitStaticHttpProofSession =
  staticHttpProofSessionHooks.commitSession

export async function prepareStaticHttpProofRequest(
  req: MedusaRequest,
  fetchRequest: Request
): Promise<void> {
  const url = new URL(fetchRequest.url)
  staticCurrentStoreRequestCustomerId = url.pathname.startsWith("/store/")
    ? fetchRequest.headers.get("x-medusa-customer-id-proof")
    : null
  staticForcePaymentAuthorizationFailure =
    fetchRequest.headers.get("x-medusa-payment-authorization-fails-proof") ===
    "1"

  if (fetchRequest.headers.has("x-medusa-access-token")) {
    const bearerAuthContext = decodeStaticBearerAuthContext(
      fetchRequest.headers.get("authorization") ?? undefined
    )
    const actorId = bearerAuthContext?.actor_id || "user_worker_http_proof"
    staticCurrentAdminActorId = actorId
    ensureStaticAdminActorUser(actorId, bearerAuthContext?.user_metadata ?? {})

    setMedusaRequestAuthContext(
      req,
      {
        actor_id: actorId,
        actor_type: "user",
        auth_identity_id:
          bearerAuthContext?.auth_identity_id ??
          "auth_identity_worker_http_proof",
        app_metadata: bearerAuthContext?.app_metadata ?? {},
        user_metadata: bearerAuthContext?.user_metadata ?? {},
      },
      { persistSession: true }
    )
  }

  await prepareStaticAuthUpdateTokenPayload(req, fetchRequest, url)

  const customerId = fetchRequest.headers.get("x-medusa-customer-id-proof")
  if (!customerId) {
    return
  }

  setMedusaRequestAuthContext(
    req,
    {
      actor_id: customerId,
      actor_type: "customer",
      auth_identity_id: "auth_identity_worker_http_proof",
      app_metadata: {},
      user_metadata: {},
    },
    { persistSession: true }
  )
}

async function prepareStaticAuthUpdateTokenPayload(
  req: MedusaRequest,
  fetchRequest: Request,
  url: URL
): Promise<void> {
  const authUpdateMatch = url.pathname.match(
    /^\/auth\/([^/]+)\/([^/]+)\/update$/
  )
  if (!authUpdateMatch || fetchRequest.method !== "POST") {
    return
  }

  const actorType = decodeURIComponent(authUpdateMatch[1])
  const provider = decodeURIComponent(authUpdateMatch[2])
  const token = getStaticBearerToken(
    fetchRequest.headers.get("authorization") ?? undefined
  )
  const payload = token
    ? await verifyStaticResetToken(
        token,
        getStaticRequestNowMs(
          fetchRequest.headers.get("x-medusa-test-now") ?? undefined
        )
      )
    : undefined

  if (!isStaticUpdateProviderPayload(payload, actorType, provider)) {
    return
  }

  setMedusaRequestValidatedTokenPayload(req, {
    actor_type: actorType,
    entity_id: payload.entity_id,
    provider,
  })
}

type StaticUpdateProviderPayload = {
  actor_type: string
  entity_id: string
  provider: string
}

function isStaticUpdateProviderPayload(
  value: unknown,
  actorType: string,
  provider: string
): value is StaticUpdateProviderPayload {
  return (
    isRecord(value) &&
    getStringValue(value, "actor_type") === actorType &&
    !!getStringValue(value, "entity_id") &&
    getStringValue(value, "provider") === provider
  )
}

