function createStaticAdminReturnShippingMethodResponse(
  returnId: string,
  body: Record<string, unknown>
): Response {
  const claim = getStaticClaimByReturnId(returnId)
  if (!claim) {
    return createStaticReturnNotFoundResponse(returnId)
  }

  const shippingMethod = {
    ...createStaticClaimShippingMethod(body, "inbound"),
    return_id: returnId,
  }
  const existing = getStaticClaimShippingMethods(claim).filter(
    (method) => getStringValue(method, "direction") !== "inbound"
  )
  setStaticClaimShippingMethods(claim, [...existing, shippingMethod])

  return createStaticJsonResponse({
    order_preview: createStaticClaimOrderPreview(claim),
    return: createStaticClaimReturn(claim),
  })
}

function createStaticAdminReturnShippingMethodActionResponse(
  returnId: string,
  actionId: string,
  body: Record<string, unknown>
): Response {
  const claim = getStaticClaimByReturnId(returnId)
  if (!claim) {
    return createStaticReturnNotFoundResponse(returnId)
  }

  const methods = getStaticClaimShippingMethods(claim).map((method) => {
    if (getStringValue(method, "id") !== actionId) {
      return method
    }

    const customAmount = getNullableNumberValue(body, "custom_amount")
    const amount =
      customAmount ??
      getStaticShippingOptionAmount(getStringValue(method, "shipping_option_id"))

    return {
      ...method,
      subtotal: amount,
      amount,
      is_custom_amount: customAmount !== null,
      actions: getStaticNestedRows(method, "actions").map((action) => ({
        ...action,
        ...(getStringValue(body, "internal_note")
          ? { internal_note: getStringValue(body, "internal_note") }
          : {}),
      })),
    }
  })
  setStaticClaimShippingMethods(claim, methods)

  return createStaticJsonResponse({
    order_preview: createStaticClaimOrderPreview(claim),
    return: createStaticClaimReturn(claim),
  })
}

