function createStaticAdminReturnReceiveItemActionResponse(
  returnId: string,
  actionId: string,
  body: Record<string, unknown>
): Response {
  const quantity = getNumberValue(body, "quantity") ?? 0
  if (quantity <= 0) {
    const claim = getStaticClaimByReturnId(returnId)
    const itemId =
      claim?.claim_items
        .map((item) => getStringValue(item, "item_id"))
        .find((id): id is string => typeof id === "string") ?? actionId

    return createStaticErrorResponse(
      400,
      "invalid_data",
      `Quantity to receive return of item ${itemId} is required.`
    )
  }

  const claim = getStaticClaimByReturnId(returnId)
  if (!claim) {
    return createStaticReturnNotFoundResponse(returnId)
  }

  claim.claim_items = claim.claim_items.map((item) =>
    getStaticNestedRows(item, "actions").some(
      (action) => getStringValue(action, "id") === actionId
    )
      ? {
          ...item,
          received_quantity: quantity,
        }
      : item
  )

  return createStaticJsonResponse({
    order_preview: createStaticClaimOrderPreview(claim),
    return: createStaticClaimReturn(claim),
  })
}

