function createStaticTaxRateFromBody(
  body: Record<string, unknown>
): StaticTaxRate {
  const taxRegionId = getStringValue(body, "tax_region_id")
  if (!taxRegionId) {
    throw new MedusaError(
      MedusaError.Types.INVALID_DATA,
      "tax_region_id is required"
    )
  }

  staticTaxRateSequence += 1
  const timestamp = new Date(
    Date.UTC(2026, 5, 21, 5, 20, staticTaxRateSequence)
  ).toISOString()
  const taxRate: StaticTaxRate = {
    id:
      getStringValue(body, "id") ??
      `txrate_worker_http_proof_${staticTaxRateSequence}`,
    name: getStringValue(body, "name") ?? "Worker Tax Rate",
    tax_region_id: taxRegionId,
    rate: typeof body.rate === "number" ? body.rate : 0,
    code: getStringValue(body, "code") ?? "WORKER_TAX",
    is_combinable: body.is_combinable === true,
    is_default: body.is_default === true,
    created_by: getNullableStringValue(body, "created_by") ?? "test",
    metadata: getRecordValue(body, "metadata") ?? null,
    rules: [],
    created_at: timestamp,
    updated_at: timestamp,
    deleted_at: null,
  }
  taxRate.rules = parseStaticTaxRateRulesForRate(taxRate.id, body.rules, timestamp)

  staticTaxRates = [...staticTaxRates, taxRate]
  return taxRate
}

function parseStaticTaxRateRulesForRate(
  taxRateId: string,
  input: unknown,
  timestamp = staticCartTimestamp,
  startIndex = 0
): StaticTaxRateRule[] {
  if (!Array.isArray(input)) {
    return []
  }

  return input.flatMap((rule, index): StaticTaxRateRule[] => {
    if (!isRecord(rule)) {
      return []
    }

    const reference = getStringValue(rule, "reference")
    const referenceId = getStringValue(rule, "reference_id")
    if (!reference || !referenceId) {
      return []
    }

    return [
      {
        id:
          getStringValue(rule, "id") ??
          `txrule_worker_http_proof_${taxRateId}_${startIndex + index + 1}`,
        tax_rate_id: getStringValue(rule, "tax_rate_id") ?? taxRateId,
        reference,
        reference_id: referenceId,
        created_by: getNullableStringValue(rule, "created_by") ?? "test",
        metadata: getRecordValue(rule, "metadata") ?? null,
        created_at: getStringValue(rule, "created_at") ?? timestamp,
        updated_at: getStringValue(rule, "updated_at") ?? timestamp,
        deleted_at: getNullableStringValue(rule, "deleted_at"),
      },
    ]
  })
}

