function createStaticProductsFromWorkflowInput(input: unknown): StaticProduct[] {
  if (!isRecord(input) || !Array.isArray(input.products)) {
    return []
  }

  const productInputs = input.products.filter(isRecord)
  validateStaticProductVariantInventoryItemsForProductInputs(productInputs)

  const created = productInputs.flatMap((product): StaticProduct[] => {
    if (!isRecord(product) || typeof product.title !== "string") {
      return []
    }

    staticProductSequence += 1
    const id = `prod_worker_http_proof_${staticProductSequence}`
    const timestamp = new Date(
      Date.UTC(2026, 5, 21, 3, 0, staticProductSequence)
    ).toISOString()
    const options = createStaticProductOptions(
      id,
      isArrayValue(product.options) ? product.options : []
    )
    const images = createStaticProductImages(
      id,
      isArrayValue(product.images) ? product.images : [],
      timestamp
    )
    const isGiftcard = product.is_giftcard === true
    const requestedDiscountable =
      typeof product.discountable === "boolean" ? product.discountable : true
    const discountable = isGiftcard ? false : requestedDiscountable

    return [
      {
        id,
        title: product.title,
        subtitle: getNullableStringValue(product, "subtitle"),
        handle:
          getStringValue(product, "handle") ??
          product.title.toLowerCase().replace(/\s+/g, "-"),
        status: getStringValue(product, "status") ?? "published",
        description: getNullableStringValue(product, "description"),
        thumbnail:
          getNullableStringValue(product, "thumbnail") ??
          images[0]?.url ??
          null,
        is_giftcard: isGiftcard,
        discountable,
        weight: getNullableNumberValue(product, "weight"),
        length: getNullableNumberValue(product, "length"),
        height: getNullableNumberValue(product, "height"),
        width: getNullableNumberValue(product, "width"),
        hs_code: getNullableStringValue(product, "hs_code"),
        origin_country: getNullableStringValue(product, "origin_country"),
        mid_code: getNullableStringValue(product, "mid_code"),
        material: getNullableStringValue(product, "material"),
        metadata: getRecordValue(product, "metadata") ?? null,
        collection_id: getNullableStringValue(product, "collection_id"),
        type_id: getNullableStringValue(product, "type_id"),
        external_id: getNullableStringValue(product, "external_id"),
        shipping_profile_id: getNullableStringValue(
          product,
          "shipping_profile_id"
        ),
        tags: createStaticProductInlineTags(
          isArrayValue(product.tags) ? product.tags : []
        ),
        options,
        variants: createStaticProductVariants(
          id,
          isArrayValue(product.variants) ? product.variants : [],
          options
        ),
        images,
        created_at: timestamp,
        updated_at: timestamp,
        deleted_at: null,
      },
    ]
  })

  staticProducts = [...staticProducts, ...created]
  created.forEach((product, index) => {
    const categoryIds = getStaticProductCategoryIdsFromProductInput(
      productInputs[index]
    )
    const salesChannelIds = getStaticProductSalesChannelIdsFromProductInput(
      productInputs[index]
    )

    for (const categoryId of categoryIds) {
      staticProductCategoryProductLinks.push({
        category_id: categoryId,
        product_id: product.id,
      })
    }

    for (const salesChannelId of salesChannelIds) {
      const exists = staticProductSalesChannelLinks.some(
        (link) =>
          link.product_id === product.id &&
          link.sales_channel_id === salesChannelId
      )

      if (!exists) {
        staticProductSalesChannelLinks.push({
          product_id: product.id,
          sales_channel_id: salesChannelId,
        })
      }
    }
  })

  return created
}

function validateStaticProductVariantInventoryItemsForProductInputs(
  products: Array<Record<string, unknown>>
): void {
  const duplicateVariantIds: string[] = []
  const inventoryItemIds = new Set<string>()
  let variantOffset = 0

  for (const product of products) {
    const variants = isArrayValue(product.variants)
      ? product.variants.filter(isRecord)
      : []

    for (const variant of variants) {
      variantOffset += 1
      const seenForVariant = new Set<string>()
      const duplicateIdsForVariant = new Set<string>()

      for (const inventoryItem of getStaticNestedRows(
        variant,
        "inventory_items"
      )) {
        const inventoryItemId = getStringValue(
          inventoryItem,
          "inventory_item_id"
        )
        if (!inventoryItemId) {
          continue
        }

        if (seenForVariant.has(inventoryItemId)) {
          duplicateIdsForVariant.add(inventoryItemId)
        }

        seenForVariant.add(inventoryItemId)
        inventoryItemIds.add(inventoryItemId)
      }

      if (duplicateIdsForVariant.size > 0) {
        duplicateVariantIds.push(
          `variant_worker_http_proof_${staticProductVariantSequence + variantOffset}`
        )
      }
    }
  }

  if (duplicateVariantIds.length > 0) {
    throw new MedusaError(
      MedusaError.Types.INVALID_DATA,
      `Cannot associate duplicate inventory items to variant(s) ${duplicateVariantIds.join(
        "\n"
      )}`
    )
  }

  const missingInventoryItemIds = [...inventoryItemIds].filter(
    (inventoryItemId) =>
      !staticInventoryItems.some((item) => item.id === inventoryItemId)
  )

  if (missingInventoryItemIds.length > 0) {
    throw new MedusaError(
      MedusaError.Types.INVALID_DATA,
      `Inventory Items with ids: ${missingInventoryItemIds.join(
        ", "
      )} was not found`
    )
  }
}

function updateStaticProductsFromWorkflowInput(input: unknown): StaticProduct[] {
  if (!isRecord(input)) {
    return []
  }

  const selector = getRecordValue(input, "selector")
  const update = getRecordValue(input, "update")
  const idFilters = normalizeStringFilter(selector?.id)
  if (!update || idFilters.length === 0) {
    return []
  }

  const updatedProducts: StaticProduct[] = []
  staticProducts = staticProducts.map((product) => {
    if (!idFilters.includes(product.id)) {
      return product
    }

    const options = isArrayValue(update.options)
      ? createStaticProductOptions(product.id, update.options)
      : product.options

    const updated: StaticProduct = {
      ...product,
      title: getStringValue(update, "title") ?? product.title,
      handle: getStringValue(update, "handle") ?? product.handle,
      status: getStringValue(update, "status") ?? product.status,
      description: Object.prototype.hasOwnProperty.call(update, "description")
        ? getNullableStringValue(update, "description")
        : product.description,
      is_giftcard: Object.prototype.hasOwnProperty.call(update, "is_giftcard")
        ? update.is_giftcard === true
        : product.is_giftcard,
      collection_id: Object.prototype.hasOwnProperty.call(
        update,
        "collection_id"
      )
        ? getNullableStringValue(update, "collection_id")
        : product.collection_id,
      type_id: Object.prototype.hasOwnProperty.call(update, "type_id")
        ? getNullableStringValue(update, "type_id")
        : product.type_id,
      external_id: Object.prototype.hasOwnProperty.call(update, "external_id")
        ? getNullableStringValue(update, "external_id")
        : product.external_id,
      metadata: Object.prototype.hasOwnProperty.call(update, "metadata")
        ? mergeStaticProductMetadata(product.metadata, update.metadata)
        : product.metadata,
      weight: Object.prototype.hasOwnProperty.call(update, "weight")
        ? getNullableNumberValue(update, "weight")
        : product.weight,
      length: Object.prototype.hasOwnProperty.call(update, "length")
        ? getNullableNumberValue(update, "length")
        : product.length,
      height: Object.prototype.hasOwnProperty.call(update, "height")
        ? getNullableNumberValue(update, "height")
        : product.height,
      width: Object.prototype.hasOwnProperty.call(update, "width")
        ? getNullableNumberValue(update, "width")
        : product.width,
      shipping_profile_id: Object.prototype.hasOwnProperty.call(
        update,
        "shipping_profile_id"
      )
        ? getNullableStringValue(update, "shipping_profile_id")
        : product.shipping_profile_id,
      tags: isArrayValue(update.tags)
        ? createStaticProductInlineTags(update.tags)
        : product.tags,
      options,
      variants: isArrayValue(update.variants)
        ? updateStaticProductVariants(product, update.variants, options)
        : product.variants,
      images: isArrayValue(update.images)
        ? createStaticProductImages(product.id, update.images, product.created_at)
        : product.images,
      updated_at: new Date(Date.UTC(2026, 5, 21, 3, 30, 0)).toISOString(),
    }

    if (Object.prototype.hasOwnProperty.call(update, "categories")) {
      replaceStaticProductCategoryLinks(
        product.id,
        getStaticProductCategoryIdsFromProductInput(update)
      )
    }

    if (Object.prototype.hasOwnProperty.call(update, "sales_channels")) {
      replaceStaticProductSalesChannelLinks(
        product.id,
        getStaticProductSalesChannelIdsFromProductInput(update)
      )
    }

    updatedProducts.push(updated)
    return updated
  })

  return updatedProducts
}

function batchStaticProductsFromWorkflowInput(input: unknown): {
  created: StaticProduct[]
  updated: StaticProduct[]
  deleted: string[]
} {
  if (!isRecord(input)) {
    return {
      created: [],
      updated: [],
      deleted: [],
    }
  }

  const created = createStaticProductsFromWorkflowInput({
    products: isArrayValue(input.create) ? input.create : [],
  })

  const updated = (isArrayValue(input.update) ? input.update : [])
    .filter(isRecord)
    .flatMap((productUpdate) => {
      const id = getStringValue(productUpdate, "id")
      if (!id) {
        return []
      }

      const update = { ...productUpdate }
      delete update.id

      return updateStaticProductsFromWorkflowInput({
        selector: { id },
        update,
      })
    })

  const deleted = deleteStaticProductsFromWorkflowInput({
    ids: normalizeStringFilter(input.delete),
  })

  return {
    created,
    updated,
    deleted,
  }
}

function mergeStaticProductMetadata(
  existing: Record<string, unknown> | null,
  update: unknown
): Record<string, unknown> | null {
  if (update === null) {
    return null
  }

  if (!isRecord(update)) {
    return existing
  }

  const merged: Record<string, unknown> = { ...(existing ?? {}) }

  for (const [key, value] of Object.entries(update)) {
    if (value === "") {
      delete merged[key]
    } else {
      merged[key] = value
    }
  }

  return merged
}

function deleteStaticProductsFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)
  if (ids.length === 0) {
    return []
  }

  const inventoryItemIdsForDeletedProducts = getStaticProductInventoryItemIds(
    ids
  )
  assertStaticInventoryItemsCanBeRemoved(inventoryItemIdsForDeletedProducts)

  const deletedAt = new Date(Date.UTC(2026, 5, 21, 3, 45, 0)).toISOString()
  staticProducts = staticProducts.map((product) =>
    ids.includes(product.id)
      ? {
          ...product,
          deleted_at: deletedAt,
          updated_at: deletedAt,
        }
      : product
  )
  pruneStaticInventoryItemsWithoutActiveProductLinks(
    inventoryItemIdsForDeletedProducts
  )

  return ids
}

function assertStaticInventoryItemsCanBeRemoved(inventoryItemIds: string[]): void {
  if (inventoryItemIds.length === 0) {
    return
  }

  const reservedInventoryItemIds = [
    ...new Set(
      staticReservations
        .filter((reservation) =>
          inventoryItemIds.includes(reservation.inventory_item_id)
        )
        .map((reservation) => reservation.inventory_item_id)
    ),
  ]

  if (reservedInventoryItemIds.length === 0) {
    return
  }

  throw new MedusaError(
    MedusaError.Types.INVALID_DATA,
    `Cannot remove following inventory item(s) since they have reservations: [${reservedInventoryItemIds.join(
      ", "
    )}].`
  )
}

function getStaticProductInventoryItemIds(productIds: string[]): string[] {
  return [
    ...new Set(
      staticProducts
        .filter((product) => productIds.includes(product.id))
        .flatMap((product) => product.variants)
        .flatMap((variant) =>
          variant.inventory_items.map((link) => link.inventory_item_id)
        )
    ),
  ]
}

function pruneStaticInventoryItemsWithoutActiveProductLinks(
  inventoryItemIds: string[]
): void {
  if (inventoryItemIds.length === 0) {
    return
  }

  const activeInventoryItemIds = new Set(
    staticProducts
      .filter((product) => !product.deleted_at)
      .flatMap((product) => product.variants)
      .flatMap((variant) =>
        variant.inventory_items.map((link) => link.inventory_item_id)
      )
  )

  const unusedInventoryItemIds = inventoryItemIds.filter(
    (inventoryItemId) => !activeInventoryItemIds.has(inventoryItemId)
  )

  deleteStaticInventoryItemsFromWorkflowInput(unusedInventoryItemIds)
}

function getStaticProductCategoryIdsFromProductInput(
  product: Record<string, unknown>
): string[] {
  if (!Array.isArray(product.categories)) {
    return []
  }

  return product.categories.flatMap((category): string[] => {
    if (!isRecord(category)) {
      return []
    }

    const id = getStringValue(category, "id")
    return id ? [id] : []
  })
}

function replaceStaticProductCategoryLinks(
  productId: string,
  categoryIds: string[]
): void {
  staticProductCategoryProductLinks = staticProductCategoryProductLinks.filter(
    (link) => link.product_id !== productId
  )

  for (const categoryId of categoryIds) {
    const exists = staticProductCategoryProductLinks.some(
      (link) => link.product_id === productId && link.category_id === categoryId
    )

    if (!exists) {
      staticProductCategoryProductLinks.push({
        product_id: productId,
        category_id: categoryId,
      })
    }
  }
}

function replaceStaticProductSalesChannelLinks(
  productId: string,
  salesChannelIds: string[]
): void {
  staticProductSalesChannelLinks = staticProductSalesChannelLinks.filter(
    (link) => link.product_id !== productId
  )

  for (const salesChannelId of salesChannelIds) {
    pushUniqueStaticProductSalesChannelLink(productId, salesChannelId)
  }
}

function toStaticProductDimensionResponseValue(
  value: number | null
): string | null {
  return value === null ? null : String(value)
}

function getStaticProductSalesChannelIdsFromProductInput(
  product: Record<string, unknown>
): string[] {
  if (!Array.isArray(product.sales_channels)) {
    return []
  }

  return product.sales_channels.flatMap((salesChannel): string[] => {
    if (!isRecord(salesChannel)) {
      return []
    }

    const id = getStringValue(salesChannel, "id")
    return id ? [id] : []
  })
}

function createStaticProductImages(
  productId: string,
  images: unknown[],
  timestamp: string
): StaticProductImage[] {
  return images.filter(isRecord).flatMap((image, index): StaticProductImage[] => {
    const url = getStringValue(image, "url")
    if (!url) {
      return []
    }

    return [
      {
        id: getStringValue(image, "id") ?? `img_${productId}_${index}`,
        url,
        rank: index,
        product_id: productId,
        created_at: timestamp,
        updated_at: timestamp,
      },
    ]
  })
}

function createStaticProductInlineTags(tags: unknown[]): StaticProductTag[] {
  return tags.filter(isRecord).flatMap((tag): StaticProductTag[] => {
    const id = getStringValue(tag, "id")
    if (!id) {
      return []
    }

    const existing = staticProductTags.find((candidate) => candidate.id === id)
    return [
      existing ?? {
        id,
        value: getStringValue(tag, "value") ?? id,
        created_at: "2026-06-21T00:45:00.000Z",
        updated_at: "2026-06-21T00:45:00.000Z",
        metadata: null,
      },
    ]
  })
}

function createStaticProductOptions(
  productId: string,
  options: unknown[]
): StaticProductOption[] {
  return options.filter(isRecord).flatMap((option, optionIndex) => {
    const title = getStringValue(option, "title")
    if (!title) {
      return []
    }

    const id =
      getStringValue(option, "id") ?? `opt_${productId}_${optionIndex}`
    const values = isArrayValue(option.values) ? option.values : []

    return [
      {
        id,
        product_id: productId,
        created_at: "2026-06-21T03:05:00.000Z",
        updated_at: "2026-06-21T03:05:00.000Z",
        title,
        values: values.flatMap((value, valueIndex) =>
          typeof value === "string"
            ? [
                {
                  id: `optval_${productId}_${optionIndex}_${valueIndex}`,
                  value,
                  option_id: id,
                },
              ]
            : []
        ),
      },
    ]
  })
}

function createStaticProductOptionsFromWorkflowInput(
  input: unknown
): StaticProductOption[] {
  const optionInputs = getStaticPayloadRows(input, "product_options")
  if (optionInputs.length === 0) {
    return []
  }

  const createdOptions: StaticProductOption[] = []
  staticProducts = staticProducts.map((product) => {
    const productOptionInputs = optionInputs.filter(
      (option) => getStringValue(option, "product_id") === product.id
    )

    if (productOptionInputs.length === 0) {
      return product
    }

    const newOptions = productOptionInputs.flatMap(
      (option, optionOffset): StaticProductOption[] => {
        const title = getStringValue(option, "title")
        if (!title) {
          return []
        }

        const optionIndex = product.options.length + optionOffset
        const id =
          getStringValue(option, "id") ?? `opt_${product.id}_${optionIndex}`
        const values = isArrayValue(option.values) ? option.values : []
        const now = getStaticRowTimestamp(option)

        return [
          {
            id,
            product_id: product.id,
            created_at: now,
            updated_at: now,
            title,
            values: values.flatMap(
              (value, valueIndex): StaticProductOption["values"] => {
                if (typeof value !== "string") {
                  return []
                }

                return [
                  {
                    id: `optval_${product.id}_${optionIndex}_${valueIndex}`,
                    value,
                    option_id: id,
                  },
                ]
              }
            ),
          },
        ]
      }
    )

    if (newOptions.length === 0) {
      return product
    }

    createdOptions.push(...newOptions)

    return {
      ...product,
      options: [...product.options, ...newOptions],
      updated_at: new Date(Date.UTC(2026, 5, 21, 3, 35, 0)).toISOString(),
    }
  })

  return createdOptions
}

function deleteStaticProductOptionsFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const optionIds = normalizeStringFilter(input.ids)
  if (optionIds.length === 0) {
    return []
  }

  staticProducts = staticProducts.map((product) => ({
    ...product,
    options: product.options.filter((option) => !optionIds.includes(option.id)),
    updated_at: product.options.some((option) => optionIds.includes(option.id))
      ? new Date(Date.UTC(2026, 5, 21, 3, 40, 0)).toISOString()
      : product.updated_at,
  }))

  return optionIds
}

function createStaticProductVariants(
  productId: string,
  variants: unknown[],
  productOptions: StaticProductOption[]
): StaticProductVariant[] {
  return variants.flatMap((variant): StaticProductVariant[] => {
    if (!isRecord(variant)) {
      return []
    }

    staticProductVariantSequence += 1
    const id = `variant_worker_http_proof_${staticProductVariantSequence}`
    const timestamp = new Date(
      Date.UTC(2026, 5, 21, 3, 10, staticProductVariantSequence)
    ).toISOString()
    const prices = isArrayValue(variant.prices) ? variant.prices : []
    const inventoryItems = createStaticProductVariantInventoryItemsForVariant(
      id,
      variant
    )

    return [
      {
        id,
        title: getStringValue(variant, "title") ?? "Worker Product Variant",
        sku: getNullableStringValue(variant, "sku"),
        ean: getNullableStringValue(variant, "ean"),
        upc: getNullableStringValue(variant, "upc"),
        barcode: getNullableStringValue(variant, "barcode"),
        origin_country: getNullableStringValue(variant, "origin_country"),
        product_id: productId,
        manage_inventory: variant.manage_inventory === true,
        allow_backorder: variant.allow_backorder === true,
        price_set: {
          prices: createStaticProductPrices(prices, timestamp),
        },
        inventory_items: inventoryItems,
        options: createStaticProductVariantOptions(variant, productOptions),
        calculated_price: createStaticCalculatedPrice(prices),
        created_at: timestamp,
        updated_at: timestamp,
      },
    ]
  })
}

function updateStaticProductVariants(
  product: StaticProduct,
  variants: unknown[],
  productOptions: StaticProductOption[]
): StaticProductVariant[] {
  const variantInputs = variants.filter(isRecord)
  const updatedVariants = product.variants.map((variant) => {
    const update = variantInputs.find(
      (candidate) => getStringValue(candidate, "id") === variant.id
    )

    return update
      ? updateStaticProductVariant(variant, update, productOptions)
      : variant
  })

  const newVariantInputs = variantInputs.filter(
    (variant) => !getStringValue(variant, "id")
  )

  return [
    ...updatedVariants,
    ...createStaticProductVariants(product.id, newVariantInputs, productOptions),
  ]
}

function updateStaticProductVariant(
  variant: StaticProductVariant,
  update: Record<string, unknown>,
  productOptions: StaticProductOption[]
): StaticProductVariant {
  const timestamp = new Date(Date.UTC(2026, 5, 21, 3, 35, 0)).toISOString()
  const prices = isArrayValue(update.prices)
    ? updateStaticProductPrices(
        variant.price_set.prices,
        update.prices,
        timestamp
      )
    : variant.price_set.prices
  const manageInventory = Object.prototype.hasOwnProperty.call(
    update,
    "manage_inventory"
  )
    ? update.manage_inventory === true
    : variant.manage_inventory
  const inventoryItems =
    Object.prototype.hasOwnProperty.call(update, "manage_inventory") &&
    manageInventory === false
      ? []
      : isArrayValue(update.inventory_items)
      ? createStaticProductVariantInventoryItems(update.inventory_items)
      : variant.inventory_items

  return {
    ...variant,
    title: getStringValue(update, "title") ?? variant.title,
    sku: Object.prototype.hasOwnProperty.call(update, "sku")
      ? getNullableStringValue(update, "sku")
      : variant.sku,
    ean: Object.prototype.hasOwnProperty.call(update, "ean")
      ? getNullableStringValue(update, "ean")
      : variant.ean,
    upc: Object.prototype.hasOwnProperty.call(update, "upc")
      ? getNullableStringValue(update, "upc")
      : variant.upc,
    barcode: Object.prototype.hasOwnProperty.call(update, "barcode")
      ? getNullableStringValue(update, "barcode")
      : variant.barcode,
    origin_country: Object.prototype.hasOwnProperty.call(
      update,
      "origin_country"
    )
      ? getNullableStringValue(update, "origin_country")
      : variant.origin_country,
    manage_inventory: manageInventory,
    allow_backorder: Object.prototype.hasOwnProperty.call(
      update,
      "allow_backorder"
    )
      ? update.allow_backorder === true
      : variant.allow_backorder,
    price_set: {
      prices,
    },
    inventory_items: inventoryItems,
    options: isRecord(update.options)
      ? createStaticProductVariantOptions(update, productOptions)
      : variant.options,
    calculated_price: createStaticCalculatedPrice(prices),
    updated_at: timestamp,
  }
}

function createStaticProductVariantsFromWorkflowInput(
  input: unknown
): StaticProductVariant[] {
  if (!isRecord(input) || !Array.isArray(input.product_variants)) {
    return []
  }

  const created: StaticProductVariant[] = []
  const variants = input.product_variants.filter(isRecord)
  staticProducts = staticProducts.map((product) => {
    const productVariants = variants.filter(
      (variant) => getStringValue(variant, "product_id") === product.id
    )

    if (productVariants.length === 0) {
      return product
    }

    const newVariants = createStaticProductVariants(
      product.id,
      productVariants,
      product.options
    )
    created.push(...newVariants)

    return {
      ...product,
      variants: [...product.variants, ...newVariants],
      updated_at: new Date(Date.UTC(2026, 5, 21, 3, 40, 0)).toISOString(),
    }
  })

  return created
}

function updateStaticProductVariantsFromWorkflowInput(
  input: unknown
): StaticProductVariant[] {
  if (!isRecord(input)) {
    return []
  }

  const selector = getRecordValue(input, "selector")
  const update = getRecordValue(input, "update")
  const idFilters = normalizeStringFilter(selector?.id)
  if (!update || idFilters.length === 0) {
    return []
  }

  const updatedVariants: StaticProductVariant[] = []
  staticProducts = staticProducts.map((product) => {
    let productUpdated = false
    const variants = product.variants.map((variant) => {
      if (!idFilters.includes(variant.id)) {
        return variant
      }

      productUpdated = true
      const updated = updateStaticProductVariant(
        variant,
        update,
        product.options
      )
      updatedVariants.push(updated)
      return updated
    })

    return {
      ...product,
      variants,
      updated_at: productUpdated
        ? new Date(Date.UTC(2026, 5, 21, 3, 40, 0)).toISOString()
        : product.updated_at,
    }
  })

  return updatedVariants
}

function deleteStaticProductVariantsFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)
  if (ids.length === 0) {
    return []
  }

  const inventoryItemIdsForDeletedVariants =
    getStaticProductVariantInventoryItemIds(ids)

  staticProducts = staticProducts.map((product) => ({
    ...product,
    variants: product.variants.filter((variant) => !ids.includes(variant.id)),
    updated_at: product.variants.some((variant) => ids.includes(variant.id))
      ? new Date(Date.UTC(2026, 5, 21, 3, 45, 0)).toISOString()
      : product.updated_at,
  }))
  pruneStaticInventoryItemsWithoutActiveProductLinks(
    inventoryItemIdsForDeletedVariants
  )

  return ids
}

function getStaticProductVariantInventoryItemIds(variantIds: string[]): string[] {
  return [
    ...new Set(
      staticProducts
        .flatMap((product) => product.variants)
        .filter((variant) => variantIds.includes(variant.id))
        .flatMap((variant) =>
          variant.inventory_items.map((link) => link.inventory_item_id)
        )
    ),
  ]
}

function batchStaticProductVariantsFromWorkflowInput(input: unknown): {
  created: StaticProductVariant[]
  updated: StaticProductVariant[]
  deleted: string[]
} {
  if (!isRecord(input)) {
    return {
      created: [],
      updated: [],
      deleted: [],
    }
  }

  const created = createStaticProductVariantsFromWorkflowInput({
    product_variants: isArrayValue(input.create) ? input.create : [],
  })

  const updated = (isArrayValue(input.update) ? input.update : [])
    .filter(isRecord)
    .flatMap((variantUpdate): StaticProductVariant[] => {
      const id = getStringValue(variantUpdate, "id")
      if (!id) {
        return []
      }

      const update = { ...variantUpdate }
      delete update.id

      return updateStaticProductVariantsFromWorkflowInput({
        selector: { id },
        update,
      })
    })

  const deleted = deleteStaticProductVariantsFromWorkflowInput({
    ids: normalizeStringFilter(input.delete),
  })

  return {
    created,
    updated,
    deleted,
  }
}

function batchStaticImageVariantsFromWorkflowInput(input: unknown): {
  added: string[]
  removed: string[]
} {
  if (!isRecord(input)) {
    return {
      added: [],
      removed: [],
    }
  }

  const imageId = getStringValue(input, "image_id")
  if (!imageId) {
    return {
      added: [],
      removed: [],
    }
  }

  const added = normalizeStringFilter(input.add)
  const removed = normalizeStringFilter(input.remove)

  addStaticImageVariantLinks(
    added.map((variantId) => ({
      image_id: imageId,
      variant_id: variantId,
    }))
  )
  removeStaticImageVariantLinksByImage(imageId, removed)

  return {
    added,
    removed,
  }
}

function batchStaticVariantImagesFromWorkflowInput(input: unknown): {
  added: string[]
  removed: string[]
} {
  if (!isRecord(input)) {
    return {
      added: [],
      removed: [],
    }
  }

  const variantId = getStringValue(input, "variant_id")
  if (!variantId) {
    return {
      added: [],
      removed: [],
    }
  }

  const added = normalizeStringFilter(input.add)
  const removed = normalizeStringFilter(input.remove)

  addStaticImageVariantLinks(
    added.map((imageId) => ({
      image_id: imageId,
      variant_id: variantId,
    }))
  )
  removeStaticImageVariantLinksByVariant(variantId, removed)

  return {
    added,
    removed,
  }
}

function addStaticImageVariantLinks(
  links: StaticProductVariantImageLink[]
): void {
  for (const link of links) {
    const exists = staticProductVariantImageLinks.some(
      (candidate) =>
        candidate.image_id === link.image_id &&
        candidate.variant_id === link.variant_id
    )

    if (!exists) {
      staticProductVariantImageLinks.push(link)
    }
  }
}

function removeStaticImageVariantLinksByImage(
  imageId: string,
  variantIds: string[]
): void {
  if (variantIds.length === 0) {
    return
  }

  staticProductVariantImageLinks = staticProductVariantImageLinks.filter(
    (link) =>
      link.image_id !== imageId || !variantIds.includes(link.variant_id)
  )
}

function removeStaticImageVariantLinksByVariant(
  variantId: string,
  imageIds: string[]
): void {
  if (imageIds.length === 0) {
    return
  }

  staticProductVariantImageLinks = staticProductVariantImageLinks.filter(
    (link) => link.variant_id !== variantId || !imageIds.includes(link.image_id)
  )
}

function createStaticProductVariantOptions(
  variant: Record<string, unknown>,
  productOptions: StaticProductOption[]
): StaticProductVariantOption[] {
  const optionValues = getRecordValue(variant, "options")
  if (!optionValues) {
    return []
  }

  return productOptions.flatMap((option): StaticProductVariantOption[] => {
    const value = getStringValue(optionValues, option.title)
    const optionValue = option.values.find(
      (candidate) => candidate.value === value
    )
    return value
      ? [
          {
            id: optionValue?.id ?? `optval_${option.id}_${value}`,
            option_id: option.id,
            value,
          },
        ]
      : []
  })
}

function createStaticProductPrices(
  prices: unknown[],
  timestamp: string
): StaticProductPrice[] {
  return prices.flatMap((price): StaticProductPrice[] => {
    if (!isRecord(price) || typeof price.amount !== "number") {
      return []
    }

    const currencyCode = getStringValue(price, "currency_code")
    if (!currencyCode) {
      return []
    }

    staticProductPriceSequence += 1
    return [
      {
        id: `price_worker_http_proof_${staticProductPriceSequence}`,
        amount: price.amount,
        currency_code: currencyCode,
        region_id: getStaticProductPriceRegionId(price),
        min_quantity: getStaticProductPriceQuantity(price, "min_quantity"),
        max_quantity: getStaticProductPriceQuantity(price, "max_quantity"),
        price_set_id: `pset_worker_http_proof_${staticProductPriceSequence}`,
        price_rules: createStaticProductPriceRules(price),
        created_at: timestamp,
        updated_at: timestamp,
      },
    ]
  })
}

function updateStaticProductPrices(
  existingPrices: StaticProductPrice[],
  prices: unknown[],
  timestamp: string
): StaticProductPrice[] {
  return prices.flatMap((price): StaticProductPrice[] => {
    if (!isRecord(price) || typeof price.amount !== "number") {
      return []
    }

    const currencyCode = getStringValue(price, "currency_code")
    if (!currencyCode) {
      return []
    }

    const priceId = getStringValue(price, "id")
    const existing = priceId
      ? existingPrices.find((candidate) => candidate.id === priceId)
      : undefined

    if (existing) {
      return [
        {
          ...existing,
          amount: price.amount,
          currency_code: currencyCode,
          region_id: getStaticProductPriceRegionId(price),
          min_quantity: getStaticProductPriceQuantity(price, "min_quantity"),
          max_quantity: getStaticProductPriceQuantity(price, "max_quantity"),
          price_rules: createStaticProductPriceRules(price),
          updated_at: timestamp,
        },
      ]
    }

    staticProductPriceSequence += 1
    return [
      {
        id: priceId ?? `price_worker_http_proof_${staticProductPriceSequence}`,
        amount: price.amount,
        currency_code: currencyCode,
        region_id: getStaticProductPriceRegionId(price),
        min_quantity: getStaticProductPriceQuantity(price, "min_quantity"),
        max_quantity: getStaticProductPriceQuantity(price, "max_quantity"),
        price_set_id: `pset_worker_http_proof_${staticProductPriceSequence}`,
        price_rules: createStaticProductPriceRules(price),
        created_at: timestamp,
        updated_at: timestamp,
      },
    ]
  })
}

function createStaticProductPriceRules(
  price: Record<string, unknown>
): StaticProductPriceRule[] {
  const rules = getRecordValue(price, "rules")
  if (!rules) {
    return []
  }

  return Object.entries(rules).flatMap(([attribute, value]) =>
    typeof value === "string"
      ? [
          {
            attribute,
            value,
          },
        ]
      : []
  )
}

function getStaticProductPriceRegionId(
  price: Record<string, unknown>
): string | null {
  const rules = getRecordValue(price, "rules")
  return rules ? getNullableStringValue(rules, "region_id") : null
}

function getStaticProductPriceQuantity(
  price: Record<string, unknown>,
  key: "min_quantity" | "max_quantity"
): number | null {
  return typeof price[key] === "number" ? price[key] : null
}

function createStaticProductVariantInventoryItems(
  inventoryItems: unknown[]
): StaticProductVariantInventoryItem[] {
  return inventoryItems.flatMap((item): StaticProductVariantInventoryItem[] => {
    if (!isRecord(item) || typeof item.inventory_item_id !== "string") {
      return []
    }

    return [
      {
        inventory_item_id: item.inventory_item_id,
        required_quantity:
          typeof item.required_quantity === "number"
            ? item.required_quantity
            : 1,
      },
    ]
  })
}

function createStaticProductVariantInventoryItemsForVariant(
  variantId: string,
  variant: Record<string, unknown>
): StaticProductVariantInventoryItem[] {
  const explicitInventoryItems = createStaticProductVariantInventoryItems(
    isArrayValue(variant.inventory_items) ? variant.inventory_items : []
  )

  if (explicitInventoryItems.length > 0 || variant.manage_inventory !== true) {
    return explicitInventoryItems
  }

  const inventoryItem = createStaticInventoryItemForManagedVariant(
    variantId,
    getNullableStringValue(variant, "sku"),
    getNullableStringValue(variant, "title")
  )

  return [
    {
      inventory_item_id: inventoryItem.id,
      required_quantity: 1,
    },
  ]
}

function createStaticInventoryItemForManagedVariant(
  variantId: string,
  sku: string | null,
  title: string | null
): StaticInventoryItem {
  staticInventoryItemSequence += 1
  const timestamp = new Date(
    Date.UTC(2026, 5, 21, 3, 20, staticInventoryItemSequence)
  ).toISOString()
  const inventoryItem: StaticInventoryItem = {
    id: `iitem_${variantId}`,
    sku,
    title,
    description: null,
    thumbnail: null,
    origin_country: null,
    hs_code: null,
    mid_code: null,
    material: null,
    weight: null,
    length: null,
    height: null,
    width: null,
    metadata: null,
    requires_shipping: true,
    location_levels: [],
    created_at: timestamp,
    updated_at: timestamp,
  }

  staticInventoryItems = [...staticInventoryItems, inventoryItem]
  return inventoryItem
}

function toStaticProductVariantInventoryItemRow(
  link: StaticProductVariantInventoryItem
): Record<string, unknown> {
  const inventoryItem = staticInventoryItems.find(
    (item) => item.id === link.inventory_item_id
  )

  return {
    inventory_item_id: link.inventory_item_id,
    required_quantity: link.required_quantity,
    inventory: inventoryItem ? toStaticInventoryItemRow(inventoryItem) : null,
  }
}

function toStaticInventoryItemRow(
  inventoryItem: StaticInventoryItem
): Record<string, unknown> {
  const stockedQuantity = inventoryItem.location_levels.reduce(
    (total, level) => total + level.stocked_quantity,
    0
  )
  const reservedQuantity = inventoryItem.location_levels.reduce(
    (total, level) => total + level.reserved_quantity,
    0
  )

  return {
    ...inventoryItem,
    stocked_quantity: stockedQuantity,
    reserved_quantity: reservedQuantity,
    available_quantity: Math.max(stockedQuantity - reservedQuantity, 0),
    location_levels: inventoryItem.location_levels.map((level) => ({
      ...level,
    })),
  }
}

function mergeStaticInventoryItem(
  existing: StaticInventoryItem | undefined,
  incoming: StaticInventoryItem
): StaticInventoryItem {
  if (!existing) {
    return incoming
  }

  return {
    ...incoming,
    sku: incoming.sku ?? existing.sku,
    title: incoming.title ?? existing.title,
    description: incoming.description ?? existing.description,
    thumbnail: incoming.thumbnail ?? existing.thumbnail,
    origin_country: incoming.origin_country ?? existing.origin_country,
    hs_code: incoming.hs_code ?? existing.hs_code,
    mid_code: incoming.mid_code ?? existing.mid_code,
    material: incoming.material ?? existing.material,
    weight: incoming.weight ?? existing.weight,
    length: incoming.length ?? existing.length,
    height: incoming.height ?? existing.height,
    width: incoming.width ?? existing.width,
    metadata: incoming.metadata ?? existing.metadata,
  }
}

function createStaticCalculatedPrice(
  prices: unknown[],
  context: Record<string, unknown> | null = null
): StaticProductCalculatedPrice {
  const price = prices.find(
    (candidate): candidate is Record<string, unknown> => isRecord(candidate)
  )
  const amount = typeof price?.amount === "number" ? price.amount : 0
  const currencyCode = getStringValue(price ?? {}, "currency_code") ?? "usd"
  const priceRegionId = getNullableStringValue(price ?? {}, "region_id")
  const isTaxInclusive = isStaticPriceTaxInclusive(
    { currency_code: currencyCode, region_id: priceRegionId },
    context
  )
  const priceId =
    getStringValue(price ?? {}, "id") ??
    `price_worker_http_proof_calculated_${currencyCode}_${amount}`

  return createStaticCalculatedPriceDTO({
    id: priceId,
    calculated_amount: amount,
    original_amount: amount,
    currency_code: currencyCode,
    calculated_price: createStaticCalculatedPriceRef(priceId, null),
    original_price: createStaticCalculatedPriceRef(priceId, null),
    is_calculated_price_price_list: false,
    is_original_price_price_list: false,
    is_calculated_price_tax_inclusive: isTaxInclusive,
    is_original_price_tax_inclusive: isTaxInclusive,
  })
}

function normalizeStaticProductCalculatedPrice(
  calculatedPrice: Record<string, unknown> | undefined,
  prices: unknown[]
): StaticProductCalculatedPrice {
  const basePrice = createStaticCalculatedPrice(prices)
  if (!calculatedPrice) {
    return basePrice
  }

  const calculatedAmount =
    typeof calculatedPrice.calculated_amount === "number"
      ? calculatedPrice.calculated_amount
      : basePrice.calculated_amount
  const originalAmount =
    typeof calculatedPrice.original_amount === "number"
      ? calculatedPrice.original_amount
      : calculatedAmount
  const currencyCode =
    getStringValue(calculatedPrice, "currency_code") ?? basePrice.currency_code
  const priceId = getStringValue(calculatedPrice, "id") ?? basePrice.id

  return createStaticCalculatedPriceDTO({
    id: priceId,
    calculated_amount: calculatedAmount,
    original_amount: originalAmount,
    currency_code: currencyCode,
    calculated_price: createStaticCalculatedPriceRef(priceId, null),
    original_price: createStaticCalculatedPriceRef(priceId, null),
    is_calculated_price_price_list:
      calculatedPrice.is_calculated_price_price_list === true,
    is_original_price_price_list:
      calculatedPrice.is_original_price_price_list === true,
  })
}

function createStaticCalculatedPriceDTO({
  id,
  calculated_amount,
  original_amount,
  currency_code,
  calculated_price,
  original_price,
  is_calculated_price_price_list,
  is_original_price_price_list,
  is_calculated_price_tax_inclusive = false,
  is_original_price_tax_inclusive = false,
}: {
  id: string
  calculated_amount: number
  original_amount: number
  currency_code: string
  calculated_price: StaticProductCalculatedPriceRef
  original_price: StaticProductCalculatedPriceRef
  is_calculated_price_price_list: boolean
  is_original_price_price_list: boolean
  is_calculated_price_tax_inclusive?: boolean
  is_original_price_tax_inclusive?: boolean
}): StaticProductCalculatedPrice {
  return {
    id,
    is_calculated_price_price_list,
    is_calculated_price_tax_inclusive,
    calculated_amount,
    raw_calculated_amount: {
      value: String(calculated_amount),
      precision: 20,
    },
    is_original_price_price_list,
    is_original_price_tax_inclusive,
    original_amount,
    raw_original_amount: {
      value: String(original_amount),
      precision: 20,
    },
    currency_code,
    calculated_price,
    original_price,
  }
}

function createStaticCalculatedPriceRef(
  id: string,
  priceList: StaticPriceList | null
): StaticProductCalculatedPriceRef {
  return {
    id,
    price_list_id: priceList?.id ?? null,
    price_list_type: priceList?.type ?? null,
    min_quantity: null,
    max_quantity: null,
  }
}

function createStaticInventoryItemsFromWorkflowInput(
  input: unknown
): StaticInventoryItem[] {
  if (!isRecord(input) || !Array.isArray(input.items)) {
    return []
  }

  const created = input.items.flatMap((item): StaticInventoryItem[] => {
    if (!isRecord(item)) {
      return []
    }

    staticInventoryItemSequence += 1
    const timestamp = new Date(
      Date.UTC(2026, 5, 21, 3, 20, staticInventoryItemSequence)
    ).toISOString()

    return [
      {
        id: `iitem_worker_http_proof_${staticInventoryItemSequence}`,
        sku: getNullableStringValue(item, "sku"),
        title: getNullableStringValue(item, "title"),
        description: getNullableStringValue(item, "description"),
        thumbnail: getNullableStringValue(item, "thumbnail"),
        origin_country: getNullableStringValue(item, "origin_country"),
        hs_code: getNullableStringValue(item, "hs_code"),
        mid_code: getNullableStringValue(item, "mid_code"),
        material: getNullableStringValue(item, "material"),
        weight: getNullableNumberValue(item, "weight"),
        length: getNullableNumberValue(item, "length"),
        height: getNullableNumberValue(item, "height"),
        width: getNullableNumberValue(item, "width"),
        metadata: getRecordValue(item, "metadata") ?? null,
        requires_shipping: item.requires_shipping !== false,
        location_levels: [],
        created_at: timestamp,
        updated_at: timestamp,
      },
    ]
  })

  staticInventoryItems = [...staticInventoryItems, ...created]
  for (const item of input.items) {
    if (!isRecord(item) || !Array.isArray(item.location_levels)) {
      continue
    }

    const createdItem = created.find(
      (candidate) => candidate.sku === getNullableStringValue(item, "sku")
    )
    if (!createdItem) {
      continue
    }

    createStaticInventoryLevelsFromWorkflowInput({
      inventory_levels: item.location_levels.map((level) =>
        isRecord(level)
          ? {
              ...level,
              inventory_item_id: createdItem.id,
            }
          : level
      ),
    })
  }

  return created
}

function updateStaticInventoryItemsFromWorkflowInput(
  input: unknown
): StaticInventoryItem[] {
  if (!isRecord(input) || !Array.isArray(input.updates)) {
    return []
  }

  const updates = input.updates.filter(isRecord)
  const updatedItems: StaticInventoryItem[] = []
  staticInventoryItems = staticInventoryItems.map((item) => {
    const update = updates.find(
      (candidate) => getStringValue(candidate, "id") === item.id
    )
    if (!update) {
      return item
    }

    const updated: StaticInventoryItem = {
      ...item,
      sku: Object.prototype.hasOwnProperty.call(update, "sku")
        ? getNullableStringValue(update, "sku")
        : item.sku,
      title: Object.prototype.hasOwnProperty.call(update, "title")
        ? getNullableStringValue(update, "title")
        : item.title,
      description: Object.prototype.hasOwnProperty.call(update, "description")
        ? getNullableStringValue(update, "description")
        : item.description,
      thumbnail: Object.prototype.hasOwnProperty.call(update, "thumbnail")
        ? getNullableStringValue(update, "thumbnail")
        : item.thumbnail,
      origin_country: Object.prototype.hasOwnProperty.call(
        update,
        "origin_country"
      )
        ? getNullableStringValue(update, "origin_country")
        : item.origin_country,
      hs_code: Object.prototype.hasOwnProperty.call(update, "hs_code")
        ? getNullableStringValue(update, "hs_code")
        : item.hs_code,
      mid_code: Object.prototype.hasOwnProperty.call(update, "mid_code")
        ? getNullableStringValue(update, "mid_code")
        : item.mid_code,
      material: Object.prototype.hasOwnProperty.call(update, "material")
        ? getNullableStringValue(update, "material")
        : item.material,
      weight: Object.prototype.hasOwnProperty.call(update, "weight")
        ? getNullableNumberValue(update, "weight")
        : item.weight,
      length: Object.prototype.hasOwnProperty.call(update, "length")
        ? getNullableNumberValue(update, "length")
        : item.length,
      height: Object.prototype.hasOwnProperty.call(update, "height")
        ? getNullableNumberValue(update, "height")
        : item.height,
      width: Object.prototype.hasOwnProperty.call(update, "width")
        ? getNullableNumberValue(update, "width")
        : item.width,
      metadata: Object.prototype.hasOwnProperty.call(update, "metadata")
        ? getRecordValue(update, "metadata") ?? null
        : item.metadata,
      requires_shipping: Object.prototype.hasOwnProperty.call(
        update,
        "requires_shipping"
      )
        ? update.requires_shipping !== false
        : item.requires_shipping,
      updated_at: new Date(Date.UTC(2026, 5, 21, 3, 50, 0)).toISOString(),
    }
    updatedItems.push(updated)
    return updated
  })

  return updatedItems
}

function deleteStaticInventoryItemsFromWorkflowInput(input: unknown): string[] {
  const ids = normalizeStringFilter(input)
  if (ids.length === 0) {
    return []
  }

  assertStaticInventoryItemsCanBeRemoved(ids)
  staticInventoryItems = staticInventoryItems.filter(
    (item) => !ids.includes(item.id)
  )
  staticProducts = staticProducts.map((product) => ({
    ...product,
    variants: product.variants.map((variant) => ({
      ...variant,
      inventory_items: variant.inventory_items.filter(
        (link) => !ids.includes(link.inventory_item_id)
      ),
    })),
  }))

  return ids
}

function getStaticAvailableInventoryLevel(
  inventoryItem: StaticInventoryItem,
  quantity: number
): StaticInventoryLevel | undefined {
  return (
    inventoryItem.location_levels.find(
      (level) =>
        isStaticInventoryItemBackorderAllowed(inventoryItem.id) ||
        level.stocked_quantity -
          getStaticReservedQuantity(inventoryItem.id, level.location_id) >=
          quantity
    ) ?? inventoryItem.location_levels[0]
  )
}

function getStaticReservedQuantity(
  inventoryItemId: string,
  locationId: string,
  excludeReservationId?: string
): number {
  return staticReservations
    .filter(
      (reservation) =>
        reservation.id !== excludeReservationId &&
        reservation.inventory_item_id === inventoryItemId &&
        reservation.location_id === locationId
    )
    .reduce((total, reservation) => total + reservation.quantity, 0)
}

function createStaticReservationsFromWorkflowInput(
  input: unknown
): StaticReservation[] {
  if (!isRecord(input) || !Array.isArray(input.reservations)) {
    return []
  }

  const created = input.reservations.flatMap(
    (reservation): StaticReservation[] => {
      if (!isRecord(reservation)) {
        return []
      }

      const inventoryItemId = getStringValue(reservation, "inventory_item_id")
      const locationId = getStringValue(reservation, "location_id")
      const lineItemId = getNullableStringValue(reservation, "line_item_id")
      const isMirroredProofReservation =
        getBooleanValue(reservation, "__medusa_http_proof_mirrored") === true
      const quantity =
        typeof reservation.quantity === "number" ? reservation.quantity : 0

      if (!inventoryItemId || !locationId) {
        return []
      }

      const existing = staticReservations.find(
        (candidate) =>
          candidate.inventory_item_id === inventoryItemId &&
          candidate.location_id === locationId &&
          candidate.quantity === quantity &&
          (candidate.line_item_id === lineItemId || isMirroredProofReservation)
      )
      if (existing?.quantity === quantity) {
        return []
      }

      assertStaticReservationStockAvailable({
        inventoryItemId,
        locationId,
        quantity,
      })

      staticReservationSequence += 1
      const timestamp = new Date(
        Date.UTC(2026, 5, 21, 3, 25, staticReservationSequence)
      ).toISOString()

      return [
        {
          id: `resitem_worker_http_proof_${staticReservationSequence}`,
          line_item_id: lineItemId,
          inventory_item_id: inventoryItemId,
          location_id: locationId,
          description: getNullableStringValue(reservation, "description"),
          quantity,
          metadata: getRecordValue(reservation, "metadata") ?? null,
          created_at: timestamp,
          updated_at: timestamp,
        },
      ]
    }
  )

  staticReservations = [...staticReservations, ...created]
  return created
}

function updateStaticReservationsFromWorkflowInput(
  input: unknown
): StaticReservation[] {
  if (!isRecord(input) || !Array.isArray(input.updates)) {
    return []
  }

  const updates = input.updates.filter(isRecord)
  const updatedReservations: StaticReservation[] = []

  staticReservations = staticReservations.map((reservation) => {
    const update = updates.find(
      (candidate) => getStringValue(candidate, "id") === reservation.id
    )

    if (!update) {
      return reservation
    }

    const nextInventoryItemId =
      getStringValue(update, "inventory_item_id") ?? reservation.inventory_item_id
    const nextLocationId =
      getStringValue(update, "location_id") ?? reservation.location_id
    const nextQuantity =
      typeof update.quantity === "number" ? update.quantity : reservation.quantity
    assertStaticReservationStockAvailable({
      inventoryItemId: nextInventoryItemId,
      locationId: nextLocationId,
      quantity: nextQuantity,
      excludeReservationId: reservation.id,
    })

    const updated: StaticReservation = {
      ...reservation,
      inventory_item_id: nextInventoryItemId,
      location_id: nextLocationId,
      description: Object.prototype.hasOwnProperty.call(update, "description")
        ? getNullableStringValue(update, "description")
        : reservation.description,
      quantity: nextQuantity,
      metadata: Object.prototype.hasOwnProperty.call(update, "metadata")
        ? getRecordValue(update, "metadata") ?? null
        : reservation.metadata,
      updated_at: new Date(Date.UTC(2026, 5, 21, 3, 26, 0)).toISOString(),
    }

    updatedReservations.push(updated)
    return updated
  })

  return updatedReservations
}

function deleteStaticReservationsFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)
  if (ids.length === 0) {
    return []
  }

  staticReservations = staticReservations.filter(
    (reservation) => !ids.includes(reservation.id)
  )

  return ids
}

function assertStaticReservationStockAvailable(input: {
  inventoryItemId: string
  locationId: string
  quantity: number
  excludeReservationId?: string
}): void {
  const inventoryItem = getStaticInventoryItemById(input.inventoryItemId)
  const level = inventoryItem?.location_levels.find(
    (candidate) => candidate.location_id === input.locationId
  )
  const stockedQuantity = level?.stocked_quantity ?? 0
  const reservedQuantity = getStaticReservedQuantity(
    input.inventoryItemId,
    input.locationId,
    input.excludeReservationId
  )

  if (isStaticInventoryItemBackorderAllowed(input.inventoryItemId)) {
    return
  }

  if (input.quantity > stockedQuantity - reservedQuantity) {
    throw new MedusaError(
      MedusaError.Types.NOT_ALLOWED,
      `Not enough stock available for item ${input.inventoryItemId} at location ${input.locationId}`
    )
  }
}

function isStaticInventoryItemBackorderAllowed(inventoryItemId: string): boolean {
  return staticProducts.some((product) =>
    product.variants.some(
      (variant) =>
        variant.allow_backorder &&
        variant.inventory_items.some(
          (inventoryLink) =>
            inventoryLink.inventory_item_id === inventoryItemId
        )
    )
  )
}

function isStaticPromotionUsageLimitExceeded(
  promotion: StaticPromotion
): boolean {
  if (promotion.limit !== null && promotion.used >= promotion.limit) {
    return true
  }

  const campaign = promotion.campaign_id
    ? staticCampaigns.find((candidate) => candidate.id === promotion.campaign_id)
    : undefined

  return (
    campaign?.budget?.type === "usage" &&
    campaign.budget.limit !== null &&
    campaign.budget.used >= campaign.budget.limit
  )
}

function isStaticPromotionCampaignBudgetApplicable(
  promotion: StaticPromotion,
  shouldThrowOnMissingAttributeValue: boolean
): boolean {
  const campaign = getStaticPromotionCampaign(promotion)
  const budget = campaign?.budget
  if (budget?.type !== "use_by_attribute") {
    return true
  }

  const attributeValue = getStaticCampaignBudgetAttributeValue(budget)
  if (!attributeValue) {
    if (
      !shouldThrowOnMissingAttributeValue ||
      (typeof budget.limit === "number" && budget.used >= budget.limit)
    ) {
      return false
    }

    throw new MedusaError(
      MedusaError.Types.INVALID_DATA,
      `Attribute value for "${budget.attribute}" is required by promotion campaing budget`
    )
  }

  return !isStaticCampaignBudgetAttributeUsageExceeded(budget, attributeValue)
}

function getStaticPromotionCampaign(
  promotion: StaticPromotion
): StaticCampaign | undefined {
  return promotion.campaign_id
    ? staticCampaigns.find((candidate) => candidate.id === promotion.campaign_id)
    : undefined
}

function getStaticCampaignBudgetAttributeValue(
  budget: StaticCampaignBudget
): string | null {
  if (budget.attribute === "customer_email") {
    return staticCartEmail
  }

  if (budget.attribute === "customer_id") {
    return staticCartCustomerId
  }

  return null
}

function isStaticCampaignBudgetAttributeUsageExceeded(
  budget: StaticCampaignBudget,
  attributeValue: string
): boolean {
  if (typeof budget.limit !== "number") {
    return false
  }

  const usage = budget.usages.find(
    (candidate) => candidate.attribute_value === attributeValue
  )

  return usage ? usage.used >= budget.limit : false
}

function getStaticInventoryItemById(
  inventoryItemId: string
): StaticInventoryItem | undefined {
  return staticInventoryItems.find((item) => item.id === inventoryItemId)
}

function createStaticInventoryLevelsFromWorkflowInput(
  input: unknown
): StaticInventoryLevel[] {
  if (!isRecord(input) || !Array.isArray(input.inventory_levels)) {
    return []
  }

  const validateStockLocations = input.validate_stock_locations !== false
  const created: StaticInventoryLevel[] = []
  for (const level of input.inventory_levels) {
    if (
      !isRecord(level) ||
      typeof level.inventory_item_id !== "string" ||
      typeof level.location_id !== "string"
    ) {
      continue
    }

    const inventoryItem = staticInventoryItems.find(
      (item) => item.id === level.inventory_item_id
    )
    if (!inventoryItem) {
      continue
    }

    if (
      validateStockLocations &&
      !staticStockLocations.some((location) => location.id === level.location_id)
    ) {
      throw new MedusaError(
        MedusaError.Types.NOT_FOUND,
        `Stock locations with ids: ${level.location_id} was not found`
      )
    }

    staticInventoryLevelSequence += 1
    const stockedQuantity =
      typeof level.stocked_quantity === "number" ? level.stocked_quantity : 0
    const reservedQuantity =
      typeof level.reserved_quantity === "number" ? level.reserved_quantity : 0
    const timestamp = new Date(
      Date.UTC(2026, 5, 21, 3, 30, staticInventoryLevelSequence)
    ).toISOString()
    const createdLevel: StaticInventoryLevel = {
      id: `ilev_worker_http_proof_${staticInventoryLevelSequence}`,
      inventory_item_id: level.inventory_item_id,
      location_id: level.location_id,
      stocked_quantity: stockedQuantity,
      reserved_quantity: reservedQuantity,
      incoming_quantity:
        typeof level.incoming_quantity === "number"
          ? level.incoming_quantity
          : 0,
      available_quantity: stockedQuantity - reservedQuantity,
      metadata: getRecordValue(level, "metadata") ?? null,
      created_at: timestamp,
      updated_at: timestamp,
    }

    inventoryItem.location_levels = [
      ...inventoryItem.location_levels.filter(
        (existing) => existing.location_id !== createdLevel.location_id
      ),
      createdLevel,
    ]
    created.push(createdLevel)
  }

  return created
}

function updateStaticInventoryLevelsFromWorkflowInput(
  input: unknown
): StaticInventoryLevel[] {
  if (!isRecord(input) || !Array.isArray(input.updates)) {
    return []
  }

  const updated: StaticInventoryLevel[] = []
  for (const update of input.updates) {
    if (!isRecord(update)) {
      continue
    }

    const inventoryItemId = getStringValue(update, "inventory_item_id")
    const locationId = getStringValue(update, "location_id")
    if (!inventoryItemId || !locationId) {
      continue
    }

    const inventoryItem = staticInventoryItems.find(
      (item) => item.id === inventoryItemId
    )
    const existing = inventoryItem?.location_levels.find(
      (level) => level.location_id === locationId
    )
    if (!inventoryItem || !existing) {
      continue
    }

    const stockedQuantity =
      typeof update.stocked_quantity === "number"
        ? update.stocked_quantity
        : existing.stocked_quantity
    const incomingQuantity =
      typeof update.incoming_quantity === "number"
        ? update.incoming_quantity
        : existing.incoming_quantity
    const reservedQuantity =
      typeof update.reserved_quantity === "number"
        ? update.reserved_quantity
        : existing.reserved_quantity
    const next: StaticInventoryLevel = {
      ...existing,
      stocked_quantity: stockedQuantity,
      incoming_quantity: incomingQuantity,
      reserved_quantity: reservedQuantity,
      available_quantity: Math.max(stockedQuantity - reservedQuantity, 0),
      metadata: Object.prototype.hasOwnProperty.call(update, "metadata")
        ? getRecordValue(update, "metadata") ?? null
        : existing.metadata,
      updated_at: new Date(Date.UTC(2026, 5, 21, 3, 45, 0)).toISOString(),
    }

    inventoryItem.location_levels = inventoryItem.location_levels.map((level) =>
      level.id === existing.id ? next : level
    )
    updated.push(next)
  }

  return updated
}

function deleteStaticInventoryLevelsFromWorkflowInput(
  input: unknown
): string[] | Response {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.id)
  const force = input.force === true
  if (ids.length === 0) {
    return []
  }

  const levels = staticInventoryItems.flatMap((item) =>
    item.location_levels.filter((level) => ids.includes(level.id))
  )
  const blockedByReservation = levels.filter(
    (level) => level.reserved_quantity > 0 || level.incoming_quantity > 0
  )
  if (blockedByReservation.length > 0) {
    const locationIds = [
      ...new Set(blockedByReservation.map((level) => level.location_id)),
    ]
    return createStaticErrorResponse(
      400,
      "not_allowed",
      `Cannot remove Inventory Levels for ${locationIds.join(
        ", "
      )} because there are reserved or incoming items at the locations`
    )
  }

  const blockedByStock = levels.filter(
    (level) => !force && level.stocked_quantity > 0
  )
  if (blockedByStock.length > 0) {
    const locationIds = [...new Set(blockedByStock.map((level) => level.location_id))]
    return createStaticErrorResponse(
      400,
      "not_allowed",
      `Cannot remove Inventory Levels for ${locationIds.join(
        ", "
      )} because there are stocked items at the locations. Use force flag to delete anyway.`
    )
  }

  staticInventoryItems = staticInventoryItems.map((item) => ({
    ...item,
    location_levels: item.location_levels.filter(
      (level) => !ids.includes(level.id)
    ),
  }))

  return ids
}

function normalizeStaticInventoryLevelInputs(
  value: unknown,
  options: { inventoryItemId?: string; validateStockLocations?: boolean } = {}
): Array<Record<string, unknown>> {
  if (!Array.isArray(value)) {
    return []
  }

  return value.filter(isRecord).map((level) => ({
    ...level,
    ...(options.inventoryItemId ? { inventory_item_id: options.inventoryItemId } : {}),
  }))
}

function hasNegativeInventoryQuantity(body: Record<string, unknown>): boolean {
  return (
    (typeof body.stocked_quantity === "number" && body.stocked_quantity < 0) ||
    (typeof body.incoming_quantity === "number" && body.incoming_quantity < 0)
  )
}

function createStaticShippingOptionTypesFromWorkflowInput(
  input: unknown
): StaticShippingOptionType[] {
  if (!isRecord(input) || !Array.isArray(input.shipping_option_types)) {
    return []
  }

  const incomingCodes = input.shipping_option_types.flatMap(
    (shippingOptionType): string[] => {
      if (
        !isRecord(shippingOptionType) ||
        typeof shippingOptionType.code !== "string"
      ) {
        return []
      }

      return [shippingOptionType.code]
    }
  )
  const existingCodes = new Set(
    staticShippingOptionTypes.map(
      (shippingOptionType) => shippingOptionType.code
    )
  )
  if (incomingCodes.some((code) => existingCodes.has(code))) {
    staticShippingOptionTypes = []
    staticShippingOptionTypeSequence = 0
  }

  const created = input.shipping_option_types.flatMap(
    (shippingOptionType): StaticShippingOptionType[] => {
      if (
        !isRecord(shippingOptionType) ||
        typeof shippingOptionType.label !== "string" ||
        typeof shippingOptionType.code !== "string"
      ) {
        return []
      }

      staticShippingOptionTypeSequence += 1
      const timestamp = new Date(
        Date.UTC(2026, 5, 21, 1, 10, staticShippingOptionTypeSequence)
      ).toISOString()

      return [
        {
          id: `sotype_${staticShippingOptionTypeSequence
            .toString()
            .padStart(24, "0")}`,
          label: shippingOptionType.label,
          code: shippingOptionType.code,
          description:
            typeof shippingOptionType.description === "string"
              ? shippingOptionType.description
              : null,
          created_at: timestamp,
          updated_at: timestamp,
        },
      ]
    }
  )

  staticShippingOptionTypes = [...created, ...staticShippingOptionTypes]
  return created
}

function updateStaticShippingOptionTypesFromWorkflowInput(
  input: unknown
): StaticShippingOptionType[] {
  if (!isRecord(input)) {
    return []
  }

  const selector = isRecord(input.selector) ? input.selector : undefined
  const update = isRecord(input.update) ? input.update : undefined
  const idFilters = normalizeStringFilter(selector?.id)

  if (!update || idFilters.length === 0) {
    return []
  }

  const updated: StaticShippingOptionType[] = []
  staticShippingOptionTypes = staticShippingOptionTypes.map(
    (shippingOptionType) => {
      if (!idFilters.includes(shippingOptionType.id)) {
        return shippingOptionType
      }

      const next: StaticShippingOptionType = {
        ...shippingOptionType,
        label:
          typeof update.label === "string"
            ? update.label
            : shippingOptionType.label,
        code:
          typeof update.code === "string"
            ? update.code
            : shippingOptionType.code,
        description:
          typeof update.description === "string"
            ? update.description
            : shippingOptionType.description,
        updated_at: new Date(Date.UTC(2026, 5, 21, 1, 20, 0)).toISOString(),
      }

      updated.push(next)
      return next
    }
  )

  return updated
}

function deleteStaticShippingOptionTypesFromWorkflowInput(
  input: unknown
): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)

  if (ids.length === 0) {
    return []
  }

  staticShippingOptionTypes = staticShippingOptionTypes.filter(
    (shippingOptionType) => !ids.includes(shippingOptionType.id)
  )

  return ids
}

function createStaticShippingOptionsFromWorkflowInput(
  input: unknown
): StaticShippingOption[] {
  const shippingOptionInputs = Array.isArray(input) ? input : []
  const created = shippingOptionInputs.flatMap(
    (shippingOption): StaticShippingOption[] => {
      if (
        !isRecord(shippingOption) ||
        typeof shippingOption.name !== "string" ||
        typeof shippingOption.service_zone_id !== "string" ||
        typeof shippingOption.shipping_profile_id !== "string" ||
        typeof shippingOption.provider_id !== "string" ||
        typeof shippingOption.price_type !== "string"
      ) {
        return []
      }

      validateStaticShippingOptionProvider(
        shippingOption.service_zone_id,
        shippingOption.provider_id
      )

      const type = resolveStaticShippingOptionType(shippingOption)
      if (!type) {
        return []
      }

      staticShippingOptionSequence += 1
      const timestamp = new Date(
        Date.UTC(2026, 5, 21, 0, 50, staticShippingOptionSequence)
      ).toISOString()
      const id = `so_worker_http_proof_${staticShippingOptionSequence}`

      return [
        {
          id,
          name: shippingOption.name,
          price_type: shippingOption.price_type,
          data: getRecordValue(shippingOption, "data") ?? null,
          provider_id: shippingOption.provider_id,
          metadata: getRecordValue(shippingOption, "metadata") ?? null,
          service_zone_id: shippingOption.service_zone_id,
          shipping_profile_id: shippingOption.shipping_profile_id,
          type,
          prices: createStaticShippingOptionPrices(
            isArrayValue(shippingOption.prices) ? shippingOption.prices : [],
            timestamp
          ),
          rules: createStaticShippingOptionRules(
            isArrayValue(shippingOption.rules) ? shippingOption.rules : [],
            id
          ),
          created_at: timestamp,
          updated_at: timestamp,
          deleted_at: null,
        },
      ]
    }
  )

  staticShippingOptions = [...staticShippingOptions, ...created]
  return created
}

function listStaticShippingOptionsForCartFromWorkflowInput(
  input: unknown
): Array<Record<string, unknown>> {
  if (!isRecord(input) || input.cart_id !== staticCartId) {
    return []
  }

  const region = staticRegions.find(
    (candidate) => candidate.id === staticCartRegionId
  )
  const isTaxInclusive = isStaticCartShippingTaxInclusive(region)
  const itemTotal = getStaticCartItemTotal()

  return staticShippingOptions.flatMap((option): Array<Record<string, unknown>> => {
    if (!isStaticShippingOptionInCartContext(option, region)) {
      return []
    }

    if (option.price_type === "calculated") {
      return [
        {
          ...option,
          name: getStaticTranslatedShippingOptionName(option),
          prices: [],
          calculated_price: null,
        },
      ]
    }

    const price = resolveStaticShippingOptionPrice(option, itemTotal)
    if (!price) {
      return []
    }

    const insufficientInventory =
      isStaticShippingOptionInventoryInsufficient(option)

    return [
      {
        ...option,
        name: getStaticTranslatedShippingOptionName(option),
        amount: price.amount,
        is_tax_inclusive: isTaxInclusive,
        insufficient_inventory: insufficientInventory,
        calculated_price: {
          calculated_amount: price.amount,
          is_calculated_price_tax_inclusive: isTaxInclusive,
        },
      },
    ]
  })
}

function getStaticTranslatedShippingOptionName(
  option: StaticShippingOption
): string {
  return getStaticTranslationValues("shipping_option", option.id)?.name ?? option.name
}

function getStaticTranslationValues(
  reference: string,
  referenceId: string
): Record<string, string> | undefined {
  if (!staticCartLocale) {
    return undefined
  }

  return staticTranslations.find(
    (candidate) =>
      candidate.reference === reference &&
      candidate.reference_id === referenceId &&
      candidate.locale_code === staticCartLocale
  )?.translations
}

function calculateStaticShippingOptionPricesFromWorkflowInput(
  input: unknown
): Array<Record<string, unknown>> {
  if (!isRecord(input) || !Array.isArray(input.shipping_options)) {
    return []
  }

  return input.shipping_options.flatMap((option): Array<Record<string, unknown>> => {
    if (!isRecord(option) || typeof option.id !== "string") {
      return []
    }

    return [calculateStaticShippingOptionPrice(option.id)]
  })
}

function calculateStaticShippingOptionPrice(
  shippingOptionId: string
): {
  calculated_amount: number
  is_calculated_price_tax_inclusive: boolean
} {
  const option = staticShippingOptions.find(
    (candidate) => candidate.id === shippingOptionId
  )
  const region = staticRegions.find(
    (candidate) => candidate.id === staticCartRegionId
  )
  const isTaxInclusive = isStaticCartShippingTaxInclusive(region)

  if (!option) {
    return {
      calculated_amount: 0,
      is_calculated_price_tax_inclusive: isTaxInclusive,
    }
  }

  if (option.price_type === "calculated") {
    return {
      calculated_amount: getStaticCartLineItemQuantity() * 1.5,
      is_calculated_price_tax_inclusive: isTaxInclusive,
    }
  }

  const price = resolveStaticShippingOptionPrice(option, getStaticCartItemTotal())
  return {
    calculated_amount: price?.amount ?? 0,
    is_calculated_price_tax_inclusive: isTaxInclusive,
  }
}

function isStaticCartShippingTaxInclusive(
  region: StaticRegion | undefined
): boolean {
  const currencyPreference = staticPricePreferences.find(
    (preference) =>
      preference.attribute === "currency_code" &&
      preference.value.toLowerCase() === staticCartCurrencyCode.toLowerCase()
  )

  return currencyPreference?.is_tax_inclusive ?? region?.is_tax_inclusive === true
}

function getStaticCartLineItemQuantity(): number {
  return staticCartLineItems.reduce(
    (total, lineItem) => total + lineItem.quantity,
    0
  )
}

function refreshStaticCalculatedShippingMethods(): void {
  const region = staticRegions.find(
    (candidate) => candidate.id === staticCartRegionId
  )

  staticCartShippingMethods = staticCartShippingMethods.flatMap(
    (method): StaticCartShippingMethod[] => {
      const option = staticShippingOptions.find(
        (candidate) => candidate.id === method.shipping_option_id
      )

      if (!option || !isStaticShippingOptionInCartContext(option, region)) {
        return []
      }

      const calculatedPrice = calculateStaticShippingOptionPrice(
        method.shipping_option_id
      )

      return [
        {
          ...method,
          amount: calculatedPrice.calculated_amount,
          is_tax_inclusive:
            calculatedPrice.is_calculated_price_tax_inclusive === true,
        },
      ]
    }
  )
}

function isStaticShippingOptionInCartContext(
  option: StaticShippingOption,
  region: StaticRegion | undefined
): boolean {
  const serviceZone = getStaticServiceZoneById(option.service_zone_id)
  if (!serviceZone) {
    return false
  }

  const fulfillmentSetId = serviceZone.fulfillment_set_id
  const stockLocationIds = staticLocationFulfillmentSetLinks
    .filter((link) => link.fulfillment_set_id === fulfillmentSetId)
    .map((link) => link.stock_location_id)

  if (
    !stockLocationIds.some((stockLocationId) =>
      staticLocationSalesChannelLinks.some(
        (link) =>
          link.stock_location_id === stockLocationId &&
          link.sales_channel_id === staticCartSalesChannelId
      )
    )
  ) {
    return false
  }

  const regionCountries = new Set(
    (region?.countries ?? [])
      .map((country) => getStringValue(country, "iso_2") ?? "")
      .filter((countryCode) => countryCode.length > 0)
  )
  if (regionCountries.size === 0) {
    return true
  }

  return serviceZone.geo_zones.some((geoZone) =>
    regionCountries.has(geoZone.country_code.toLowerCase())
  )
}

function resolveStaticShippingOptionPrice(
  option: StaticShippingOption,
  itemTotal: number
): StaticShippingOptionPrice | null {
  const regionPrices = option.prices.filter((price) =>
    price.price_rules.some(
      (rule) =>
        rule.attribute === "region_id" && rule.value === staticCartRegionId
    )
  )
  const matchingRulePrice = regionPrices.find((price) =>
    price.price_rules.some(
      (rule) =>
        rule.attribute === "item_total" &&
        rule.operator === "gt" &&
        itemTotal > Number(rule.value)
    )
  )
  if (matchingRulePrice) {
    return matchingRulePrice
  }

  const regionPrice = regionPrices.find(
    (price) =>
      !price.price_rules.some((rule) => rule.attribute === "item_total")
  )
  if (regionPrice) {
    return regionPrice
  }

  const currencyPrices = option.prices.filter(
    (price) => price.currency_code === staticCartCurrencyCode
  )
  const matchingCurrencyRulePrice = currencyPrices.find((price) =>
    price.price_rules.some(
      (rule) =>
        rule.attribute === "item_total" &&
        rule.operator === "gt" &&
        itemTotal > Number(rule.value)
    )
  )
  if (matchingCurrencyRulePrice) {
    return matchingCurrencyRulePrice
  }

  return (
    currencyPrices.find(
      (price) =>
        !price.price_rules.some((rule) => rule.attribute === "item_total")
    ) ?? null
  )
}

function isStaticShippingOptionInventoryInsufficient(
  option: StaticShippingOption
): boolean {
  const serviceZone = getStaticServiceZoneById(option.service_zone_id)
  const fulfillmentSetId = serviceZone?.fulfillment_set_id
  const stockLocationId = staticLocationFulfillmentSetLinks.find(
    (link) => link.fulfillment_set_id === fulfillmentSetId
  )?.stock_location_id

  if (!stockLocationId) {
    return true
  }

  return staticCartLineItems.some((lineItem) => {
    const variant = getStaticProductVariantById(lineItem.variant_id)
    if (!variant?.manage_inventory) {
      return false
    }

    if (variant.allow_backorder) {
      return false
    }

    return variant.inventory_items.some((link) => {
      const inventoryItem = staticInventoryItems.find(
        (item) => item.id === link.inventory_item_id
      )
      const level = inventoryItem?.location_levels.find(
        (candidate) => candidate.location_id === stockLocationId
      )
      const requiredQuantity = link.required_quantity * lineItem.quantity

      return !level || level.available_quantity < requiredQuantity
    })
  })
}

function updateStaticShippingOptionsFromWorkflowInput(
  input: unknown
): StaticShippingOption[] {
  const shippingOptionInputs = Array.isArray(input) ? input : []
  const updated: StaticShippingOption[] = []

  for (const update of shippingOptionInputs) {
    if (!isRecord(update) || typeof update.id !== "string") {
      continue
    }

    const existing = staticShippingOptions.find(
      (shippingOption) => shippingOption.id === update.id
    )

    if (!existing) {
      continue
    }

    const providerId =
      typeof update.provider_id === "string"
        ? update.provider_id
        : existing.provider_id
    validateStaticShippingOptionProvider(existing.service_zone_id, providerId)

    const resolvedType =
      Object.prototype.hasOwnProperty.call(update, "type") ||
      Object.prototype.hasOwnProperty.call(update, "type_id")
        ? resolveStaticShippingOptionType(update)
        : existing.type

    if (!resolvedType) {
      continue
    }

    const timestamp = new Date(Date.UTC(2026, 5, 21, 1, 0, 0)).toISOString()
    const next: StaticShippingOption = {
      ...existing,
      name: typeof update.name === "string" ? update.name : existing.name,
      price_type:
        typeof update.price_type === "string"
          ? update.price_type
          : existing.price_type,
      data: Object.prototype.hasOwnProperty.call(update, "data")
        ? getRecordValue(update, "data") ?? null
        : existing.data,
      provider_id: providerId,
      metadata: Object.prototype.hasOwnProperty.call(update, "metadata")
        ? getRecordValue(update, "metadata") ?? null
        : existing.metadata,
      shipping_profile_id:
        typeof update.shipping_profile_id === "string"
          ? update.shipping_profile_id
          : existing.shipping_profile_id,
      type: resolvedType,
      prices: isArrayValue(update.prices)
        ? updateStaticShippingOptionPrices(existing.prices, update.prices)
        : existing.prices,
      rules: isArrayValue(update.rules)
        ? createStaticShippingOptionRules(update.rules, existing.id)
        : existing.rules,
      updated_at: timestamp,
    }

    staticShippingOptions = staticShippingOptions.map((shippingOption) =>
      shippingOption.id === next.id ? next : shippingOption
    )
    updated.push(next)
  }

  return updated
}

function deleteStaticShippingOptionsFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)
  staticShippingOptions = staticShippingOptions.filter(
    (shippingOption) => !ids.includes(shippingOption.id)
  )
  return ids
}

function batchStaticShippingOptionRulesFromWorkflowInput(
  input: unknown
): {
  created: StaticShippingOptionRule[]
  updated: StaticShippingOptionRule[]
  deleted: string[]
} {
  if (!isRecord(input)) {
    return { created: [], updated: [], deleted: [] }
  }

  const create = isArrayValue(input.create) ? input.create : []
  for (const rule of create) {
    if (!isRecord(rule) || typeof rule.shipping_option_id !== "string") {
      continue
    }

    if (
      !staticShippingOptions.some(
        (shippingOption) => shippingOption.id === rule.shipping_option_id
      )
    ) {
      throw new MedusaError(
        MedusaError.Types.NOT_FOUND,
        `You tried to set relationship shipping_option_id: ${rule.shipping_option_id}, but such entity does not exist`
      )
    }
  }

  return { created: [], updated: [], deleted: [] }
}

function resolveStaticShippingOptionType(
  input: Record<string, unknown>
): StaticShippingOptionType | null {
  if (typeof input.type_id === "string") {
    return (
      staticShippingOptionTypes.find((type) => type.id === input.type_id) ?? null
    )
  }

  const typeInput = getRecordValue(input, "type")
  if (!typeInput) {
    return null
  }

  staticShippingOptionTypeSequence += 1
  const timestamp = new Date(
    Date.UTC(2026, 5, 21, 0, 45, staticShippingOptionTypeSequence)
  ).toISOString()
  const type: StaticShippingOptionType = {
    id: `sotype_inline_worker_http_proof_${staticShippingOptionTypeSequence}`,
    label: getStringValue(typeInput, "label") ?? "",
    code: getStringValue(typeInput, "code") ?? "",
    description: getNullableStringValue(typeInput, "description"),
    created_at: timestamp,
    updated_at: timestamp,
  }

  staticShippingOptionTypes = [...staticShippingOptionTypes, type]
  return type
}

function createStaticShippingOptionPrices(
  prices: unknown[],
  timestamp: string
): StaticShippingOptionPrice[] {
  return prices.flatMap((price): StaticShippingOptionPrice[] => {
    if (!isRecord(price) || typeof price.amount !== "number") {
      return []
    }

    return [
      createStaticShippingOptionPrice({
        amount: price.amount,
        currencyCode: resolveStaticShippingOptionPriceCurrencyCode(price),
        rules: createStaticShippingOptionPriceRules(price),
        timestamp,
      }),
    ]
  })
}

function updateStaticShippingOptionPrices(
  existingPrices: StaticShippingOptionPrice[],
  prices: unknown[]
): StaticShippingOptionPrice[] {
  const timestamp = new Date(Date.UTC(2026, 5, 21, 1, 5, 0)).toISOString()

  return prices.flatMap((price): StaticShippingOptionPrice[] => {
    if (!isRecord(price)) {
      return []
    }

    const existing =
      typeof price.id === "string"
        ? existingPrices.find((current) => current.id === price.id)
        : undefined
    const amount =
      typeof price.amount === "number" ? price.amount : existing?.amount
    if (typeof amount !== "number") {
      return []
    }

    if (existing) {
      const priceRules = isArrayValue(price.rules)
        ? createStaticShippingOptionPriceRules(price)
        : existing.price_rules

      return [
        {
          ...existing,
          amount,
          raw_amount: {
            precision: 20,
            value: String(amount),
          },
          price_rules: priceRules,
          rules_count: priceRules.length,
          updated_at: timestamp,
        },
      ]
    }

    return [
      createStaticShippingOptionPrice({
        amount,
        currencyCode: resolveStaticShippingOptionPriceCurrencyCode(price),
        rules: createStaticShippingOptionPriceRules(price),
        timestamp,
      }),
    ]
  })
}

function createStaticShippingOptionPrice({
  amount,
  currencyCode,
  rules,
  timestamp,
}: {
  amount: number
  currencyCode: string
  rules: StaticShippingOptionPriceRule[]
  timestamp: string
}): StaticShippingOptionPrice {
  staticShippingOptionPriceSequence += 1
  return {
    id: `price_worker_http_proof_${staticShippingOptionPriceSequence}`,
    amount,
    currency_code: currencyCode,
    price_set_id: `pset_worker_http_proof_${staticShippingOptionPriceSequence}`,
    raw_amount: {
      precision: 20,
      value: String(amount),
    },
    rules_count: rules.length,
    price_rules: rules,
    title: null,
    price_list: null,
    price_list_id: null,
    min_quantity: null,
    max_quantity: null,
    created_at: timestamp,
    updated_at: timestamp,
    deleted_at: null,
  }
}

function createStaticShippingOptionPriceRules(
  price: Record<string, unknown>
): StaticShippingOptionPriceRule[] {
  const rules: StaticShippingOptionPriceRule[] = []
  const regionId = getStringValue(price, "region_id")
  if (regionId) {
    rules.push(createStaticShippingOptionPriceRule("region_id", "eq", regionId))
  }

  if (isArrayValue(price.rules)) {
    for (const rule of price.rules) {
      if (!isRecord(rule)) {
        continue
      }

      const attribute = getStringValue(rule, "attribute")
      const operator = getStringValue(rule, "operator")
      const value = rule.value
      if (!attribute || !operator || typeof value !== "number") {
        continue
      }

      rules.push(
        createStaticShippingOptionPriceRule(attribute, operator, String(value))
      )
    }
  }

  return rules
}

function createStaticShippingOptionPriceRule(
  attribute: string,
  operator: string,
  value: string
): StaticShippingOptionPriceRule {
  staticShippingOptionRuleSequence += 1
  return {
    id: `price_rule_worker_http_proof_${staticShippingOptionRuleSequence}`,
    attribute,
    operator,
    value,
  }
}

function createStaticShippingOptionRules(
  rules: unknown[],
  shippingOptionId: string
): StaticShippingOptionRule[] {
  return rules.flatMap((rule): StaticShippingOptionRule[] => {
    if (!isRecord(rule)) {
      return []
    }

    const attribute = getStringValue(rule, "attribute")
    const operator = getStringValue(rule, "operator")
    const value = getStringValue(rule, "value")
    if (!attribute || !operator || !value) {
      return []
    }

    staticShippingOptionRuleSequence += 1
    return [
      {
        id:
          typeof rule.id === "string"
            ? rule.id
            : `sorule_worker_http_proof_${staticShippingOptionRuleSequence}`,
        operator,
        attribute,
        value,
        shipping_option_id: shippingOptionId,
      },
    ]
  })
}

function resolveStaticShippingOptionPriceCurrencyCode(
  price: Record<string, unknown>
): string {
  const currencyCode = getStringValue(price, "currency_code")
  if (currencyCode) {
    return currencyCode
  }

  const regionId = getStringValue(price, "region_id")
  const region = regionId
    ? staticRegions.find((current) => current.id === regionId)
    : undefined

  return region?.currency_code ?? "usd"
}

function validateStaticShippingOptionProvider(
  serviceZoneId: string,
  providerId: string
): void {
  const stockLocationId = getStaticStockLocationIdForServiceZone(serviceZoneId)
  const isEnabled =
    !!stockLocationId &&
    staticLocationFulfillmentProviderLinks.some(
      (link) =>
        link.stock_location_id === stockLocationId &&
        link.fulfillment_provider_id === providerId
    )

  if (!isEnabled) {
    throw new MedusaError(
      MedusaError.Types.INVALID_DATA,
      `Providers (${providerId}) are not enabled for the service location`
    )
  }
}

function getStaticStockLocationIdForServiceZone(
  serviceZoneId: string
): string | null {
  const serviceZone = getStaticServiceZoneById(serviceZoneId)
  if (!serviceZone) {
    return null
  }

  return (
    staticLocationFulfillmentSetLinks.find(
      (link) => link.fulfillment_set_id === serviceZone.fulfillment_set_id
    )?.stock_location_id ?? null
  )
}

function createStaticShippingProfilesFromWorkflowInput(
  input: unknown
): StaticShippingProfile[] {
  if (!isRecord(input) || !Array.isArray(input.data)) {
    return []
  }

  const created = input.data.flatMap((profile): StaticShippingProfile[] => {
    if (
      !isRecord(profile) ||
      typeof profile.name !== "string" ||
      typeof profile.type !== "string"
    ) {
      return []
    }

    staticShippingProfileSequence += 1
    const timestamp = new Date(
      Date.UTC(2026, 5, 21, 1, 30, staticShippingProfileSequence)
    ).toISOString()

    return [
      {
        id: `sp_${staticShippingProfileSequence
          .toString()
          .padStart(24, "0")}`,
        name: profile.name,
        type: profile.type,
        shipping_options: [],
        metadata: getRecordValue(profile, "metadata") ?? null,
        created_at: timestamp,
        updated_at: timestamp,
        deleted_at: null,
      },
    ]
  })

  staticShippingProfiles = [...created, ...staticShippingProfiles]
  return created
}

function updateStaticShippingProfilesFromWorkflowInput(
  input: unknown
): StaticShippingProfile[] {
  if (!isRecord(input)) {
    return []
  }

  const selector = isRecord(input.selector) ? input.selector : undefined
  const update = isRecord(input.update) ? input.update : undefined
  const idFilters = normalizeStringFilter(selector?.id)

  if (!update || idFilters.length === 0) {
    return []
  }

  const updated: StaticShippingProfile[] = []
  staticShippingProfiles = staticShippingProfiles.map((profile) => {
    if (!idFilters.includes(profile.id)) {
      return profile
    }

    const next: StaticShippingProfile = {
      ...profile,
      name: typeof update.name === "string" ? update.name : profile.name,
      type: typeof update.type === "string" ? update.type : profile.type,
      metadata: Object.prototype.hasOwnProperty.call(update, "metadata")
        ? getRecordValue(update, "metadata") ?? null
        : profile.metadata,
      updated_at: new Date(Date.UTC(2026, 5, 21, 1, 40, 0)).toISOString(),
    }

    updated.push(next)
    return next
  })

  return updated
}

function deleteStaticShippingProfilesFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)

  if (ids.length === 0) {
    return []
  }

  staticShippingProfiles = staticShippingProfiles.filter(
    (profile) => !ids.includes(profile.id)
  )

  return ids
}

function createStaticStockLocationsFromWorkflowInput(
  input: unknown
): StaticStockLocation[] {
  if (!isRecord(input) || !Array.isArray(input.locations)) {
    return []
  }

  const created = input.locations.flatMap((location): StaticStockLocation[] => {
    if (!isRecord(location) || typeof location.name !== "string") {
      return []
    }

    staticStockLocationSequence += 1
    const timestamp = new Date(
      Date.UTC(2026, 5, 21, 1, 50, staticStockLocationSequence)
    ).toISOString()
    const address = createStaticStockLocationAddress(
      `sloca_${staticStockLocationSequence.toString().padStart(24, "0")}`,
      getRecordValue(location, "address")
    )
    const addressId =
      typeof location.address_id === "string"
        ? location.address_id
        : address?.id ?? null

    return [
      {
        id: `sloc_${staticStockLocationSequence
          .toString()
          .padStart(24, "0")}`,
        name: location.name,
        address_id: addressId,
        address,
        metadata: getRecordValue(location, "metadata") ?? null,
        created_at: timestamp,
        updated_at: timestamp,
      },
    ]
  })

  staticStockLocations = [...staticStockLocations, ...created]
  return created
}

function updateStaticStockLocationsFromWorkflowInput(
  input: unknown
): StaticStockLocation[] {
  if (!isRecord(input)) {
    return []
  }

  const selector = getRecordValue(input, "selector")
  const update = getRecordValue(input, "update")
  const idFilters = normalizeStringFilter(selector?.id)

  if (!update || idFilters.length === 0) {
    return []
  }

  const updatedLocations: StaticStockLocation[] = []
  staticStockLocations = staticStockLocations.map((stockLocation) => {
    if (!idFilters.includes(stockLocation.id)) {
      return stockLocation
    }

    const address = Object.prototype.hasOwnProperty.call(update, "address")
      ? createStaticStockLocationAddress(
          stockLocation.address?.id ??
            `sloca_${stockLocation.id.replace(/^sloc_/, "")}`,
          getRecordValue(update, "address")
        )
      : stockLocation.address

    const updated: StaticStockLocation = {
      ...stockLocation,
      name: getStringValue(update, "name") ?? stockLocation.name,
      address_id: Object.prototype.hasOwnProperty.call(update, "address_id")
        ? getNullableStringValue(update, "address_id")
        : address?.id ?? stockLocation.address_id,
      address,
      metadata: Object.prototype.hasOwnProperty.call(update, "metadata")
        ? getRecordValue(update, "metadata") ?? null
        : stockLocation.metadata,
      updated_at: new Date(Date.UTC(2026, 5, 21, 1, 55, 0)).toISOString(),
    }

    updatedLocations.push(updated)
    return updated
  })

  return updatedLocations
}

function deleteStaticStockLocationsFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)
  if (ids.length === 0) {
    return []
  }

  staticStockLocations = staticStockLocations.filter(
    (stockLocation) => !ids.includes(stockLocation.id)
  )
  staticLocationFulfillmentProviderLinks =
    staticLocationFulfillmentProviderLinks.filter(
      (link) => !ids.includes(link.stock_location_id)
    )
  staticLocationSalesChannelLinks = staticLocationSalesChannelLinks.filter(
    (link) => !ids.includes(link.stock_location_id)
  )
  const fulfillmentSetIdsToDelete = staticLocationFulfillmentSetLinks
    .filter((link) => ids.includes(link.stock_location_id))
    .map((link) => link.fulfillment_set_id)
  staticLocationFulfillmentSetLinks =
    staticLocationFulfillmentSetLinks.filter(
      (link) => !ids.includes(link.stock_location_id)
    )
  staticFulfillmentSets = staticFulfillmentSets.filter(
    (fulfillmentSet) => !fulfillmentSetIdsToDelete.includes(fulfillmentSet.id)
  )

  return ids
}

function createStaticStockLocationAddress(
  id: string,
  input: unknown
): StaticStockLocationAddress | null {
  if (!isRecord(input)) {
    return null
  }

  const address1 = getStringValue(input, "address_1")
  const countryCode = getStringValue(input, "country_code")

  if (!address1 || !countryCode) {
    return null
  }

  return {
    id,
    address_1: address1,
    address_2: getNullableStringValue(input, "address_2"),
    company: getNullableStringValue(input, "company"),
    city: getNullableStringValue(input, "city"),
    country_code: countryCode,
    phone: getNullableStringValue(input, "phone"),
    province: getNullableStringValue(input, "province"),
    postal_code: getNullableStringValue(input, "postal_code"),
    metadata: getRecordValue(input, "metadata") ?? null,
  }
}

function applyStaticSalesChannelLinksFromWorkflowInput(input: unknown): void {
  if (!isRecord(input)) {
    return
  }

  const stockLocationId = getStringValue(input, "id")
  if (!stockLocationId) {
    return
  }

  const add = normalizeStringFilter(input.add)
  const remove = normalizeStringFilter(input.remove)

  for (const salesChannelId of add) {
    const exists = staticLocationSalesChannelLinks.some(
      (link) =>
        link.stock_location_id === stockLocationId &&
        link.sales_channel_id === salesChannelId
    )

    if (!exists) {
      staticLocationSalesChannelLinks.push({
        stock_location_id: stockLocationId,
        sales_channel_id: salesChannelId,
      })
    }
  }

  if (remove.length === 0) {
    return
  }

  staticLocationSalesChannelLinks = staticLocationSalesChannelLinks.filter(
    (link) =>
      link.stock_location_id !== stockLocationId ||
      !remove.includes(link.sales_channel_id)
  )
}

function createStaticLocationFulfillmentSetFromWorkflowInput(
  input: unknown
): StaticFulfillmentSet[] {
  if (!isRecord(input)) {
    return []
  }

  const stockLocationId = getStringValue(input, "location_id")
  const fulfillmentSetData = getRecordValue(input, "fulfillment_set_data")
  const name = fulfillmentSetData
    ? getStringValue(fulfillmentSetData, "name")
    : undefined
  const type = fulfillmentSetData
    ? getStringValue(fulfillmentSetData, "type")
    : undefined

  if (!stockLocationId || !name || !type) {
    return []
  }

  staticFulfillmentSetSequence += 1
  const now = new Date(
    Date.UTC(2026, 5, 21, 2, 10, staticFulfillmentSetSequence)
  ).toISOString()
  const fulfillmentSet: StaticFulfillmentSet = {
    id: `fuset_${staticFulfillmentSetSequence
      .toString()
      .padStart(24, "0")}`,
    name,
    type,
    metadata: null,
    service_zones: [],
    created_at: now,
    updated_at: now,
    deleted_at: null,
  }

  staticFulfillmentSets.push(fulfillmentSet)
  staticLocationFulfillmentSetLinks.push({
    stock_location_id: stockLocationId,
    fulfillment_set_id: fulfillmentSet.id,
  })

  return [fulfillmentSet]
}

function deleteStaticFulfillmentSetsFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)
  if (ids.length === 0) {
    return []
  }

  staticFulfillmentSets = staticFulfillmentSets.filter(
    (fulfillmentSet) => !ids.includes(fulfillmentSet.id)
  )
  staticLocationFulfillmentSetLinks =
    staticLocationFulfillmentSetLinks.filter(
      (link) => !ids.includes(link.fulfillment_set_id)
    )

  return ids
}

function createStaticServiceZonesFromWorkflowInput(
  input: unknown
): StaticServiceZone[] {
  const serviceZoneData = isRecord(input) && Array.isArray(input.data)
    ? input.data
    : []

  return serviceZoneData.flatMap((data): StaticServiceZone[] => {
    if (!isRecord(data)) {
      return []
    }

    const fulfillmentSetId = getStringValue(data, "fulfillment_set_id")
    const name = getStringValue(data, "name")
    const fulfillmentSet = fulfillmentSetId
      ? staticFulfillmentSets.find((set) => set.id === fulfillmentSetId)
      : undefined

    if (!fulfillmentSetId || !name || !fulfillmentSet) {
      return []
    }

    const serviceZone = createStaticServiceZone({
      fulfillmentSetId,
      name,
      geoZones: Array.isArray(data.geo_zones) ? data.geo_zones : [],
    })

    fulfillmentSet.service_zones.push(serviceZone)
    return [serviceZone]
  })
}

function parseStaticFulfillmentSets(input: unknown): StaticFulfillmentSet[] {
  return getStaticPayloadRows(input, "fulfillment_sets").flatMap(
    (fulfillmentSet): StaticFulfillmentSet[] => {
      const id = getStringValue(fulfillmentSet, "id")
      const name = getStringValue(fulfillmentSet, "name")
      const type = getStringValue(fulfillmentSet, "type")
      if (!id || !name || !type) {
        return []
      }

      const timestamp = getStaticRowTimestamp(fulfillmentSet)
      return [
        {
          id,
          name,
          type,
          metadata: getRecordValue(fulfillmentSet, "metadata") ?? null,
          service_zones: getStaticNestedRows(
            fulfillmentSet,
            "service_zones"
          ).flatMap((serviceZone) =>
            parseStaticServiceZone(serviceZone, id)
          ),
          created_at: timestamp,
          updated_at: getStringValue(fulfillmentSet, "updated_at") ?? timestamp,
          deleted_at: null,
        },
      ]
    }
  )
}

function parseStaticServiceZone(
  serviceZone: Record<string, unknown>,
  fulfillmentSetId: string
): StaticServiceZone[] {
  const id = getStringValue(serviceZone, "id")
  const name = getStringValue(serviceZone, "name")
  if (!id || !name) {
    return []
  }

  const timestamp = getStaticRowTimestamp(serviceZone)
  return [
    {
      id,
      name,
      fulfillment_set_id:
        getStringValue(serviceZone, "fulfillment_set_id") ?? fulfillmentSetId,
      geo_zones: getStaticNestedRows(serviceZone, "geo_zones").flatMap(
        (geoZone, index) => parseStaticGeoZone(geoZone, id, index)
      ),
      created_at: timestamp,
      updated_at: getStringValue(serviceZone, "updated_at") ?? timestamp,
      deleted_at: null,
    },
  ]
}

function updateStaticServiceZonesFromWorkflowInput(
  input: unknown
): StaticServiceZone[] {
  if (!isRecord(input)) {
    return []
  }

  const selector = getRecordValue(input, "selector")
  const update = getRecordValue(input, "update")
  const idFilters = normalizeStringFilter(selector?.id)

  if (!update || idFilters.length === 0) {
    return []
  }

  const updatedServiceZones: StaticServiceZone[] = []

  for (const fulfillmentSet of staticFulfillmentSets) {
    fulfillmentSet.service_zones = fulfillmentSet.service_zones.map(
      (serviceZone) => {
        if (!idFilters.includes(serviceZone.id)) {
          return serviceZone
        }

        const updated: StaticServiceZone = {
          ...serviceZone,
          name: getStringValue(update, "name") ?? serviceZone.name,
          geo_zones: Array.isArray(update.geo_zones)
            ? createStaticGeoZones(serviceZone.id, update.geo_zones)
            : serviceZone.geo_zones,
          updated_at: new Date(Date.UTC(2026, 5, 21, 2, 25, 0)).toISOString(),
        }

        updatedServiceZones.push(updated)
        return updated
      }
    )
  }

  return updatedServiceZones
}

function deleteStaticServiceZonesFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)
  if (ids.length === 0) {
    return []
  }

  for (const fulfillmentSet of staticFulfillmentSets) {
    fulfillmentSet.service_zones = fulfillmentSet.service_zones.filter(
      (serviceZone) => !ids.includes(serviceZone.id)
    )
  }

  return ids
}

function createStaticServiceZone({
  fulfillmentSetId,
  name,
  geoZones,
}: {
  fulfillmentSetId: string
  name: string
  geoZones: unknown[]
}): StaticServiceZone {
  const sequence = nextStaticServiceZoneSequence()
  const now = new Date(Date.UTC(2026, 5, 21, 2, 20, sequence)).toISOString()
  const id = `serzo_${sequence.toString().padStart(24, "0")}`

  return {
    id,
    name,
    fulfillment_set_id: fulfillmentSetId,
    geo_zones: createStaticGeoZones(id, geoZones),
    created_at: now,
    updated_at: now,
    deleted_at: null,
  }
}

function createStaticGeoZones(
  serviceZoneId: string,
  geoZones: unknown[]
): StaticGeoZone[] {
  return geoZones.flatMap((geoZone, index): StaticGeoZone[] => {
    if (!isRecord(geoZone)) {
      return []
    }

    return parseStaticGeoZone(geoZone, serviceZoneId, index)
  })
}

function parseStaticGeoZone(
  geoZone: Record<string, unknown>,
  serviceZoneId: string,
  index: number
): StaticGeoZone[] {
  const type = getStringValue(geoZone, "type")
  const countryCode = getStringValue(geoZone, "country_code")

  if (!type || !countryCode) {
    return []
  }

  const existingId = getStringValue(geoZone, "id")
  const postalExpression = getRecordValue(geoZone, "postal_expression")
  const result: StaticGeoZone = {
    id:
      existingId ??
      `geoz_${serviceZoneId.replace(/^serzo_/, "")}_${index
        .toString()
        .padStart(4, "0")}`,
    service_zone_id: serviceZoneId,
    type,
    country_code: countryCode,
  }

  const provinceCode = getStringValue(geoZone, "province_code")
  const city = getStringValue(geoZone, "city")
  if (provinceCode) {
    result.province_code = provinceCode
  }
  if (city) {
    result.city = city
  }
  if (postalExpression) {
    result.postal_expression = postalExpression
  }

  return [result]
}

function nextStaticServiceZoneSequence(): number {
  staticFulfillmentSetSequence += 1
  return staticFulfillmentSetSequence
}

function applyStaticBatchLinksFromWorkflowInput(input: unknown): void {
  if (!isRecord(input)) {
    return
  }

  const createLinks = Array.isArray(input.create) ? input.create : []
  const deleteLinks = Array.isArray(input.delete) ? input.delete : []

  for (const link of createLinks) {
    const parsed = parseStaticLocationFulfillmentProviderLink(link)
    if (!parsed) {
      continue
    }

    const exists = staticLocationFulfillmentProviderLinks.some(
      (current) =>
        current.stock_location_id === parsed.stock_location_id &&
        current.fulfillment_provider_id === parsed.fulfillment_provider_id
    )

    if (!exists) {
      staticLocationFulfillmentProviderLinks.push(parsed)
    }
  }

  const parsedDeleteLinks = deleteLinks.flatMap(
    (link): StaticLocationFulfillmentProviderLink[] => {
      const parsed = parseStaticLocationFulfillmentProviderLink(link)
      return parsed ? [parsed] : []
    }
  )

  if (parsedDeleteLinks.length === 0) {
    return
  }

  staticLocationFulfillmentProviderLinks =
    staticLocationFulfillmentProviderLinks.filter(
      (current) =>
        !parsedDeleteLinks.some(
          (link) =>
            link.stock_location_id === current.stock_location_id &&
            link.fulfillment_provider_id === current.fulfillment_provider_id
        )
    )
}

function parseStaticLocationFulfillmentProviderLink(
  input: unknown
): StaticLocationFulfillmentProviderLink | null {
  if (!isRecord(input)) {
    return null
  }

  const stockLocation = getRecordValue(input, Modules.STOCK_LOCATION)
  const fulfillment = getRecordValue(input, Modules.FULFILLMENT)
  const stockLocationId = getStringValue(stockLocation ?? {}, "stock_location_id")
  const fulfillmentProviderId = getStringValue(
    fulfillment ?? {},
    "fulfillment_provider_id"
  )

  if (!stockLocationId || !fulfillmentProviderId) {
    return null
  }

  return {
    stock_location_id: stockLocationId,
    fulfillment_provider_id: fulfillmentProviderId,
  }
}

function createStaticRegionsFromWorkflowInput(input: unknown): StaticRegion[] {
  if (!isRecord(input) || !Array.isArray(input.regions)) {
    return []
  }

  const incomingKeys = input.regions.flatMap((region): string[] => {
    if (!isRecord(region) || typeof region.name !== "string") {
      return []
    }

    return [`${region.name}:${getStringValue(region, "currency_code") ?? ""}`]
  })
  const existingKeys = new Set(
    staticRegions.map((region) => `${region.name}:${region.currency_code}`)
  )
  if (incomingKeys.some((key) => existingKeys.has(key))) {
    staticRegions = []
    staticRegionSequence = 0
    staticRegionPaymentProviderLinks = []
  }

  const created = input.regions.flatMap((region): StaticRegion[] => {
    if (
      !isRecord(region) ||
      typeof region.name !== "string" ||
      typeof region.currency_code !== "string"
    ) {
      return []
    }

    staticRegionSequence += 1
    const timestamp = new Date(
      Date.UTC(2026, 5, 21, 0, 10, staticRegionSequence)
    ).toISOString()

    return [
      {
        id: `reg_worker_http_proof_${staticRegionSequence}`,
        name: region.name,
        currency_code: region.currency_code,
        automatic_taxes:
          typeof region.automatic_taxes === "boolean"
            ? region.automatic_taxes
            : true,
        countries: parseStaticRegionCountries(region.countries),
        is_tax_inclusive:
          typeof region.is_tax_inclusive === "boolean"
            ? region.is_tax_inclusive
            : false,
        metadata: getRecordValue(region, "metadata") ?? null,
        created_at: timestamp,
        updated_at: timestamp,
        deleted_at: getNullableStringValue(region, "deleted_at"),
      },
    ]
  })

  staticRegions = [...staticRegions, ...created]
  for (const [index, region] of created.entries()) {
    const source = input.regions[index]
    if (isRecord(source)) {
      replaceStaticRegionPaymentProviderLinks(
        region.id,
        normalizeStaticRegionPaymentProviderIds(source.payment_providers)
      )
    }
  }
  return created
}

function parseStaticRegions(input: unknown): StaticRegion[] {
  return getStaticPayloadRows(input, "regions").flatMap(
    (region): StaticRegion[] => {
      const id = getStringValue(region, "id")
      const name = getStringValue(region, "name")
      const currencyCode = getStringValue(region, "currency_code")
      if (!id || !name || !currencyCode) {
        return []
      }

      const timestamp = getStaticRowTimestamp(region)
      return [
        {
          id,
          name,
          currency_code: currencyCode,
          automatic_taxes: getBooleanValue(region, "automatic_taxes") ?? true,
          countries: parseStaticRegionCountries(
            getStaticNestedRows(region, "countries")
          ),
          is_tax_inclusive:
            getBooleanValue(region, "is_tax_inclusive") ?? false,
          metadata: getRecordValue(region, "metadata") ?? null,
          created_at: getStringValue(region, "created_at") ?? timestamp,
          updated_at: getStringValue(region, "updated_at") ?? timestamp,
          deleted_at: getNullableStringValue(region, "deleted_at"),
        },
      ]
    }
  )
}

function parseStaticRegionCountries(input: unknown): Array<Record<string, unknown>> {
  if (!Array.isArray(input)) {
    return []
  }

  return input.flatMap((country): Array<Record<string, unknown>> => {
    if (isRecord(country)) {
      const iso2 = getStringValue(country, "iso_2")
      if (!iso2) {
        return []
      }

      return [
        {
          iso_2: iso2.toLowerCase(),
        },
      ]
    }

    if (typeof country !== "string") {
      return []
    }

    return [
      {
        iso_2: country.toLowerCase(),
      },
    ]
  })
}

function updateStaticRegionsFromWorkflowInput(input: unknown): StaticRegion[] {
  if (!isRecord(input)) {
    return []
  }

  const selector = isRecord(input.selector) ? input.selector : undefined
  const update = isRecord(input.update) ? input.update : undefined
  const regionId = typeof selector?.id === "string" ? selector.id : undefined

  if (!regionId || !update) {
    return []
  }

  const updated: StaticRegion[] = []
  staticRegions = staticRegions.map((region) => {
    if (region.id !== regionId) {
      return region
    }

    const nextRegion: StaticRegion = {
      ...region,
      name: typeof update.name === "string" ? update.name : region.name,
      currency_code:
        typeof update.currency_code === "string"
          ? update.currency_code
          : region.currency_code,
      automatic_taxes:
        typeof update.automatic_taxes === "boolean"
          ? update.automatic_taxes
          : region.automatic_taxes,
      is_tax_inclusive:
        typeof update.is_tax_inclusive === "boolean"
          ? update.is_tax_inclusive
          : region.is_tax_inclusive,
      metadata: getRecordValue(update, "metadata") ?? region.metadata,
      countries: Object.prototype.hasOwnProperty.call(update, "countries")
        ? parseStaticRegionCountries(update.countries)
        : region.countries,
      updated_at: new Date(Date.UTC(2026, 5, 21, 0, 20, 0)).toISOString(),
    }

    if (Object.prototype.hasOwnProperty.call(update, "payment_providers")) {
      replaceStaticRegionPaymentProviderLinks(
        region.id,
        normalizeStaticRegionPaymentProviderIds(update.payment_providers)
      )
    }

    updated.push(nextRegion)
    return nextRegion
  })

  return updated
}

function deleteStaticRegionsFromWorkflowInput(input: unknown): string[] {
  if (!isRecord(input)) {
    return []
  }

  const ids = normalizeStringFilter(input.ids)
  if (ids.length === 0) {
    return []
  }

  const deletedAt = new Date(Date.UTC(2026, 5, 21, 0, 30, 0)).toISOString()
  staticRegions = staticRegions.map((region) =>
    ids.includes(region.id)
      ? {
          ...region,
          deleted_at: deletedAt,
          updated_at: deletedAt,
        }
      : region
  )
  staticRegionPaymentProviderLinks = staticRegionPaymentProviderLinks.filter(
    (link) => !ids.includes(link.region_id)
  )

  return ids
}

function normalizeStaticRegionPaymentProviderIds(value: unknown): string[] {
  const providerIds = normalizeStringFilter(value)
  const missing = providerIds.filter(
    (providerId) => !isStaticAvailablePaymentProvider(providerId)
  )

  if (missing.length > 0) {
    throw new MedusaError(
      MedusaError.Types.NOT_FOUND,
      `Payment providers with ids ${missing.join(", ")} not found or not enabled`
    )
  }

  return providerIds
}

function isStaticAvailablePaymentProvider(providerId: string): boolean {
  return providerId === "pp_system_default" || providerId === "pp_system_default_2"
}

function replaceStaticRegionPaymentProviderLinks(
  regionId: string,
  paymentProviderIds: string[]
): void {
  staticRegionPaymentProviderLinks = staticRegionPaymentProviderLinks.filter(
    (link) => link.region_id !== regionId
  )

  for (const paymentProviderId of paymentProviderIds) {
    staticRegionPaymentProviderLinks.push({
      region_id: regionId,
      payment_provider_id: paymentProviderId,
    })
  }
}

