function parseStaticPayments(input: unknown): StaticPayment[] {
  return getStaticPayloadRows(input, "payments").flatMap(
    (payment): StaticPayment[] => {
      const id = getStringValue(payment, "id")
      const paymentCollectionId = getStringValue(payment, "payment_collection_id")
      const amount = getNumericValue(payment, "amount")
      const currencyCode = getStringValue(payment, "currency_code")
      const providerId = getStringValue(payment, "provider_id")
      const paymentSessionId = getStringValue(payment, "payment_session_id")
      if (
        !id ||
        !paymentCollectionId ||
        amount === undefined ||
        !currencyCode ||
        !providerId
      ) {
        return []
      }

      const timestamp = getStaticRowTimestamp(payment)
      return [
        {
          id,
          payment_collection_id: paymentCollectionId,
          amount,
          raw_amount: amount,
          authorized_amount: amount,
          currency_code: currencyCode,
          provider_id: providerId,
          captured_at: getStaticPaymentCapturedAt(payment, amount),
          canceled_at: getNullableStringValue(payment, "canceled_at"),
          captures: parseStaticPaymentCaptures(payment, id),
          refunds: [],
          created_at: timestamp,
          updated_at: timestamp,
          ...(paymentSessionId ? { payment_session_id: paymentSessionId } : {}),
        },
      ]
    }
  )
}

function parseStaticPaymentCaptures(
  payment: Record<string, unknown>,
  paymentId: string
): StaticPaymentCapture[] {
  const captures = Array.isArray(payment.captures) ? payment.captures : []

  return captures.filter(isRecord).flatMap(
    (capture): StaticPaymentCapture[] => {
      const id = getStringValue(capture, "id")
      const amount = getNumericValue(capture, "amount")
      if (!id || amount === undefined) {
        return []
      }

      const timestamp = getStaticRowTimestamp(capture)
      return [
        {
          id,
          payment_id: getStringValue(capture, "payment_id") ?? paymentId,
          amount,
          raw_amount: amount,
          created_at: timestamp,
          updated_at: timestamp,
        },
      ]
    }
  )
}

function getStaticPaymentCapturedAt(
  payment: Record<string, unknown>,
  amount: number
): string | null {
  const captures = parseStaticPaymentCaptures(
    payment,
    getStringValue(payment, "id") ?? staticPaymentId
  )
  const capturedAmount = captures.reduce((sum, capture) => sum + capture.amount, 0)
  if (capturedAmount < amount) {
    return null
  }

  return captures[captures.length - 1]?.created_at ?? getStaticRowTimestamp(payment)
}

function parseStaticInventoryLevels(input: unknown): StaticInventoryLevel[] {
  return getStaticPayloadRows(input, "inventory_levels").flatMap(
    (level): StaticInventoryLevel[] => {
      const inventoryItemId = getStringValue(level, "inventory_item_id")
      const locationId = getStringValue(level, "location_id")
      if (!inventoryItemId || !locationId) {
        return []
      }

      const stockedQuantity =
        typeof level.stocked_quantity === "number"
          ? level.stocked_quantity
          : 0
      const reservedQuantity =
        typeof level.reserved_quantity === "number"
          ? level.reserved_quantity
          : 0
      const now = getStaticRowTimestamp(level)

      if (typeof level.id !== "string") {
        staticInventoryLevelSequence += 1
      }

      return [
        {
          id:
            getStringValue(level, "id") ??
            `ilev_worker_http_proof_${staticInventoryLevelSequence}`,
          inventory_item_id: inventoryItemId,
          location_id: locationId,
          stocked_quantity: stockedQuantity,
          reserved_quantity: reservedQuantity,
          incoming_quantity:
            typeof level.incoming_quantity === "number"
              ? level.incoming_quantity
              : 0,
          available_quantity: stockedQuantity - reservedQuantity,
          metadata: getRecordValue(level, "metadata") ?? null,
          created_at: now,
          updated_at: now,
        },
      ]
    }
  )
}

