function parseStaticTaxRegions(input: unknown): StaticTaxRegion[] {
  return getStaticPayloadRows(input, "tax_regions").flatMap(
    (taxRegion): StaticTaxRegion[] => {
      const id = getStringValue(taxRegion, "id")
      const countryCode = getStringValue(taxRegion, "country_code")
      if (!id || !countryCode) {
        return []
      }

      const now = getStaticRowTimestamp(taxRegion)
      return [
        {
          id,
          country_code: countryCode.toLowerCase(),
          province_code: getNullableStringValue(
            taxRegion,
            "province_code"
          )?.toLowerCase() ?? null,
          parent_id: getNullableStringValue(taxRegion, "parent_id"),
          provider_id: getNullableStringValue(taxRegion, "provider_id"),
          has_default_tax_rate:
            getStaticNestedRows(taxRegion, "tax_rates").some(
              (taxRate) => getBooleanValue(taxRate, "is_default") === true
            ),
          default_tax_rate: getStaticTaxRegionDefaultRate(taxRegion),
          default_tax_rate_code:
            getStaticTaxRegionDefaultRateCode(taxRegion),
          default_tax_rate_name:
            getStaticTaxRegionDefaultRateName(taxRegion),
          created_by: getNullableStringValue(taxRegion, "created_by"),
          metadata: getRecordValue(taxRegion, "metadata") ?? null,
          created_at: now,
          updated_at: getStringValue(taxRegion, "updated_at") ?? now,
          deleted_at: getNullableStringValue(taxRegion, "deleted_at"),
        },
      ]
    }
  )
}

function parseStaticTaxRates(input: unknown): StaticTaxRate[] {
  return getStaticPayloadRows(input, "tax_rates").flatMap(
    (taxRate): StaticTaxRate[] => {
      const id = getStringValue(taxRate, "id")
      const taxRegionId = getStringValue(taxRate, "tax_region_id")
      if (!id || !taxRegionId) {
        return []
      }

      const now = getStaticRowTimestamp(taxRate)
      const ruleRows = getStaticNestedRows(taxRate, "rules")
      const existing = staticTaxRates.find((current) => current.id === id)
      return [
        {
          id,
          name: getStringValue(taxRate, "name") ?? "Tax Rate",
          tax_region_id: taxRegionId,
          rate: getNumericValue(taxRate, "rate") ?? 0,
          code: getStringValue(taxRate, "code") ?? "TAX",
          is_combinable: getBooleanValue(taxRate, "is_combinable") ?? false,
          is_default: getBooleanValue(taxRate, "is_default") ?? false,
          created_by: getNullableStringValue(taxRate, "created_by"),
          metadata: getRecordValue(taxRate, "metadata") ?? null,
          rules:
            ruleRows.length > 0
              ? parseStaticTaxRateRulesForRate(id, ruleRows, now)
              : existing?.rules ?? [],
          created_at: now,
          updated_at: getStringValue(taxRate, "updated_at") ?? now,
          deleted_at: getNullableStringValue(taxRate, "deleted_at"),
        },
      ]
    }
  )
}

function getStaticTaxRegionDefaultRate(
  taxRegion: Record<string, unknown>
): number {
  const taxRates = getStaticNestedRows(taxRegion, "tax_rates")
  const defaultRate = taxRates.find(
    (taxRate) => getBooleanValue(taxRate, "is_default") === true
  )
  return defaultRate ? getNumericValue(defaultRate, "rate") ?? 10 : 10
}

function getStaticTaxRegionDefaultRateCode(
  taxRegion: Record<string, unknown>
): string {
  const taxRates = getStaticNestedRows(taxRegion, "tax_rates")
  const defaultRate = taxRates.find(
    (taxRate) => getBooleanValue(taxRate, "is_default") === true
  )
  return (
    (defaultRate ? getStringValue(defaultRate, "code") : undefined) ??
    getStringValue(taxRegion, "country_code") ??
    "tax"
  )
}

function getStaticTaxRegionDefaultRateName(
  taxRegion: Record<string, unknown>
): string {
  const taxRates = getStaticNestedRows(taxRegion, "tax_rates")
  const defaultRate = taxRates.find(
    (taxRate) => getBooleanValue(taxRate, "is_default") === true
  )
  return defaultRate ? getStringValue(defaultRate, "name") ?? "Worker Tax" : "Worker Tax"
}

