function parseStaticAuthIdentities(input: unknown): StaticAuthIdentity[] {
  return getStaticPayloadRows(input, "auth_identities").flatMap(
    (identity): StaticAuthIdentity[] => {
      const id = getStringValue(identity, "id")
      const providerIdentitiesValue = identity.provider_identities
      const providerIdentities = Array.isArray(providerIdentitiesValue)
        ? providerIdentitiesValue.filter(isRecord)
        : []
      const providerIdentity = providerIdentities[0]
      const provider = getStringValue(providerIdentity, "provider")
      const email = getStringValue(providerIdentity, "entity_id")

      if (!id || !provider || !email) {
        return []
      }

      const providerMetadata =
        getRecordValue(providerIdentity, "provider_metadata") ?? {}
      const userMetadata =
        getRecordValue(providerIdentity, "user_metadata") ?? { email }

      return [
        {
          id,
          provider,
          email,
          password: getStringValue(providerMetadata, "password") ?? "",
          app_metadata: getRecordValue(identity, "app_metadata") ?? {},
          user_metadata: userMetadata,
        },
      ]
    }
  )
}

function applyStaticRemoteLinks(input: unknown): void {
  for (const link of getStaticPayloadRows(input, "product_variant_price_set_links")) {
    const variantId = getStringValue(link, "variant_id")
    const priceSetId = getStringValue(link, "price_set_id")
    if (variantId && priceSetId) {
      pushUniqueStaticProductVariantPriceSetLink(variantId, priceSetId)
    }
  }

  const links = getStaticPayloadRows(input, "links")

  for (const link of links) {
    const product = getStaticLinkRecord(link, Modules.PRODUCT, "product")
    const salesChannel = getStaticLinkRecord(
      link,
      Modules.SALES_CHANNEL,
      "sales_channel"
    )
    const stockLocation = getStaticLinkRecord(
      link,
      Modules.STOCK_LOCATION,
      "stock_location"
    )
    const fulfillment = getStaticLinkRecord(
      link,
      Modules.FULFILLMENT,
      "fulfillment"
    )
    const inventory = getStaticLinkRecord(link, Modules.INVENTORY, "inventory")
    const apiKey = getStaticLinkRecord(link, Modules.API_KEY, "api_key")
    const user = getStaticLinkRecord(link, Modules.USER, "user")
    const rbac = getStaticLinkRecord(link, Modules.RBAC, "rbac")
    const rbacPolicy = getStaticLinkRecord(link, "rbac_policy", "policy")
    const cart = getStaticLinkRecord(link, Modules.CART, "cart")
    const promotion = getStaticLinkRecord(link, Modules.PROMOTION, "promotion")

    const productId = product
      ? getStringValue(product, "product_id")
      : undefined
    const variantId = product ? getStringValue(product, "variant_id") : undefined
    const salesChannelId = salesChannel
      ? getStringValue(salesChannel, "sales_channel_id")
      : undefined
    const stockLocationId = stockLocation
      ? getStringValue(stockLocation, "stock_location_id")
      : undefined
    const inventoryItemId = inventory
      ? getStringValue(inventory, "inventory_item_id")
      : undefined
    const fulfillmentProviderId = fulfillment
      ? getStringValue(fulfillment, "fulfillment_provider_id")
      : undefined
    const fulfillmentSetId = fulfillment
      ? getStringValue(fulfillment, "fulfillment_set_id")
      : undefined
    const data = getRecordValue(link, "data")
    const requiredQuantity =
      typeof data?.required_quantity === "number" ? data.required_quantity : 1
    const apiKeyId = apiKey
      ? getStringValue(apiKey, "publishable_key_id") ??
        getStringValue(apiKey, "api_key_id")
      : undefined
    const userId = user ? getStringValue(user, "user_id") : undefined
    const roleId = rbac ? getStringValue(rbac, "rbac_role_id") : undefined
    const rbacPolicyId = rbacPolicy
      ? getStringValue(rbacPolicy, "rbac_policy_id") ??
        getStringValue(rbacPolicy, "policy_id")
      : undefined
    const cartId = cart ? getStringValue(cart, "cart_id") : undefined
    const promotionId = promotion
      ? getStringValue(promotion, "promotion_id")
      : undefined
    const pricing = getStaticLinkRecord(link, Modules.PRICING, "pricing")
    const priceSetId = pricing
      ? getStringValue(pricing, "price_set_id")
      : undefined

    if (productId && salesChannelId) {
      pushUniqueStaticProductSalesChannelLink(productId, salesChannelId)
    }

    if (variantId && priceSetId) {
      pushUniqueStaticProductVariantPriceSetLink(variantId, priceSetId)
    }

    if (stockLocationId && salesChannelId) {
      pushUniqueStaticLocationSalesChannelLink(stockLocationId, salesChannelId)
    }

    if (stockLocationId && fulfillmentProviderId) {
      pushUniqueStaticLocationFulfillmentProviderLink(
        stockLocationId,
        fulfillmentProviderId
      )
    }

    if (stockLocationId && fulfillmentSetId) {
      pushUniqueStaticLocationFulfillmentSetLink(
        stockLocationId,
        fulfillmentSetId
      )
    }

    if (variantId && inventoryItemId) {
      pushUniqueStaticVariantInventoryItemLink(
        variantId,
        inventoryItemId,
        requiredQuantity
      )
    }

    if (apiKeyId && salesChannelId) {
      pushUniqueStaticApiKeySalesChannelLink(apiKeyId, salesChannelId)
    }

    if (userId && roleId) {
      pushUniqueStaticUserRbacRoleLink(userId, roleId)
    }

    if (roleId && rbacPolicyId) {
      createStaticRbacRolePolicy(roleId, rbacPolicyId)
    }

    if (cartId === staticCartId && promotionId) {
      pushUniqueStaticCartPromotion(promotionId)
    }
  }
}

function normalizeStaticLinkDefinitions(
  links: LinkDefinition | LinkDefinition[]
): LinkDefinition[] {
  return Array.isArray(links) ? links : [links]
}

function dismissStaticRemoteLinks(links: LinkDefinition[]): void {
  for (const link of links) {
    const linkRecord = link as Record<string, unknown>
    const user = getStaticLinkRecord(linkRecord, Modules.USER, "user")
    const rbac = getStaticLinkRecord(linkRecord, Modules.RBAC, "rbac")
    const userId = user ? getStringValue(user, "user_id") : undefined
    const roleId = rbac ? getStringValue(rbac, "rbac_role_id") : undefined

    if (userId && roleId) {
      staticUserRbacRoleLinks = staticUserRbacRoleLinks.filter(
        (candidate) =>
          !(candidate.user_id === userId && candidate.rbac_role_id === roleId)
      )
    }
  }
}

function pushUniqueStaticCartPromotion(promotionId: string): void {
  const promotion = staticPromotions.find(
    (candidate) => candidate.id === promotionId
  )
  if (!promotion) {
    return
  }

  const exists = staticCartPromotions.some(
    (cartPromotion) => cartPromotion.id === promotion.id
  )
  if (exists) {
    return
  }

  staticCartPromotions = [
    ...staticCartPromotions,
    {
      id: promotion.id,
      code: promotion.code,
    },
  ]
}

function applyStaticRemoteLinkDeletes(input: unknown): void {
  const links = getStaticPayloadRows(input, "links")

  for (const link of links) {
    const region = getStaticLinkRecord(link, Modules.REGION, "region")
    const payment = getStaticLinkRecord(link, Modules.PAYMENT, "payment")
    const product = getStaticLinkRecord(link, Modules.PRODUCT, "product")
    const inventory = getStaticLinkRecord(link, Modules.INVENTORY, "inventory")
    const regionId =
      getStringValue(link, "region_id") ??
      (region ? getStringValue(region, "region_id") : undefined)
    const paymentProviderId =
      getStringValue(link, "payment_provider_id") ??
      (payment ? getStringValue(payment, "payment_provider_id") : undefined)
    const variantId = product ? getStringValue(product, "variant_id") : undefined
    const inventoryItemId = inventory
      ? getStringValue(inventory, "inventory_item_id")
      : undefined

    if (regionId && paymentProviderId) {
      deleteStaticRegionPaymentProviderLink(regionId, paymentProviderId)
    }

    if (variantId && inventoryItemId) {
      deleteStaticVariantInventoryItemLink(variantId, inventoryItemId)
    }
  }
}

function pushUniqueStaticProductSalesChannelLink(
  productId: string,
  salesChannelId: string
): void {
  if (
    staticProductSalesChannelLinks.some(
      (link) =>
        link.product_id === productId &&
        link.sales_channel_id === salesChannelId
    )
  ) {
    return
  }

  staticProductSalesChannelLinks.push({
    product_id: productId,
    sales_channel_id: salesChannelId,
  })
}

function deleteStaticRegionPaymentProviderLink(
  regionId: string,
  paymentProviderId: string
): void {
  staticRegionPaymentProviderLinks = staticRegionPaymentProviderLinks.filter(
    (link) =>
      link.region_id !== regionId ||
      link.payment_provider_id !== paymentProviderId
  )
}

function pushUniqueStaticLocationSalesChannelLink(
  stockLocationId: string,
  salesChannelId: string
): void {
  if (
    staticLocationSalesChannelLinks.some(
      (link) =>
        link.stock_location_id === stockLocationId &&
        link.sales_channel_id === salesChannelId
    )
  ) {
    return
  }

  staticLocationSalesChannelLinks.push({
    stock_location_id: stockLocationId,
    sales_channel_id: salesChannelId,
  })
}

function pushUniqueStaticLocationFulfillmentProviderLink(
  stockLocationId: string,
  fulfillmentProviderId: string
): void {
  if (
    staticLocationFulfillmentProviderLinks.some(
      (link) =>
        link.stock_location_id === stockLocationId &&
        link.fulfillment_provider_id === fulfillmentProviderId
    )
  ) {
    return
  }

  staticLocationFulfillmentProviderLinks.push({
    stock_location_id: stockLocationId,
    fulfillment_provider_id: fulfillmentProviderId,
  })
}

function pushUniqueStaticLocationFulfillmentSetLink(
  stockLocationId: string,
  fulfillmentSetId: string
): void {
  if (
    staticLocationFulfillmentSetLinks.some(
      (link) =>
        link.stock_location_id === stockLocationId &&
        link.fulfillment_set_id === fulfillmentSetId
    )
  ) {
    return
  }

  staticLocationFulfillmentSetLinks.push({
    stock_location_id: stockLocationId,
    fulfillment_set_id: fulfillmentSetId,
  })
}

function pushUniqueStaticVariantInventoryItemLink(
  variantId: string,
  inventoryItemId: string,
  requiredQuantity = 1
): void {
  const variant = getStaticProductVariantById(variantId)
  if (!variant) {
    return
  }

  const existing = variant.inventory_items.find(
    (link) => link.inventory_item_id === inventoryItemId
  )
  if (existing) {
    existing.required_quantity = requiredQuantity
    return
  }

  variant.inventory_items.push({
    inventory_item_id: inventoryItemId,
    required_quantity: requiredQuantity,
  })
}

function deleteStaticVariantInventoryItemLink(
  variantId: string,
  inventoryItemId: string
): void {
  const variant = getStaticProductVariantById(variantId)
  if (!variant) {
    return
  }

  variant.inventory_items = variant.inventory_items.filter(
    (link) => link.inventory_item_id !== inventoryItemId
  )
}

function pushUniqueStaticApiKeySalesChannelLink(
  apiKeyId: string,
  salesChannelId: string
): void {
  if (
    staticApiKeySalesChannelLinks.some(
      (link) =>
        link.api_key_id === apiKeyId &&
        link.sales_channel_id === salesChannelId
    )
  ) {
    return
  }

  staticApiKeySalesChannelLinks.push({
    api_key_id: apiKeyId,
    sales_channel_id: salesChannelId,
  })
}

function pushUniqueStaticProductVariantPriceSetLink(
  variantId: string,
  priceSetId: string
): void {
  staticProductVariantPriceSetLinks = [
    ...staticProductVariantPriceSetLinks.filter(
      (link) => link.variant_id !== variantId
    ),
    {
      variant_id: variantId,
      price_set_id: priceSetId,
    },
  ]
}

function getStaticLinkRecord(
  link: Record<string, unknown>,
  moduleKey: string,
  fallbackKey: string
): Record<string, unknown> | undefined {
  return getRecordValue(link, moduleKey) ?? getRecordValue(link, fallbackKey)
}

function getStaticPayloadRows(
  input: unknown,
  key: string
): Record<string, unknown>[] {
  if (!isRecord(input)) {
    return []
  }

  const rows = input[key]
  if (!Array.isArray(rows)) {
    return []
  }

  return rows.filter(isRecord)
}

function getStaticNestedRows(
  parent: Record<string, unknown>,
  key: string
): Record<string, unknown>[] {
  const rows = parent[key]
  if (!Array.isArray(rows)) {
    return []
  }

  return rows.filter(isRecord)
}

function getStaticRowTimestamp(row: Record<string, unknown>): string {
  return (
    getStringValue(row, "created_at") ??
    getStringValue(row, "updated_at") ??
    "2026-06-21T00:00:00.000Z"
  )
}

function parseStaticStoreLocales(input: unknown): StaticStoreLocale[] {
  if (!isRecord(input) || !Array.isArray(input.supported_locales)) {
    return []
  }

  return input.supported_locales.flatMap((locale): StaticStoreLocale[] => {
    if (!isRecord(locale) || typeof locale.locale_code !== "string") {
      return []
    }

    return [
      {
        locale_code: locale.locale_code,
      },
    ]
  })
}

function parseStaticStores(input: unknown): StaticStore[] {
  const stores = isRecord(input) && Array.isArray(input.stores)
    ? input.stores
    : []

  return stores.flatMap((store): StaticStore[] => {
    if (!isRecord(store) || typeof store.id !== "string") {
      return []
    }

    const createdAt = getStringValue(store, "created_at")
    const updatedAt = getStringValue(store, "updated_at")

    return [
      {
        id: store.id,
        name: getStringValue(store, "name") ?? "Worker Store",
        supported_currencies: parseStaticStoreCurrencies(
          store.supported_currencies
        ),
        supported_locales: parseStaticStoreLocaleArray(store.supported_locales),
        default_sales_channel_id:
          getNullableStringValue(store, "default_sales_channel_id") ??
          "sc_worker_http_proof",
        default_region_id: getNullableStringValue(store, "default_region_id"),
        default_location_id: getNullableStringValue(
          store,
          "default_location_id"
        ),
        metadata: getRecordValue(store, "metadata") ?? null,
        created_at: createdAt ?? "2026-06-21T00:00:00.000Z",
        updated_at: updatedAt ?? createdAt ?? "2026-06-21T00:00:00.000Z",
      },
    ]
  })
}

function parseStaticStoreCurrencies(input: unknown): StaticStoreCurrency[] {
  if (!Array.isArray(input)) {
    return []
  }

  return input.flatMap((currency): StaticStoreCurrency[] => {
    if (!isRecord(currency) || typeof currency.currency_code !== "string") {
      return []
    }

    return [
      {
        currency_code: currency.currency_code,
        is_default: currency.is_default === true,
        is_tax_inclusive: currency.is_tax_inclusive === true,
      },
    ]
  })
}

function parseStaticStoreLocaleArray(input: unknown): StaticStoreLocale[] {
  if (!Array.isArray(input)) {
    return []
  }

  return input.flatMap((locale): StaticStoreLocale[] => {
    if (!isRecord(locale) || typeof locale.locale_code !== "string") {
      return []
    }

    return [
      {
        locale_code: locale.locale_code,
      },
    ]
  })
}

function parseStaticStoreIds(input: unknown): string[] {
  if (!isRecord(input) || !Array.isArray(input.ids)) {
    return []
  }

  return input.ids.filter((id): id is string => typeof id === "string")
}

function updateStaticStoresFromWorkflowInput(input: unknown): StaticStore[] {
  if (!isRecord(input)) {
    return []
  }

  const selector = getRecordValue(input, "selector")
  const update = getRecordValue(input, "update")
  const idFilters = normalizeStringFilter(selector?.id)

  if (!update || idFilters.length === 0) {
    return []
  }

  const updatedStores: StaticStore[] = []
  staticStores = staticStores.map((store) => {
    if (!idFilters.includes(store.id)) {
      return store
    }

    if (
      Object.prototype.hasOwnProperty.call(update, "supported_currencies")
    ) {
      validateStaticStoreCurrenciesUpdate(update.supported_currencies)
    }

    const nextStore: StaticStore = {
      ...store,
      name: getStringValue(update, "name") ?? store.name,
      supported_currencies: Object.prototype.hasOwnProperty.call(
        update,
        "supported_currencies"
      )
        ? parseStaticStoreCurrencies(update.supported_currencies)
        : store.supported_currencies,
      supported_locales: Object.prototype.hasOwnProperty.call(
        update,
        "supported_locales"
      )
        ? parseStaticStoreLocaleArray(update.supported_locales)
        : store.supported_locales,
      default_sales_channel_id: Object.prototype.hasOwnProperty.call(
        update,
        "default_sales_channel_id"
      )
        ? getNullableStringValue(update, "default_sales_channel_id")
        : store.default_sales_channel_id,
      default_region_id: Object.prototype.hasOwnProperty.call(
        update,
        "default_region_id"
      )
        ? getNullableStringValue(update, "default_region_id")
        : store.default_region_id,
      default_location_id: Object.prototype.hasOwnProperty.call(
        update,
        "default_location_id"
      )
        ? getNullableStringValue(update, "default_location_id")
        : store.default_location_id,
      metadata: Object.prototype.hasOwnProperty.call(update, "metadata")
        ? getRecordValue(update, "metadata") ?? null
        : store.metadata,
      updated_at: new Date(Date.UTC(2026, 5, 21, 0, 30, 0)).toISOString(),
    }

    updatedStores.push(nextStore)
    return nextStore
  })

  return updatedStores
}

function validateStaticStoreCurrenciesUpdate(input: unknown): void {
  if (!Array.isArray(input) || input.length === 0) {
    return
  }

  const hasDefault = input.some(
    (currency) => isRecord(currency) && currency.is_default === true
  )

  if (!hasDefault) {
    throw new MedusaError(
      MedusaError.Types.INVALID_DATA,
      "There should be a default currency set for the store"
    )
  }
}

