function getStaticProductVariantById(
  variantId: string
): StaticProductVariant | undefined {
  return staticProducts
    .filter((product) => !product.deleted_at)
    .flatMap((product) => product.variants)
    .find((variant) => variant.id === variantId)
}

function getStaticProductByVariantId(
  variantId: string
): StaticProduct | undefined {
  return staticProducts
    .filter((product) => !product.deleted_at)
    .find((product) =>
      product.variants.some((variant) => variant.id === variantId)
    )
}

function createStaticSalesChannelsFromWorkflowInput(
  input: unknown
): StaticSalesChannel[] {
  const salesChannelsData =
    isRecord(input) && Array.isArray(input.salesChannelsData)
      ? input.salesChannelsData
      : []

  return salesChannelsData.flatMap((salesChannel): StaticSalesChannel[] => {
    if (!isRecord(salesChannel) || typeof salesChannel.name !== "string") {
      return []
    }

    const created = createStaticSalesChannelFromInput(salesChannel)
    staticSalesChannels.push(created)
    return [created]
  })
}

