function updateStaticSalesChannelsFromWorkflowInput(
  input: unknown
): StaticSalesChannel[] {
  if (!isRecord(input)) {
    return []
  }

  const selector = getRecordValue(input, "selector")
  const update = getRecordValue(input, "update")
  const idFilters = normalizeStringFilter(selector?.id)

  if (!update || idFilters.length === 0) {
    return []
  }

  const updatedSalesChannels: StaticSalesChannel[] = []
  staticSalesChannels = staticSalesChannels.map((salesChannel) => {
    if (!idFilters.includes(salesChannel.id)) {
      return salesChannel
    }

    const updated: StaticSalesChannel = {
      ...salesChannel,
      name: getStringValue(update, "name") ?? salesChannel.name,
      description: Object.prototype.hasOwnProperty.call(update, "description")
        ? getNullableStringValue(update, "description")
        : salesChannel.description,
      is_disabled: Object.prototype.hasOwnProperty.call(update, "is_disabled")
        ? update.is_disabled === true
        : salesChannel.is_disabled,
      metadata: Object.prototype.hasOwnProperty.call(update, "metadata")
        ? getRecordValue(update, "metadata") ?? null
        : salesChannel.metadata,
      updated_at: new Date(Date.UTC(2026, 5, 21, 0, 40, 0)).toISOString(),
    }

    updatedSalesChannels.push(updated)
    return updated
  })

  return updatedSalesChannels
}

function deleteStaticSalesChannelsFromWorkflowInput(input: unknown): void {
  if (!isRecord(input)) {
    return
  }

  const ids = normalizeStringFilter(input.ids)
  const defaultSalesChannelIds = ids.filter(
    (id) =>
      id === "sc_worker_http_proof" ||
      staticStores.some((store) => store.default_sales_channel_id === id)
  )

  if (defaultSalesChannelIds.length > 0) {
    throw new MedusaError(
      MedusaError.Types.NOT_ALLOWED,
      `Cannot delete default sales channels: ${defaultSalesChannelIds.join(
        ", "
      )}`
    )
  }

  staticSalesChannels = staticSalesChannels.filter(
    (salesChannel) => !ids.includes(salesChannel.id)
  )
  staticProductSalesChannelLinks = staticProductSalesChannelLinks.filter(
    (link) => !ids.includes(link.sales_channel_id)
  )
  staticApiKeySalesChannelLinks = staticApiKeySalesChannelLinks.filter(
    (link) => !ids.includes(link.sales_channel_id)
  )
  staticLocationSalesChannelLinks = staticLocationSalesChannelLinks.filter(
    (link) => !ids.includes(link.sales_channel_id)
  )
}

function createStaticSalesChannelFromInput(
  input: Record<string, unknown>
): StaticSalesChannel {
  const now = new Date(
    Date.UTC(2026, 5, 21, 0, 35, ++staticSalesChannelSequence)
  ).toISOString()

  return {
    id: `sc_worker_${String(staticSalesChannelSequence).padStart(24, "0")}`,
    name: getStringValue(input, "name") ?? "Worker Sales Channel",
    description: getNullableStringValue(input, "description"),
    is_disabled: input.is_disabled === true,
    metadata: getRecordValue(input, "metadata") ?? null,
    created_at: now,
    updated_at: now,
    deleted_at: null,
  }
}

function getStaticLocaleName(localeCode: string): string {
  const displayNames = new Intl.DisplayNames(["en"], {
    type: "language",
  })
  const name = displayNames.of(localeCode)

  return name ?? localeCode
}

function normalizeStringFilter(value: unknown): string[] {
  if (typeof value === "string") {
    return [value]
  }

  if (Array.isArray(value)) {
    return value.filter((id): id is string => typeof id === "string")
  }

  return []
}

function normalizeStaticSearchParamList(value: string | null): string[] {
  if (value === null) {
    return []
  }

  return value
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item.length > 0)
}

function normalizeStringOperatorFilter(value: unknown): string[] {
  if (!isRecord(value)) {
    return []
  }

  return [
    ...normalizeStringFilter(value.$eq),
    ...normalizeStringFilter(value.$in),
  ]
}

function getCalculatedPriceContext(
  context: Record<string, unknown> | undefined
): Record<string, unknown> | null {
  const variantsContext = getRecordValue(context, "variants")
  return getRecordValue(variantsContext, "calculated_price") ?? null
}

function getRecordValue(
  parent: Record<string, unknown> | undefined,
  key: string
): Record<string, unknown> | undefined {
  const value = parent?.[key]
  if (isRecord(value)) {
    return value
  }

  return undefined
}

function getStringValue(
  parent: Record<string, unknown>,
  key: string
): string | undefined {
  const value = parent[key]
  return typeof value === "string" ? value : undefined
}

function getStringArrayValue(
  parent: Record<string, unknown>,
  key: string
): string[] {
  const value = parent[key]
  if (!Array.isArray(value)) {
    return []
  }

  return value.filter((item): item is string => typeof item === "string")
}

function getNullableStringValue(
  parent: Record<string, unknown>,
  key: string
): string | null {
  const value = parent[key]
  return typeof value === "string" ? value : null
}

function getNullableNumberValue(
  parent: Record<string, unknown>,
  key: string
): number | null {
  const value = parent[key]
  return typeof value === "number" ? value : null
}

function getNumberValue(
  parent: Record<string, unknown>,
  key: string
): number | undefined {
  const value = parent[key]
  return typeof value === "number" ? value : undefined
}

function getNumericValue(
  parent: Record<string, unknown>,
  key: string
): number | undefined {
  const value = parent[key]
  if (typeof value === "number") {
    return value
  }

  if (typeof value === "string") {
    const parsed = Number(value)
    return Number.isFinite(parsed) ? parsed : undefined
  }

  return undefined
}

function getNumberSearchParam(
  searchParams: URLSearchParams,
  key: string
): number | undefined {
  const value = searchParams.get(key)
  if (value === null || value.trim() === "") {
    return undefined
  }

  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed : undefined
}

function getBooleanValue(
  parent: Record<string, unknown>,
  key: string
): boolean | undefined {
  const value = parent[key]
  return typeof value === "boolean" ? value : undefined
}

function isArrayValue(value: unknown): value is unknown[] {
  return Array.isArray(value)
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value)
  )
}

function hasOwn<TObject extends object, TKey extends PropertyKey>(
  value: TObject,
  key: TKey
): value is TObject & Record<TKey, unknown> {
  return Object.prototype.hasOwnProperty.call(value, key)
}
